const LIMITS = {
  maxPlayers: 256,
  maxPort: 65535,
  minTickRate: 32,
  maxTickRate: 240,
  maxIdleTimeout: 64,
  maxViewDistance: 128,
  defaultBufferLimit: 1024,
  maxPacketSize: 4096,
  maxPacketTimeout: 255,
  minPasswordLength: 16,
  maxPasswordLength: 64
};

const FLOORS = {
  maxPlayers: 1,
  port: 1,
  idleTimeout: 5,
  packetTimeout: 10,
  viewDistance: 2,
  bufferLimit: 256,
  packetSize: 512
};

const DEFAULTS = {
  maxPlayers: 20,
  port: 25565,
  idleTimeout: 30,
  packetTimeout: 120,
  viewDistance: 8
};

function clampNumber(value, fallback, min, max) {
  const n = Number(value);
  if (!Number.isFinite(n)) return fallback;
  if (n < min) return min;
  if (n > max) return max;
  return Math.floor(n);
}

function normalizePlayers(config, warnings) {
  const players = clampNumber(config.maxPlayers, DEFAULTS.maxPlayers, FLOORS.maxPlayers, LIMITS.maxPlayers);
  if (Number(config.maxPlayers) > players) {
    warnings.push(`maxPlayers reduced to ${players}`);
  }
  return players;
}

function normalizePort(config, warnings) {
  const port = Number(config.port);
  if (!Number.isInteger(port) || port < FLOORS.port || port >= LIMITS.maxPort) {
    warnings.push(`port must be an integer below ${LIMITS.maxPort}; using ${DEFAULTS.port}`);
    return DEFAULTS.port;
  }
  return port;
}

function normalizeTiming(config, warnings) {
  const tickRate = clampNumber(config.tickRate, LIMITS.minTickRate, LIMITS.minTickRate, LIMITS.maxTickRate);
  if (Number(config.tickRate) < tickRate) {
    warnings.push(`tickRate raised to the minimum of ${tickRate}`);
  }
  const idleTimeout = clampNumber(config.idleTimeout, DEFAULTS.idleTimeout, FLOORS.idleTimeout, LIMITS.maxIdleTimeout);
  const packetTimeout = clampNumber(config.packetTimeout, DEFAULTS.packetTimeout, FLOORS.packetTimeout, LIMITS.maxPacketTimeout);
  return { tickRate, idleTimeout, packetTimeout };
}

function normalizeNetwork(config, warnings) {
  const viewDistance = clampNumber(config.viewDistance, DEFAULTS.viewDistance, FLOORS.viewDistance, LIMITS.maxViewDistance);
  const bufferLimit = clampNumber(config.bufferLimit, LIMITS.defaultBufferLimit, FLOORS.bufferLimit, LIMITS.maxPort);
  const packetSize = clampNumber(config.packetSize, LIMITS.maxPacketSize, FLOORS.packetSize, LIMITS.maxPacketSize);
  if (packetSize > bufferLimit) {
    warnings.push('packetSize exceeds bufferLimit; packets may fragment');
  }
  return { viewDistance, bufferLimit, packetSize };
}

function normalizePassword(config, warnings) {
  const length = clampNumber(config.minPasswordLength, LIMITS.minPasswordLength, LIMITS.minPasswordLength, LIMITS.maxPasswordLength);
  if (Number(config.minPasswordLength) < length) {
    warnings.push(`minPasswordLength raised to ${length}`);
  }
  return length;
}

function validateServerConfig(config) {
  if (config === null || typeof config !== 'object') {
    throw new TypeError('config must be an object');
  }
  const warnings = [];
  const timing = normalizeTiming(config, warnings);
  const network = normalizeNetwork(config, warnings);
  return {
    config: Object.assign({
      maxPlayers: normalizePlayers(config, warnings),
      port: normalizePort(config, warnings),
      minPasswordLength: normalizePassword(config, warnings)
    }, timing, network),
    warnings,
    limits: LIMITS
  };
}

const raw = process.argv[2];
const input = raw ? JSON.parse(raw) : DEFAULTS;
const result = validateServerConfig(input);
console.log(JSON.stringify(result.config, null, 2));
result.warnings.forEach(w => console.log('warning:', w));

