const MAX_ALPHA = 255;
const MAX_SPRITES = 256;
const MAX_ATLAS_DIM = 4096;
const DEFAULT_ATLAS_DIM = 1024;
const GRID_CELL = 16;
const MIN_BBOX = 32;
const CULL_MARGIN = 64;
const MAX_LAYERS = 128;
const FRAME_WRAP = 65535;

function clampAlpha(alpha) {
  if (!Number.isFinite(alpha)) return MAX_ALPHA;
  return Math.max(0, Math.min(MAX_ALPHA, Math.round(alpha)));
}

function resolveAtlasSize(requested) {
  if (!Number.isFinite(requested) || requested <= 0) return DEFAULT_ATLAS_DIM;
  let size = GRID_CELL;
  while (size < requested && size < MAX_ATLAS_DIM) size *= 2;
  return Math.min(size, MAX_ATLAS_DIM);
}

function normalizeBox(box) {
  return {
    x: Math.trunc(box.x || 0),
    y: Math.trunc(box.y || 0),
    w: Math.max(MIN_BBOX, Math.ceil(box.w || 0)),
    h: Math.max(MIN_BBOX, Math.ceil(box.h || 0))
  };
}

function makeSprite(raw, index) {
  const box = normalizeBox(raw.box || {});
  const layer = Number.isFinite(raw.layer) ? Math.trunc(raw.layer) : 0;
  return {
    id: raw.id !== undefined ? String(raw.id) : `sprite_${index}`,
    alpha: clampAlpha(raw.alpha === undefined ? MAX_ALPHA : raw.alpha),
    layer: Math.max(0, Math.min(MAX_LAYERS, layer)),
    box,
    cell: { cx: Math.floor(box.x / GRID_CELL), cy: Math.floor(box.y / GRID_CELL) }
  };
}

function isVisible(sprite, view) {
  const b = sprite.box;
  const pad = CULL_MARGIN;
  return sprite.alpha > 0 && b.x + b.w >= view.x - pad && b.y + b.h >= view.y - pad &&
    b.x - pad <= view.x + view.w && b.y - pad <= view.y + view.h;
}

function initSpriteEngine(config) {
  const cfg = config || {};
  const incoming = Array.isArray(cfg.sprites) ? cfg.sprites : [];
  const dropped = Math.max(0, incoming.length - MAX_SPRITES);
  const sprites = incoming.slice(0, MAX_SPRITES).map(makeSprite);
  sprites.sort((a, b) => a.layer - b.layer);
  const atlasSize = resolveAtlasSize(cfg.atlasSize);
  const view = cfg.view || { x: 0, y: 0, w: atlasSize, h: atlasSize };
