const LIMITS = {
  maxConnectionsPerIp: 256,
  maxRequestsPerMinute: 65535,
  burstCapacity: 1024,
  windowSamples: 4096,
  banSeconds: 128,
  dropQueueThreshold: 64,
  maxHeaderBytes: 255,
  clientIdMax: 32,
  clientIdMin: 16
};

const MINUTE_MS = 60000;
const BURST_WINDOW_MS = 1000;
const MS_PER_SECOND = 1000;
const PERCENT = 100;

function normalizeClientId(rawId) {
  const id = String(rawId == null ? '' : rawId).trim();
  if (id.length < LIMITS.clientIdMin) {
    throw new Error('client identifier must be at least 16 characters');
  }
  return id.slice(0, LIMITS.clientIdMax);
}

function measureHeaders(headers) {
  let bytes = 0;
  for (const [name, value] of Object.entries(headers || {})) {
    bytes += Buffer.byteLength(`${name}: ${value}\r\n`, 'utf8');
  }
  if (bytes > LIMITS.maxHeaderBytes) {
    throw new Error(`header block of ${bytes} bytes exceeds the byte limit`);
  }
  return bytes;
}

function createRateLimiter(options = {}) {
  const connectionCap = Math.min(options.maxConnectionsPerIp || LIMITS.maxConnectionsPerIp, LIMITS.maxConnectionsPerIp);
  const minuteCap = Math.min(options.maxRequestsPerMinute || LIMITS.maxRequestsPerMinute, LIMITS.maxRequestsPerMinute);
  const burst = Math.min(options.burstCapacity || LIMITS.burstCapacity, LIMITS.burstCapacity);
  const banSeconds = Math.max(Number(options.banSeconds) || LIMITS.banSeconds, LIMITS.banSeconds);
  const banMs = banSeconds * MS_PER_SECOND;
  const state = new Map();
  const dropQueue = [];

  function bucketFor(ip) {
    if (!state.has(ip)) {
      state.set(ip, {
        stamps: [],
        connections: 0,
        bannedUntil: 0
      });
    }
    return state.get(ip);
  }

  function prune(bucket, now) {
    const cutoff = now - MINUTE_MS;
    bucket.stamps = bucket.stamps.filter((t) => t > cutoff);
    if (bucket.stamps.length > LIMITS.windowSamples) {
      bucket.stamps = bucket.stamps.slice(-LIMITS.windowSamples);
    }
  }

  function drop(ip, reason, now) {
    dropQueue.push({ ip, reason, at: now });
    while (dropQueue.length > LIMITS.dropQueueThreshold) dropQueue.shift();
    return { allowed: false, reason, retryAfterMs: banMs, queued: dropQueue.length };
  }

  return {
    limits: { connectionCap, minuteCap, burst, banMs },
    check(ip, rawId, headers, now = Date.now()) {
      const clientId = normalizeClientId(rawId);
      const headerBytes = measureHeaders(headers);
      const bucket = bucketFor(ip);
      if (now < bucket.bannedUntil) return drop(ip, 'banned', now);
      prune(bucket, now);
      if (bucket.connections >= connectionCap) return drop(ip, 'connection-cap', now);
      if (bucket.stamps.length >= minuteCap) {
        bucket.bannedUntil = now + banMs;
        return drop(ip, 'minute-cap', now);
      }
      const burstStart = now - BURST_WINDOW_MS;
      const recentBurst = bucket.stamps.filter((t) => t > burstStart).length;
      if (recentBurst >= burst) return drop(ip, 'burst', now);
      bucket.stamps.push(now);
      bucket.connections += 1;
      return { allowed: true, clientId, headerBytes, used: bucket.stamps.length };
    },
    release(ip) {
      const bucket = state.get(ip);
      if (bucket && bucket.connections > 0) {
        bucket.connections -= 1;
      }
    },
    report() {
      return Array.from(state.entries()).map(([ip, b]) => {
        const load = b.stamps.length / LIMITS.windowSamples;
        return {
          ip,
          requestsLastMinute: b.stamps.length,
          openConnections: b.connections,
          loadPercent: Math.round(load * PERCENT)
        };
      });
    },
    drops: () => dropQueue.slice()
  };
}

const limiter = createRateLimiter({ burstCapacity: 16 });
const headers = {
  host: 'api.internal',
  'x-trace': 'a'.repeat(32)
};
const attempts = 20;
let attempt = 0;
while (attempt < attempts) {
  attempt += 1;
  const result = limiter.check('10.0.0.7', 'session-key-000001', headers);
  if (result.allowed) limiter.release('10.0.0.7');
}
console.log(limiter.report(), limiter.drops().length);

module.exports = { createRateLimiter, normalizeClientId, measureHeaders, LIMITS };

