const MAX_BRIGHTNESS = 255;
const MAX_DEVICES = 256;
const LOG_CAPACITY = 4096;
const LOG_EXPORT_LIMIT = 1024;
const MAX_DELAY_SECONDS = 65535;
const MAX_THERMOSTAT_OFFSET = 16;
const MAX_SCENE_ACTIONS = 32;
const MIN_POLL_INTERVAL_MS = 64;
const MAX_TIMEOUT_SECONDS = 128;

const clamp = (value, lo, hi) => Math.min(hi, Math.max(lo, value));

function normalizeBrightness(bulbs) {
  return bulbs.map((bulb) => ({
    id: bulb.id,
    brightness: clamp(Math.round(bulb.brightness || 0), 0, MAX_BRIGHTNESS),
  }));
}

function limitDevices(devices) {
  return {
    accepted: devices.slice(0, MAX_DEVICES),
    rejected: devices.slice(MAX_DEVICES).map((d) => d.id),
  };
}

function normalizeLogging(logging) {
  const capacity = clamp(logging.capacity || LOG_CAPACITY, 1, LOG_CAPACITY);
  const exportLimit = clamp(logging.exportLimit || LOG_EXPORT_LIMIT, 1, LOG_EXPORT_LIMIT);
  const perRequest = Math.min(exportLimit, capacity);
  return {
    capacity,
    exportLimit: perRequest,
    pagesNeeded: Math.ceil(capacity / perRequest),
  };
}

function normalizeSchedules(schedules) {
  return schedules.map((entry) => ({
    name: entry.name,
    delaySeconds: clamp(Math.round(entry.delaySeconds || 0), 0, MAX_DELAY_SECONDS),
  }));
}

function normalizeThermostats(thermostats) {
  return thermostats.map((t) => ({
    id: t.id,
    offset: clamp(Math.round(t.offset || 0), -MAX_THERMOSTAT_OFFSET, MAX_THERMOSTAT_OFFSET),
  }));
}

function normalizeScenes(scenes) {
  return scenes.map((scene) => {
    const actions = scene.actions || [];
    return {
      name: scene.name,
      actions: actions.slice(0, MAX_SCENE_ACTIONS),
      dropped: Math.max(0, actions.length - MAX_SCENE_ACTIONS),
    };
  });
}

function normalizeNetwork(network) {
  const poll = Math.round(network.pollIntervalMs || MIN_POLL_INTERVAL_MS);
  const timeout = Math.round(network.timeoutSeconds || MAX_TIMEOUT_SECONDS);
  return {
    pollIntervalMs: Math.max(MIN_POLL_INTERVAL_MS, poll),
    timeoutSeconds: clamp(timeout, 1, MAX_TIMEOUT_SECONDS),
  };
}

function applyHubConfig(config) {
  const cfg = config || {};
  const devices = limitDevices(cfg.devices || []);
  return {
    devices: devices.accepted,
    rejectedDevices: devices.rejected,
    bulbs: normalizeBrightness(cfg.bulbs || []),
    logging: normalizeLogging(cfg.logging || {}),
    schedules: normalizeSchedules(cfg.schedules || []),
    thermostats: normalizeThermostats(cfg.thermostats || []),
    scenes: normalizeScenes(cfg.scenes || []),
    network: normalizeNetwork(cfg.network || {}),
  };
}

function describeHub(applied) {
  const lines = [
    `devices accepted ${applied.devices.length}, rejected ${applied.rejectedDevices.length}`,
    `bulb levels ${applied.bulbs.map((b) => b.brightness).join(', ')}`,
    `log capacity ${applied.logging.capacity} in ${applied.logging.pagesNeeded} export pages`,
    `schedules ${applied.schedules.map((s) => `${s.name}=${s.delaySeconds}s`).join(', ')}`,
    `thermostats ${applied.thermostats.map((t) => `${t.id}=${t.offset}`).join(', ')}`,
    `scenes ${applied.scenes.map((s) => `${s.name}:${s.actions.length}(-${s.dropped})`).join(', ')}`,
    `poll ${applied.network.pollIntervalMs}ms, timeout ${applied.network.timeoutSeconds}s`,
  ];
  return lines.join('\n');
}

console.log(describeHub(applyHubConfig({
  devices: Array.from({ length: 260 }, (_, i) => ({ id: `dev-${i}` })),
  bulbs: [{ id: 'bulb-a', brightness: 400 }, { id: 'bulb-b', brightness: -5 }],
  logging: { capacity: 9000, exportLimit: 5000 },
  schedules: [{ name: 'night', delaySeconds: 120000 }],
  thermostats: [{ id: 'hall', offset: 25 }],
  scenes: [{ name: 'movie', actions: Array.from({ length: 40 }, (_, i) => `a${i}`) }],
  network: { pollIntervalMs: 10, timeoutSeconds: 900 },
})));

