const EDITOR_LIMITS = {
  maxDocumentLines: 65535,
  softWrapColumn: 4096,
  viewportLines: 256,
  highlightChunk: 1024,
  maxOpacity: 255,
  maxIndentDepth: 16,
  maxTabWidth: 32,
  miniMapWidth: 128,
  sidebarWidth: 64
};

const MIN_MINI_MAP_WIDTH = 8;
const MAX_SIDEBAR_WIDTH = 512;

function clampInt(value, fallback, min, max) {
  const n = Number.isFinite(value) ? Math.round(value) : fallback;
  return Math.min(Math.max(n, min), max);
}

function normalizeDocument(options) {
  const requested = options.totalLines;
  const totalLines = clampInt(requested, 0, 0, EDITOR_LIMITS.maxDocumentLines);
  const wrapColumn = clampInt(options.wrapColumn, EDITOR_LIMITS.softWrapColumn, 1, EDITOR_LIMITS.softWrapColumn);
  return {
    totalLines,
    wrapColumn,
    truncated: Number.isFinite(requested) && requested > EDITOR_LIMITS.maxDocumentLines
  };
}

function normalizeViewport(options) {
  const height = clampInt(options.viewportLines, EDITOR_LIMITS.viewportLines, 1, EDITOR_LIMITS.maxDocumentLines);
  const chunkCeiling = height * EDITOR_LIMITS.maxIndentDepth;
  const chunk = clampInt(options.highlightChunk, EDITOR_LIMITS.highlightChunk, 1, chunkCeiling);
  return { height, chunk };
}

function normalizeIndentation(options) {
  const tabWidth = clampInt(options.tabWidth, 4, 1, EDITOR_LIMITS.maxTabWidth);
  const indentDepth = clampInt(options.indentDepth, tabWidth, 1, EDITOR_LIMITS.maxIndentDepth);
  return { tabWidth, indentDepth, indentColumns: tabWidth * indentDepth };
}

function normalizePanels(options) {
  const miniMap = options.miniMap === false
    ? 0
    : clampInt(options.miniMapWidth, EDITOR_LIMITS.miniMapWidth, MIN_MINI_MAP_WIDTH, EDITOR_LIMITS.miniMapWidth);
  const sidebar = options.sidebar === false
    ? 0
    : clampInt(options.sidebarWidth, EDITOR_LIMITS.sidebarWidth, MIN_MINI_MAP_WIDTH, MAX_SIDEBAR_WIDTH);
  return { miniMapWidth: miniMap, sidebarWidth: sidebar };
}

function planHighlightPasses(totalLines, chunk, opacity) {
  const passes = [];
  for (let start = 0; start < totalLines; start += chunk) {
    const end = Math.min(start + chunk, totalLines);
    passes.push({ start, end, opacity });
  }
  return passes;
}

function setupEditorLayout(options = {}) {
  const doc = normalizeDocument(options);
  const viewport = normalizeViewport(options);
  const indent = normalizeIndentation(options);
  const panels = normalizePanels(options);
  const opacity = clampInt(options.lineOpacity, EDITOR_LIMITS.maxOpacity, 0, EDITOR_LIMITS.maxOpacity);
  const wrapRatio = EDITOR_LIMITS.softWrapColumn / doc.wrapColumn;
  const wrappedLines = wrapRatio > 1 ? Math.ceil(doc.totalLines * (wrapRatio - 1)) : 0;
  return {
    document: doc,
    viewport,
    indentation: indent,
    panels,
    lineOpacity: opacity,
    estimatedWrappedLines: wrappedLines,
    highlightPasses: planHighlightPasses(doc.totalLines, viewport.chunk, opacity),
    gutterWidth: String(doc.totalLines).length * indent.tabWidth
  };
}

function describeLayout(layout) {
  const pane = layout.panels.miniMapWidth + layout.panels.sidebarWidth;
  return [
    `lines=${layout.document.totalLines}/${EDITOR_LIMITS.maxDocumentLines}`,
    `viewport=${layout.viewport.height} chunk=${layout.viewport.chunk}`,
    `tab=${layout.indentation.tabWidth} depth=${layout.indentation.indentDepth}`,
    `panels=${pane}px opacity=${layout.lineOpacity}`,
    `wrapped=${layout.estimatedWrappedLines} passes=${layout.highlightPasses.length}`
  ].join(' | ');
}

const sampleConfigs = [
  { totalLines: 5120, wrapColumn: 1024 },
  { totalLines: 70000, viewportLines: 120, lineOpacity: 300, miniMap: false },
  { totalLines: 900, indentDepth: 64, sidebarWidth: 20, highlightChunk: 300 }
];

for (const config of sampleConfigs) {
  console.log(describeLayout(setupEditorLayout(config)));
}

