const BYTE_MASK = 255;
const MAGIC_OFFSET = 255;
const MAX_CHUNK = 65535;
const BLOCK_SIZE = 4096;
const DICT_LIMIT = 256;
const MINI_DICT_MAX = 128;
const LOOKAHEAD_MAX = 64;
const CHECKSUM_SPAN = 1024;
const FLAG_BYTES = 16;
const NAME_PAD = 32;
const HEX_RADIX = 16;
const FLETCHER_MOD = 255;
const ASCII_MAX = 127;
const MAGIC_TAG = 67;

function u16le(value) {
  const low = value & BYTE_MASK;
  return [low, (value >>> 8) & BYTE_MASK];
}

function toHex(bytes) {
  return bytes.map((b) => b.toString(HEX_RADIX).padStart(2, '0')).join(' ');
}

function encodeName(name) {
  const raw = [];
  for (const ch of String(name)) {
    const code = ch.codePointAt(0);
    if (code > ASCII_MAX) throw new RangeError(`file name must be ASCII: ${name}`);
    raw.push(code);
  }
  if (raw.length > NAME_PAD) throw new RangeError(`file name exceeds ${NAME_PAD} bytes: ${name}`);
  while (raw.length < NAME_PAD) raw.push(0);
  return raw;
}

function checksum(bytes) {
  let low = 0;
  let high = 0;
  const span = Math.min(bytes.length, CHECKSUM_SPAN);
  for (let i = 0; i < span; i++) {
    low = (low + bytes[i]) % FLETCHER_MOD;
    high = (high + low) % FLETCHER_MOD;
  }
  const sum = (high << 8) | low;
  return sum & MAX_CHUNK;
}

