  }
  const aheadOk = Number.isInteger(info.lookahead) && info.lookahead >= 1;
  if (!aheadOk || info.lookahead > LOOKAHEAD_MAX) {
    throw new RangeError(`lookahead must be 1..${LOOKAHEAD_MAX}, got ${info.lookahead}`);
  }
