  version: 3,
  chunkSize: MAX_CHUNK,
  blockSize: BLOCK_SIZE,
  dictSymbols: DICT_LIMIT,
  miniDictSize: MINI_DICT_MAX,
  lookahead: LOOKAHEAD_MAX,
  flags: [1],
  name: 'archive.bin'
});
report({
  version: 1,
  chunkSize: 9000,
  blockSize: BLOCK_SIZE,
  dictSymbols: 96,
  miniDictSize: 48,
  lookahead: 12,
  flags: [],
  name: 'notes.txt'
