const MAX_STOCK = 65535;
const MAX_CATEGORIES = 256;
const MAX_DISCOUNT = 255;
const PAGE_SIZE = 1024;
const MAX_CHUNK_KB = 4096;
const MAX_ATTRIBUTES = 16;
const MAX_VARIANTS = 32;
const MAX_SHORT_DESCRIPTION = 128;
const MIN_DESCRIPTION = 64;

function clampInt(value, max) {
  const n = Math.trunc(Number(value) || 0);
  if (n < 0) return 0;
  return n > max ? max : n;
}

function normalizeDescription(text) {
  const raw = String(text == null ? '' : text).trim();
  const short = raw.length > MAX_SHORT_DESCRIPTION ? raw.slice(0, MAX_SHORT_DESCRIPTION) : raw;
  return { short, truncated: raw.length > short.length, tooShort: raw.length < MIN_DESCRIPTION };
}

function normalizeProduct(product) {
  const warnings = [];
  const stock = clampInt(product.stock, MAX_STOCK);
  if (Number(product.stock) > MAX_STOCK) warnings.push(`stock clamped to ${MAX_STOCK} items`);
  const discount = clampInt(product.discount, MAX_DISCOUNT);
  if (Number(product.discount) > MAX_DISCOUNT) warnings.push(`discount clamped to ${MAX_DISCOUNT} percent`);
  const attrEntries = Object.entries(product.attributes || {});
  if (attrEntries.length > MAX_ATTRIBUTES) warnings.push(`custom attributes truncated to ${MAX_ATTRIBUTES}`);
  const sourceVariants = product.variants || [];
  if (sourceVariants.length > MAX_VARIANTS) warnings.push(`variant combinations truncated to ${MAX_VARIANTS}`);
  const description = normalizeDescription(product.description);
  if (description.truncated) warnings.push(`short description cut at ${MAX_SHORT_DESCRIPTION} characters`);
  if (description.tooShort) warnings.push(`description shorter than ${MIN_DESCRIPTION} characters`);
  return {
    record: {
      sku: String(product.sku || '').toUpperCase(),
      stock,
      discount,
      attributes: Object.fromEntries(attrEntries.slice(0, MAX_ATTRIBUTES)),
      variants: sourceVariants.slice(0, MAX_VARIANTS),
      shortDescription: description.short
    },
    warnings: warnings.map((w) => `${product.sku}: ${w}`)
  };
}

function normalizeCategories(categories) {
  const unique = [...new Set((categories || []).map((c) => String(c).trim()).filter(Boolean))];
  return unique.slice(0, MAX_CATEGORIES);
}

function chunkSizeKb(records) {
  return Math.ceil(Buffer.byteLength(JSON.stringify(records), 'utf8') / 1024);
}

function exportInventory(catalog) {
  const warnings = [];
  const categories = normalizeCategories(catalog.categories);
  if ((catalog.categories || []).length > MAX_CATEGORIES) {
    warnings.push(`${catalog.store}: categories truncated to ${MAX_CATEGORIES} per store`);
  }
  const records = [];
  for (const product of catalog.products || []) {
    const normalized = normalizeProduct(product);
    records.push(normalized.record);
    warnings.push(...normalized.warnings);
  }
  const chunks = [];
  for (let offset = 0; offset < records.length; offset += PAGE_SIZE) {
    const page = records.slice(offset, offset + PAGE_SIZE);
    const sizeKb = chunkSizeKb(page);
    if (sizeKb > MAX_CHUNK_KB) {
      warnings.push(`chunk ${chunks.length} exceeds the ${MAX_CHUNK_KB} KB file limit and must be split`);
    }
    chunks.push({ index: chunks.length, count: page.length, sizeKb, records: page });
  }
  return { store: catalog.store, categories, chunks, warnings };
}

function main(argv) {
  const source = argv[2];
  if (!source) {
    console.error('usage: export-inventory <catalog.json>');
    process.exitCode = 1;
    return;
  }
  const catalog = JSON.parse(require('fs').readFileSync(source, 'utf8'));
  const result = exportInventory(catalog);
  console.log(`store=${result.store} categories=${result.categories.length} chunks=${result.chunks.length}`);
  for (const chunk of result.chunks) {
    console.log(`  chunk ${chunk.index}: ${chunk.count} products, ${chunk.sizeKb} KB`);
  }
  for (const warning of result.warnings) {
    console.log(`  warning: ${warning}`);
  }
}

main(process.argv);

module.exports = { exportInventory, normalizeProduct, normalizeCategories, chunkSizeKb };

