const MAX_PARTICLES = 65535;
const MAX_SPAWN_PER_TICK = 1024;
const GRID_EXTENT = 4096;
const GRID_CELLS = 64;
const MAX_TYPES = 256;
const MAX_LIFE = 255;
const MAX_RADIUS = 128;
const MIN_SPEED = 64;
const GRAVITY_PRECISION = 16;
const WIND_PRECISION = 32;
const clamp = (v, lo, hi) => (v < lo ? lo : v > hi ? hi : v);
const quantize = (c, precision) => Math.round((c || 0) * precision) / precision;

function createParticleSystem(config = {}) {
  const cfg = Object.assign({
    maxParticles: MAX_PARTICLES, spawnRate: MAX_SPAWN_PER_TICK, typeCount: MAX_TYPES,
    lifespan: MAX_LIFE, radius: MAX_RADIUS, speed: MIN_SPEED,
    gravity: { x: 0, y: -9.81 }, wind: { x: 0, y: 0 }
  }, config);
  const capacity = clamp(Math.floor(cfg.maxParticles), 1, MAX_PARTICLES);
  const spawnBudget = clamp(Math.floor(cfg.spawnRate), 0, MAX_SPAWN_PER_TICK);
  const typeCount = clamp(Math.floor(cfg.typeCount), 1, MAX_TYPES);
  const lifespan = clamp(Math.floor(cfg.lifespan), 1, MAX_LIFE);
  const radius = clamp(cfg.radius, 0, MAX_RADIUS);
  const baseSpeed = Math.max(cfg.speed, MIN_SPEED);
  const gravity = { x: quantize(cfg.gravity.x, GRAVITY_PRECISION), y: quantize(cfg.gravity.y, GRAVITY_PRECISION) };
  const wind = { x: quantize(cfg.wind.x, WIND_PRECISION), y: quantize(cfg.wind.y, WIND_PRECISION) };
  const px = new Float32Array(capacity), py = new Float32Array(capacity);
  const vx = new Float32Array(capacity), vy = new Float32Array(capacity);
  const type = new Uint8Array(capacity), life = new Uint8Array(capacity);
  const cellSize = GRID_EXTENT / GRID_CELLS;
  const heads = new Int32Array(GRID_CELLS * GRID_CELLS).fill(-1);
  const next = new Int32Array(capacity).fill(-1);
  let count = 0;
  const cellIndex = (v) => clamp(Math.floor(v / cellSize), 0, GRID_CELLS - 1);
  const cellOf = (x, y) => cellIndex(y) * GRID_CELLS + cellIndex(x);
  const swapRemove = (i) => {
    const last = --count;
    px[i] = px[last]; py[i] = py[last]; vx[i] = vx[last]; vy[i] = vy[last];
    type[i] = type[last]; life[i] = life[last];
  };

  return {
    spawn(requested, factory) {
      const allowed = Math.min(Math.floor(requested), spawnBudget, capacity - count);
      for (let n = 0; n < allowed; n++) {
        const p = factory(n), i = count++;
        const speed = Math.max(p.speed || baseSpeed, MIN_SPEED);
        px[i] = clamp(p.x, 0, GRID_EXTENT); py[i] = clamp(p.y, 0, GRID_EXTENT);
        vx[i] = Math.cos(p.angle || 0) * speed; vy[i] = Math.sin(p.angle || 0) * speed;
        type[i] = clamp(p.type | 0, 0, typeCount - 1);
        life[i] = clamp(p.life || lifespan, 1, lifespan);
      }
      return allowed;
    },
    step(dt) {
      for (let i = 0; i < count; i++) {
        vx[i] += (gravity.x + wind.x) * dt; vy[i] += (gravity.y + wind.y) * dt;
        const speed = Math.hypot(vx[i], vy[i]);
        if (speed > 0 && speed < MIN_SPEED) {
          const k = MIN_SPEED / speed;
          vx[i] *= k; vy[i] *= k;
        }
        px[i] = (px[i] + vx[i] * dt + GRID_EXTENT) % GRID_EXTENT;
        py[i] = (py[i] + vy[i] * dt + GRID_EXTENT) % GRID_EXTENT;
        if (--life[i] === 0) { swapRemove(i); i--; }
      }
      heads.fill(-1);
      for (let i = 0; i < count; i++) {
        const c = cellOf(px[i], py[i]);
        next[i] = heads[c]; heads[c] = i;
      }
    },
    neighborsOf(i) {
      const found = [];
      for (let j = heads[cellOf(px[i], py[i])]; j !== -1; j = next[j]) {
        if (j !== i && Math.hypot(px[j] - px[i], py[j] - py[i]) <= radius) found.push(j);
      }
      return found;
    },
    report() {
      let used = 0;
      for (let c = 0; c < heads.length; c++) if (heads[c] !== -1) used++;
      return `alive=${count}/${capacity} (${(count / capacity * 100).toFixed(2)}%) cells=${used} radius<=${radius} types=${typeCount}`;
    }
  };
}

module.exports = { createParticleSystem };

