const HEADER_LENGTH = 16;
const MAX_PACKET_SIZE = 65535;
const CHUNK_SIZE = 1024;
const FRAGMENT_TIMEOUT_MS = 4096;
const KEEPALIVE_SECONDS = 32;
const PRIORITY_MASK = 128;
const ERROR_MASK = 64;
const MAX_MESSAGE_TYPE = 255;

function validateBuffer(buffer) {
  if (!(buffer instanceof Uint8Array)) {
    throw new TypeError('packet must be a Uint8Array');
  }
  if (buffer.length < HEADER_LENGTH) {
    throw new RangeError(`packet too short: ${buffer.length} bytes, header needs ${HEADER_LENGTH}`);
  }
  if (buffer.length > MAX_PACKET_SIZE) {
    throw new RangeError(`packet too large: ${buffer.length} bytes exceeds ${MAX_PACKET_SIZE}`);
  }
}

function readHeader(buffer) {
  const version = buffer[0];
  const deviceId = buffer[1] % 256;
  const flagByte = buffer[2];
  const messageType = buffer[3];
  if (messageType > MAX_MESSAGE_TYPE) {
    throw new RangeError(`message type ${messageType} exceeds maximum ${MAX_MESSAGE_TYPE}`);
  }
  return {
    version,
    deviceId,
    messageType,
    priority: (flagByte & PRIORITY_MASK) !== 0,
    error: (flagByte & ERROR_MASK) !== 0,
    fragmented: (flagByte & 32) !== 0
  };
}

function chunkPayload(payload) {
  const chunks = [];
  for (let offset = 0; offset < payload.length; offset += CHUNK_SIZE) {
    chunks.push(payload.subarray(offset, offset + CHUNK_SIZE));
  }
  return chunks;
}

function parseIoTPacket(buffer) {
  validateBuffer(buffer);
  const header = readHeader(buffer);
  const payload = buffer.subarray(HEADER_LENGTH);
  const chunks = chunkPayload(payload);
  return {
    version: header.version,
    deviceId: header.deviceId,
    messageType: header.messageType,
    flags: { priority: header.priority, error: header.error },
    payloadLength: payload.length,
    chunks,
    waitTimeoutMs: header.fragmented ? FRAGMENT_TIMEOUT_MS : 0,
    keepaliveSeconds: KEEPALIVE_SECONDS
  };
}

function describePacket(packet) {
  const flags = [];
  if (packet.flags.priority) flags.push('PRIORITY');
  if (packet.flags.error) flags.push('ERROR');
  const label = flags.length ? flags.join('|') : 'NONE';
  return `dev=${packet.deviceId} type=${packet.messageType} flags=${label} ` +
    `payload=${packet.payloadLength} chunks=${packet.chunks.length} ` +
    `timeout=${packet.waitTimeoutMs}ms keepalive=${packet.keepaliveSeconds}s`;
}

function buildTestPacket(size, deviceSeed, flagByte, messageType) {
  const buffer = new Uint8Array(size);
  buffer[0] = 1;
  buffer[1] = deviceSeed & 255;
  buffer[2] = flagByte;
  buffer[3] = messageType;
  for (let i = HEADER_LENGTH; i < size; i++) {
    buffer[i] = i % 256;
  }
  return buffer;
}

function main() {
  const fragmentedFlags = PRIORITY_MASK | 32;
  const valid = buildTestPacket(500, 500, fragmentedFlags, 7);
  console.log('valid :', describePacket(parseIoTPacket(valid)));

  const multi = buildTestPacket(4096, 70, ERROR_MASK, 200);
  console.log('multi :', describePacket(parseIoTPacket(multi)));

  for (const bad of [new Uint8Array(4), new Uint8Array(MAX_PACKET_SIZE + 1)]) {
    try {
      parseIoTPacket(bad);
    } catch (err) {
      console.log(`rejected (${bad.length} bytes):`, err.message);
    }
  }
}

main();

module.exports = { parseIoTPacket, describePacket, buildTestPacket };

