const MEMORY_LIMIT = 65535;
const VRAM_BASE = 4096;
const BANK_SIZE = 1024;
const PAGE_SIZE = 256;
const SPRITES_PER_SCANLINE = 64;
const IRQ_VECTOR_OFFSET = 32;
const ROM_PROTECT_MASK = 128;

const registers = new Array(16).fill(0);
const ram = new Uint8Array(MEMORY_LIMIT + 1);
const pageCache = new Map();

let currentBank = 0;
let romStatusFlag = 128;

function validateAddress(address) {
  if (!Number.isInteger(address) || address < 0 || address > MEMORY_LIMIT) {
    throw new RangeError(`address ${address} outside 0..${MEMORY_LIMIT}`);
  }
  return address;
}

function isRomProtected() {
  return (romStatusFlag & ROM_PROTECT_MASK) !== 0;
}

function selectBank(address) {
  const bank = Math.floor(address / BANK_SIZE);
  if (bank !== currentBank) {
    currentBank = bank;
    pageCache.clear();
  }
  return currentBank;
}

function cachePage(address) {
  const page = Math.floor(address / PAGE_SIZE);
  pageCache.set(page, (pageCache.get(page) || 0) + 1);
  return page;
}

function interruptVector(index) {
  return IRQ_VECTOR_OFFSET + index * 2;
}

function mapMemory(address, value, isWrite) {
  validateAddress(address);
  const bank = selectBank(address);
  const page = cachePage(address);
  const region = address >= VRAM_BASE ? 'vram' : 'system';
  if (isWrite) {
    if (region === 'system' && address < VRAM_BASE && isRomProtected()) {
      return { address, bank, page, region, value: ram[address], blocked: true };
    }
    ram[address] = value & 255;
  }
  return { address, bank, page, region, value: ram[address], blocked: false };
}

function loadSpriteRow(scanline, sprites) {
