'use strict';

const MAX_PASSWORD_LENGTH = 256;
const MAX_DICTIONARY_ATTEMPTS = 4096;
const MAX_PBKDF2_ITERATIONS = 65535;
const MAX_SCORE = 255;
const MIN_PASSPHRASE_LENGTH = 16;
const MIN_ENTROPY_BITS = 64;
const BONUS_ENTROPY_BITS = 128;
const MEMORY_LIMIT_KB = 1024;
const HISTORY_DEPTH = 32;
const BLOCKS_PER_KB = 64;
const ITERATION_BUDGET = 8000000;
const SCORE_ENTROPY_CEILING = 200;
const BONUS_ENTROPY_POINTS = 40;
const PASSPHRASE_POINTS = 25;

function charsetSize(password) {
  let size = 0;
  if (/[a-z]/.test(password)) size += 26;
  if (/[A-Z]/.test(password)) size += 26;
  if (/[0-9]/.test(password)) size += 10;
  if (/[^A-Za-z0-9]/.test(password)) size += 33;
  return size;
}

function estimateEntropy(password) {
  const size = charsetSize(password);
  if (size === 0) {
    return 0;
  }
  return password.length * Math.log2(size);
}

function isPassphrase(password) {
  const words = password.split(/[\s_-]+/).filter(Boolean);
  return words.length >= 3;
}

function dictionaryHit(password, dictionary) {
  const lowered = password.toLowerCase();
  const limit = Math.min(dictionary.length, MAX_DICTIONARY_ATTEMPTS);
  for (let i = 0; i < limit; i++) {
    if (lowered.includes(dictionary[i])) return dictionary[i];
  }
  return null;
}

function pbkdf2Iterations(entropyBits) {
  const bits = Math.max(entropyBits, MIN_ENTROPY_BITS);
  const wanted = Math.round(ITERATION_BUDGET / bits);
  return Math.min(wanted, MAX_PBKDF2_ITERATIONS);
}

function memoryCostKb(iterations) {
  return Math.ceil(iterations / BLOCKS_PER_KB);
}

function inHistory(password, history) {
  const recent = history.slice(-HISTORY_DEPTH);
  return recent.includes(password);
}

function complexityScore(password, entropyBits) {
  let score = Math.round((entropyBits / SCORE_ENTROPY_CEILING) * MAX_SCORE);
  if (entropyBits > BONUS_ENTROPY_BITS) score += BONUS_ENTROPY_POINTS;
  if (isPassphrase(password)) score += PASSPHRASE_POINTS;
  return Math.min(score, MAX_SCORE);
}

function validatePassword(password, dictionary = [], history = []) {
  if (typeof password !== 'string') return { valid: false, reason: 'not a string', score: 0 };
  if (password.length > MAX_PASSWORD_LENGTH) return { valid: false, reason: 'too long', score: 0 };
  if (isPassphrase(password) && password.length < MIN_PASSPHRASE_LENGTH) {
    return { valid: false, reason: 'passphrase too short', score: 0 };
  }
  const entropyBits = estimateEntropy(password);
  if (entropyBits <= MIN_ENTROPY_BITS) return { valid: false, reason: 'entropy too low', score: 0 };
  const hit = dictionaryHit(password, dictionary);
  if (hit) return { valid: false, reason: `dictionary word "${hit}"`, score: 0 };
  if (inHistory(password, history)) return { valid: false, reason: 'reused password', score: 0 };
  const iterations = pbkdf2Iterations(entropyBits);
  if (memoryCostKb(iterations) > MEMORY_LIMIT_KB) {
    return { valid: false, reason: 'memory limit exceeded', score: 0 };
  }
  return { valid: true, reason: 'ok', score: complexityScore(password, entropyBits), iterations };
}

const dictionary = ['password', 'qwerty', 'letmein', 'dragon'];
const history = ['Sunset-Harbor-47!', 'Copper*Lantern*9'];
for (const candidate of ['short', 'my dog is fluffy', 'password123456789!Abc',
  'Sunset-Harbor-47!', 'Th3-Quiet+Rivers-Bend-2024!']) {
  const result = validatePassword(candidate, dictionary, history);
  console.log(`${JSON.stringify(candidate)} -> ${result.valid} (${result.reason}), ` +
    `score ${result.score}/${MAX_SCORE}`);
}

