  const effective = userMask & ADMIN_MASK;
  if (effective === ADMIN_MASK) {
    return { granted: true, reason: 'global administrator override' };
  }
  const missing = resource.requiredMask & ~effective;
  if (missing === 0) {
    return { granted: true, reason: `holds ${describeMask(resource.requiredMask)}` };
  }
  return { granted: false, reason: `missing ${describeMask(missing)}` };
}

function login(user) {
  const principal = packPrincipal(user.groupId, user.roleId);
  return {
    name: user.name,
    group: principal >>> 16,
    role: principal & MAX_ROLE_ID,
    mask: maskOf(user.actions),
    sessionTimeout: SESSION_TIMEOUT_SECONDS,
  };
}

