    { name: 'root', groupId: 0, roleId: 1, actions: Object.keys(ACTION_BITS) },
    { name: 'auditor', groupId: 12, roleId: 4200, actions: ['Read'] },
    { name: 'editor', groupId: 12, roleId: MAX_ROLE_ID, actions: ['Read', 'Write'] },
    { name: 'operator', groupId: 200, roleId: 77, actions: ['Read', 'Execute'] },
