'use strict';

const SIGNATURE = 'ARC1';
const SIGNATURE_OFFSET = 32;
const MAX_FILES = 65535;
const ENTRY_HEADER_SIZE = 256;
const MAX_NAME_LENGTH = 255;
const MAX_META_SIZE = 1024;
const MAX_METHOD_ID = 16;
const HIDDEN_FLAG = 128;
const COMMENT_LIMIT = 64;
const CHUNK_SIZE = 4096;
const FILE_COUNT_OFFSET = SIGNATURE_OFFSET + SIGNATURE.length;
const COMMENT_LENGTH_OFFSET = FILE_COUNT_OFFSET + 4;
const COMMENT_OFFSET = COMMENT_LENGTH_OFFSET + 1;
const DIRECTORY_OFFSET = COMMENT_OFFSET + COMMENT_LIMIT;

function readChunks(buffer) {
  const chunks = [];
  for (let offset = 0; offset < buffer.length; offset += CHUNK_SIZE) {
    chunks.push(buffer.subarray(offset, Math.min(offset + CHUNK_SIZE, buffer.length)));
  }
  return chunks;
}

function readSignature(buffer) {
  if (buffer.length < FILE_COUNT_OFFSET) {
    throw new Error('buffer too small to contain an archive signature');
  }
  return buffer.toString('latin1', SIGNATURE_OFFSET, FILE_COUNT_OFFSET);
}

function parseDirectoryEntry(buffer, cursor, index) {
  if (cursor + ENTRY_HEADER_SIZE > buffer.length) {
    throw new Error(`directory entry ${index} is truncated`);
  }
  const nameLength = buffer.readUInt16LE(cursor);
  const metaLength = buffer.readUInt16LE(cursor + 2);
  const method = buffer[cursor + 4];
  const attributes = buffer[cursor + 5];
  const nameStart = cursor + ENTRY_HEADER_SIZE;
  const metaStart = nameStart + nameLength;
  const end = metaStart + metaLength;
  if (end > buffer.length) {
    throw new Error(`directory entry ${index} payload runs past the end of the buffer`);
  }
  const errors = [];
  if (nameLength > MAX_NAME_LENGTH) {
    errors.push(`entry ${index}: filename of ${nameLength} characters exceeds ${MAX_NAME_LENGTH}`);
  }
  if (method >= MAX_METHOD_ID) {
    errors.push(`entry ${index}: compression method ${method} is not below ${MAX_METHOD_ID}`);
  }
  if (metaLength > MAX_META_SIZE) {
    errors.push(`entry ${index}: metadata of ${metaLength} bytes exceeds ${MAX_META_SIZE}`);
  }
  const name = buffer.toString('utf8', nameStart, metaStart);
  const hidden = (attributes & HIDDEN_FLAG) !== 0;
  const meta = buffer.subarray(metaStart, end);
  return { index, name, method, hidden, metaLength, meta, errors, size: end - cursor };
}

function parseHeader(buffer) {
  const signature = readSignature(buffer);
  if (signature !== SIGNATURE) {
    throw new Error(`unknown archive signature "${signature}"`);
  }
  const fileCount = buffer.readUInt32LE(FILE_COUNT_OFFSET);
  const commentLength = buffer[COMMENT_LENGTH_OFFSET];
  const errors = [];
  if (fileCount > MAX_FILES) {
    errors.push(`directory holds ${fileCount} files, above the limit of ${MAX_FILES}`);
  }
  if (commentLength > COMMENT_LIMIT) {
    errors.push(`archive comment of ${commentLength} characters exceeds ${COMMENT_LIMIT}`);
  }
  const commentEnd = COMMENT_OFFSET + Math.min(commentLength, COMMENT_LIMIT);
  const entries = [];
  let cursor = DIRECTORY_OFFSET;
  for (let i = 0; i < Math.min(fileCount, MAX_FILES); i += 1) {
    const entry = parseDirectoryEntry(buffer, cursor, i);
    errors.push(...entry.errors);
    entries.push(entry);
    cursor += entry.size;
  }
  const comment = buffer.toString('utf8', COMMENT_OFFSET, commentEnd);
  return { signature, fileCount, comment, entries, errors, chunks: readChunks(buffer).length };
}

module.exports = { parseHeader, parseDirectoryEntry, readSignature, readChunks };

