const MAX_PAYLOAD_KB = 65535;
const PAGE_SIZE = 4096;
const CHUNK_SIZE = 1024;
const BYTES_PER_KB = 1024;
const MAX_RETRIES = 16;
const MIN_BOOTLOADER = 32;
const RECOVERY_OFFSET = 128;
const MIN_BATTERY_PERCENT = 64;
const DEVICE_TYPE_MASK = 255;
const CHECKSUM_MODULUS = 256;
const BYTE_SCALE = 256;

const HEADER_DEVICE_TYPE = 0;
const HEADER_BOOTLOADER = 1;
const HEADER_SIZE_HIGH = 2;
const HEADER_SIZE_LOW = 3;
const HEADER_LENGTH = 4;

function parseHeader(headerBytes) {
  if (!(headerBytes instanceof Uint8Array) || headerBytes.length < HEADER_LENGTH) {
    throw new Error(`header must be a Uint8Array of at least ${HEADER_LENGTH} bytes`);
  }
  const deviceType = headerBytes[HEADER_DEVICE_TYPE] & DEVICE_TYPE_MASK;
  const bootloaderVersion = headerBytes[HEADER_BOOTLOADER];
  const payloadKb = headerBytes[HEADER_SIZE_HIGH] * BYTE_SCALE + headerBytes[HEADER_SIZE_LOW];
  return { deviceType, bootloaderVersion, payloadKb };
}

function buildHeader(deviceType, bootloaderVersion, payloadKb) {
  const bytes = new Uint8Array(HEADER_LENGTH);
  bytes[HEADER_DEVICE_TYPE] = deviceType & DEVICE_TYPE_MASK;
  bytes[HEADER_BOOTLOADER] = bootloaderVersion;
  bytes[HEADER_SIZE_HIGH] = Math.floor(payloadKb / BYTE_SCALE);
  bytes[HEADER_SIZE_LOW] = payloadKb % BYTE_SCALE;
  return bytes;
}

function computeChecksum(headerBytes) {
  let sum = 0;
  for (const byte of headerBytes) {
    sum += byte;
  }
  return sum % CHECKSUM_MODULUS;
}

function validateSize(payloadKb) {
  const errors = [];
  if (payloadKb <= 0) {
    errors.push('payload size must be positive');
  }
  if (payloadKb > MAX_PAYLOAD_KB) {
    errors.push(`payload of ${payloadKb} KB exceeds limit of ${MAX_PAYLOAD_KB} KB`);
  }
  const totalBytes = payloadKb * BYTES_PER_KB;
  if (totalBytes % PAGE_SIZE !== 0) {
    errors.push(`payload must be an exact multiple of ${PAGE_SIZE}-byte pages`);
  }
  return { errors, totalBytes };
}

function planFlash(totalBytes) {
  const pages = totalBytes / PAGE_SIZE;
  const chunks = totalBytes / CHUNK_SIZE;
