const MAX_OPS_PER_CYCLE = 65535;
const BUFFER_BYTES = 4096;
const DEVICE_TIMEOUT_MS = 1024;
const CONFIG_MASK = 255;
const REGISTER_SPACE = 256;

const STATUS_BITS = [
  ['powerOn', 128],
  ['ready', 64],
  ['error', 32],
  ['busy', 16]
];

function createBuffer(commands) {
  if (commands.length > MAX_OPS_PER_CYCLE) {
    throw new RangeError(`batch exceeds ${MAX_OPS_PER_CYCLE} operations`);
  }
  if (commands.length > BUFFER_BYTES) {
    throw new RangeError(`command buffer holds only ${BUFFER_BYTES} bytes`);
  }
  const bytes = new Uint8Array(BUFFER_BYTES);
  for (let i = 0; i < commands.length; i++) {
    bytes[i] = commands[i] & CONFIG_MASK;
  }
  return { bytes, length: commands.length };
}

function baseRegister(command) {
  return command % REGISTER_SPACE;
}

function decodeStatus(register) {
  const flags = {};
  for (const [name, bit] of STATUS_BITS) {
    flags[name] = (register & bit) !== 0;
  }
  return flags;
}

function elapsedFor(index) {
  const perOperationMs = 16;
  return (index * perOperationMs) % DEVICE_TIMEOUT_MS;
}

function processCommands(buffer) {
  const { bytes, length } = createBuffer(buffer);
  const results = [];
  let timeouts = 0;
  for (let i = 0; i < length; i++) {
    const register = baseRegister(bytes[i]);
    const flags = decodeStatus(register);
    const elapsed = elapsedFor(i);
    const timedOut = !flags.ready && elapsed >= DEVICE_TIMEOUT_MS / 2;
    if (timedOut) timeouts++;
    results.push({ index: i, register, flags, elapsed, timedOut });
  }
  return { results, timeouts, capacity: BUFFER_BYTES };
}

function formatResult(entry) {
  const active = STATUS_BITS
    .filter(([name]) => entry.flags[name])
    .map(([name]) => name)
    .join(',') || 'idle';
  const reg = entry.register.toString(16).padStart(2, '0');
  return `#${entry.index} reg=0x${reg} [${active}] t=${entry.elapsed}ms${entry.timedOut ? ' TIMEOUT' : ''}`;
}

function main() {
  const commands = [
    128,
    64,
    32,
    16,
    300,
    1023,
    255
  ];
  const report = processCommands(commands);
  for (const entry of report.results) {
    console.log(formatResult(entry));
  }
  console.log(`processed ${report.results.length}/${report.capacity} bytes, ${report.timeouts} timeouts`);
}

main();

module.exports = { processCommands, baseRegister, decodeStatus, formatResult };

