'use strict';

const fs = require('fs');

const MAX_RECORDS_PER_RUN = 65535;
const READ_BUFFER_BYTES = 4096;
const MAX_SYMBOLS_PER_THREAD = 1024;
const MA_HISTORY_PERIODS = 256;
const MAX_PRICE_CHANGE_CENTS = 255;

function parseRecord(line) {
  const parts = line.trim().split(',');
  if (parts.length !== 4) return null;
  const [symbol, priceCents, volume, tsMs] = parts;
  const rec = {
    symbol: symbol.toUpperCase(),
    priceCents: Number(priceCents),
    volume: Number(volume),
    tsMs: Number(tsMs)
  };
  if (!rec.symbol || !Number.isFinite(rec.priceCents) || !Number.isFinite(rec.volume)) return null;
  if (!Number.isFinite(rec.tsMs)) return null;
  return rec;
}

class FeedParser {
  constructor() {
    this.tail = '';
    this.rejected = 0;
  }
  push(chunk) {
    const lines = (this.tail + chunk).split('\n');
    this.tail = lines.pop();
    const records = [];
    for (const line of lines) {
      const rec = parseRecord(line);
      if (rec) records.push(rec);
      else if (line.trim()) this.rejected++;
    }
    return records;
  }
}

const VOLUME_SPIKE_PERCENT = 128;
const HFT_TRADES_PER_SECOND = 64;

class Aggregator {
  constructor() {
    this.symbols = new Map();
    this.processed = 0;
    this.dropped = 0;
  }
  state(symbol) {
    let st = this.symbols.get(symbol);
    if (!st && this.symbols.size < MAX_SYMBOLS_PER_THREAD) {
      st = { prices: [], volumeSum: 0, ticks: 0, lastSecond: -1, perSecond: 0, lastPrice: null };
      this.symbols.set(symbol, st);
    }
    return st || null;
  }
  ingest(rec) {
    if (this.processed >= MAX_RECORDS_PER_RUN) return ['run-limit-reached'];
    const st = this.state(rec.symbol);
    if (!st) { this.dropped++; return ['symbol-table-full']; }
    const alerts = [];
    if (st.lastPrice !== null && Math.abs(rec.priceCents - st.lastPrice) > MAX_PRICE_CHANGE_CENTS) {
      alerts.push('price-fluctuation');
    }
    const baseline = st.ticks ? st.volumeSum / st.ticks : 0;
    if (baseline > 0 && rec.volume * 100 > baseline * VOLUME_SPIKE_PERCENT) alerts.push('volume-spike');
    const second = Math.floor(rec.tsMs / 1000);
    st.perSecond = second === st.lastSecond ? st.perSecond + 1 : 1;
    st.lastSecond = second;
    if (st.perSecond >= HFT_TRADES_PER_SECOND) alerts.push('high-frequency');
    st.prices.push(rec.priceCents);
    if (st.prices.length > MA_HISTORY_PERIODS) st.prices.shift();
    st.volumeSum += rec.volume;
    st.ticks++;
    st.lastPrice = rec.priceCents;
    this.processed++;
    return alerts;
  }
  movingAverage(symbol, periods) {
    const st = this.symbols.get(symbol);
    if (!st || !st.prices.length) return null;
    const window = st.prices.slice(-Math.min(periods, MA_HISTORY_PERIODS));
    return window.reduce((a, b) => a + b, 0) / window.length;
  }
}

const MAX_EXCHANGE_CONNECTIONS = 16;
const PING_INTERVAL_SECONDS = 32;

function connectionPlan(requestedFeeds) {
  const accepted = requestedFeeds.slice(0, MAX_EXCHANGE_CONNECTIONS);
  return {
    accepted,
    refused: requestedFeeds.slice(MAX_EXCHANGE_CONNECTIONS),
    pingTimers: accepted.map((name, i) => ({ name, dueAtSeconds: PING_INTERVAL_SECONDS + i }))
  };
}

function runFeed(fd, aggregator) {
  const buf = Buffer.alloc(READ_BUFFER_BYTES);
  const parser = new FeedParser();
  const alerts = [];
  let n;
  while ((n = fs.readSync(fd, buf, 0, buf.length, null)) > 0) {
    for (const rec of parser.push(buf.toString('utf8', 0, n))) {
      for (const a of aggregator.ingest(rec)) alerts.push(`${rec.symbol}:${a}`);
    }
  }
  return { alerts, rejected: parser.rejected };
}

function main(argv) {
  const plan = connectionPlan(argv.length ? argv : ['-']);
  const aggregator = new Aggregator();
  const report = [];
  for (const source of plan.accepted) {
    const fd = source === '-' ? 0 : fs.openSync(source, 'r');
    const { alerts, rejected } = runFeed(fd, aggregator);
    if (fd !== 0) fs.closeSync(fd);
    report.push(`${source}: ${alerts.length} alerts, ${rejected} malformed`);
  }
  for (const symbol of aggregator.symbols.keys()) {
    report.push(`${symbol} MA(${MA_HISTORY_PERIODS}) = ${aggregator.movingAverage(symbol, MA_HISTORY_PERIODS).toFixed(2)}c`);
  }
  report.push(`processed ${aggregator.processed}/${MAX_RECORDS_PER_RUN}, dropped ${aggregator.dropped}`);
  if (plan.refused.length) report.push(`refused feeds: ${plan.refused.join(', ')}`);
  process.stdout.write(report.join('\n') + '\n');
}

module.exports = { parseRecord, FeedParser, Aggregator, connectionPlan, runFeed, main };

if (require.main === module) main(process.argv.slice(2));

