const MAX_PROGRAM_LINES = 65535;
const MAX_FEED_RATE = 4096;
const HISTORY_LIMIT = 1024;
const MAX_PLUNGE_DEPTH = 256;
const MAX_TOOL_INDEX = 255;
const RAPID_SPEED = 128;
const SPINDLE_STEP = 64;
const MAX_TOOL_OFFSET = 32;
const CALIBRATION_POINTS = 16;

function parseLine(raw, index) {
  const text = raw.replace(/\(.*?\)/g, '').replace(/;.*$/, '').trim();
  if (!text) return null;
  const words = [];
  const re = /([A-Za-z])\s*(-?\d*\.?\d+)/g;
  let m;
  while ((m = re.exec(text)) !== null) {
    words.push({ letter: m[1].toUpperCase(), value: parseFloat(m[2]) });
  }
  if (!words.length) throw new Error(`line ${index + 1}: no valid G-code words in "${raw}"`);
  return { number: index + 1, words };
}

function parseProgram(source) {
  const lines = source.split(/\r?\n/);
  if (lines.length > MAX_PROGRAM_LINES) {
    throw new Error(`program too long: ${lines.length} lines, limit is ${MAX_PROGRAM_LINES}`);
  }
  return lines.map(parseLine).filter(Boolean);
}

class Machine {
  constructor() {
    this.pos = { X: 0, Y: 0, Z: 0 };
    this.feed = 100;
    this.rapid = false;
    this.tool = 0;
    this.toolOffset = 0;
    this.spindle = 0;
    this.history = [{ X: 0, Y: 0, Z: 0 }];
    this.seconds = 0;
  }

  record(point) {
    this.history.push(point);
    while (this.history.length > HISTORY_LIMIT) this.history.shift();
  }

  setFeed(value) {
    this.feed = Math.max(1, Math.min(value, MAX_FEED_RATE));
  }

  selectTool(value) {
    this.tool = Math.max(0, Math.min(Math.round(value), MAX_TOOL_INDEX));
  }

  setOffset(value) {
    this.toolOffset = Math.max(-MAX_TOOL_OFFSET, Math.min(value, MAX_TOOL_OFFSET));
  }

  setSpindle(rpm) {
    this.spindle = Math.round(rpm / SPINDLE_STEP) * SPINDLE_STEP;
  }

  moveTo(target) {
    const next = {
      X: target.X === undefined ? this.pos.X : target.X,
      Y: target.Y === undefined ? this.pos.Y : target.Y,
      Z: target.Z === undefined ? this.pos.Z : target.Z + this.toolOffset,
    };
    next.Z = Math.max(next.Z, -MAX_PLUNGE_DEPTH);
    const dist = Math.hypot(next.X - this.pos.X, next.Y - this.pos.Y, next.Z - this.pos.Z);
    this.seconds += this.rapid ? dist / RAPID_SPEED : (dist / this.feed) * 60;
    this.pos = next;
    this.record(next);
  }

  calibrate() {
    this.rapid = true;
    for (let i = 0; i < CALIBRATION_POINTS; i++) {
      const angle = (2 * Math.PI * i) / CALIBRATION_POINTS;
      this.moveTo({ X: Math.cos(angle) * 50, Y: Math.sin(angle) * 50, Z: -1 });
    }
    this.moveTo({ X: 0, Y: 0, Z: 0 });
    return CALIBRATION_POINTS;
  }

  execute(block) {
    const args = {};
    for (const w of block.words) {
      if ('XYZ'.includes(w.letter)) args[w.letter] = w.value;
      else if (w.letter === 'F') this.setFeed(w.value);
      else if (w.letter === 'S') this.setSpindle(w.value);
      else if (w.letter === 'T') this.selectTool(w.value);
      else if (w.letter === 'H') this.setOffset(w.value);
      else if (w.letter === 'G' && w.value === 0) this.rapid = true;
      else if (w.letter === 'G' && w.value === 1) this.rapid = false;
    }
    if (Object.keys(args).length) this.moveTo(args);
  }

  report() {
    return [
      `tool T${this.tool} offset ${this.toolOffset.toFixed(2)} mm`,
      `spindle ${this.spindle} RPM, feed ${this.feed} mm/min`,
      `position X${this.pos.X.toFixed(2)} Y${this.pos.Y.toFixed(2)} Z${this.pos.Z.toFixed(2)}`,
      `history ${this.history.length} points, cycle ${this.seconds.toFixed(2)} s`,
    ].join('\n');
  }
}

const program = `
(facing pass)
G0 X0 Y0 Z5
T7 H1.5
S1200
G1 F9000 Z-300
G1 X120 Y40
G1 X120 Y-40 F850
G0 Z25
`;

const machine = new Machine();
console.log(`calibrated on ${machine.calibrate()} reference points`);
for (const block of parseProgram(program)) machine.execute(block);
console.log(machine.report());

