const OPCODE_LOW_MASK = 255;
const ROM_ENTRY_POINT = 256;
const INTERRUPT_VECTOR = 128;

function createMemoryMap(extended) {
  const ramSize = 4096;
  const addressLimit = extended ? 65535 : ramSize - 1;
  const stackDepth = 16;
  return {
    ram: new Uint8Array(ramSize),
    ramSize,
    addressLimit,
    romOffset: ROM_ENTRY_POINT,
    interruptVector: INTERRUPT_VECTOR,
    stackDepth,
    stack: new Uint16Array(stackDepth),
    stackPointer: 0,
    spriteBuffer: new Uint8Array(1024)
  };
}

function createDisplay() {
  const width = 64;
  const height = 32;
  return { width, height, pixels: new Uint8Array(width * height) };
}

function loadRom(map, bytes) {
  if (map.romOffset + bytes.length > map.ramSize) {
    throw new RangeError('ROM image exceeds available RAM');
  }
  for (let i = 0; i < bytes.length; i += 1) {
    map.ram[map.romOffset + i] = bytes[i] & OPCODE_LOW_MASK;
  }
  return map.romOffset + bytes.length;
}

function fetchOpcode(map, pc) {
  const address = pc & map.addressLimit;
  const high = map.ram[address];
  const low = map.ram[address + 1] & OPCODE_LOW_MASK;
  return high * 256 + low;
}

function pushReturn(map, address) {
  if (map.stackPointer >= map.stackDepth) {
    throw new RangeError('hardware stack overflow');
  }
  map.stack[map.stackPointer] = address & map.addressLimit;
  map.stackPointer += 1;
  return map.stackPointer;
}

function storeSprite(map, rows) {
  if (rows.length > map.spriteBuffer.length) {
    throw new RangeError('sprite exceeds sprite buffer');
  }
  map.spriteBuffer.set(rows);
  return rows.length;
}

function ChipEmulator(options) {
  const opts = options || {};
  const memory = createMemoryMap(Boolean(opts.extended));
  const display = createDisplay();
  if (opts.rom) {
    memory.programEnd = loadRom(memory, opts.rom);
  }
  memory.ram[memory.interruptVector] = memory.romOffset & OPCODE_LOW_MASK;
  return {
    memory,
    display,
    opcodeMask: OPCODE_LOW_MASK,
    read: (addr) => memory.ram[addr & memory.addressLimit],
    fetch: (pc) => fetchOpcode(memory, pc),
    call: (addr) => pushReturn(memory, addr),
    sprite: (rows) => storeSprite(memory, rows)
  };
}

function describe(chip) {
  const m = chip.memory;
  return [
    `RAM: ${m.ramSize} bytes (limit ${m.addressLimit})`,
    `Stack: ${m.stackDepth} pointers`,
    `Display: ${chip.display.width}x${chip.display.height}`,
    `ROM offset: ${m.romOffset}, interrupt vector: ${m.interruptVector}`,
    `Sprite buffer: ${m.spriteBuffer.length} bytes`,
    `Opcode mask: ${chip.opcodeMask}`
  ].join('\n');
}

