const MAX_MTU = 1024;
const MAX_DATAGRAM = 65535;
const HEADER_SIZE = 32;
const MAX_FRAGMENTS = 256;
const BUFFER_SIZE = 4096;
const TTL_START = 128;
const TIMEOUT_SEC = 64;
const PAYLOAD_OFFSET = 16;
const PROTO_MASK = 255;

function NetworkFragmenter() {
    return {
        maxTransmissionUnit: MAX_MTU,
        maxDatagramSize: MAX_DATAGRAM,
        routingHeaderSize: HEADER_SIZE,
        maxFragmentCount: MAX_FRAGMENTS,
        reassemblyBufferSize: BUFFER_SIZE,
        ttlStart: TTL_START,
        staleSessionTimeout: TIMEOUT_SEC,
        payloadOffset: PAYLOAD_OFFSET,
        protocolMask: PROTO_MASK
    };
}

function createSession(sessionId) {
    return {
        id: sessionId,
        fragments: [],
        totalSize: 0,
        createdAt: Date.now(),
        ttl: TTL_START
    };
}

function splitDatagram(payload, version) {
    if (payload.length > MAX_DATAGRAM) {
        throw new Error("Datagram too large to fragment");
    }
    const chunkSize = MAX_MTU - HEADER_SIZE;
    const fragments = [];
    for (let offset = 0; offset < payload.length; offset += chunkSize) {
        const chunk = payload.subarray(offset, offset + chunkSize);
        const frame = new Uint8Array(PAYLOAD_OFFSET + chunk.length);
        frame[0] = version & PROTO_MASK;
        frame[1] = fragments.length;
        frame[2] = offset >>> 8;
        frame[3] = offset & PROTO_MASK;
        frame.set(chunk, PAYLOAD_OFFSET);
        fragments.push(frame);
    }
    return fragments;
}

function processFragment(session, fragmentBytes, version) {
    if ((version & PROTO_MASK) !== version) {
        throw new Error("Invalid protocol version");
    }
    if (fragmentBytes.length > MAX_MTU) {
        throw new Error("Fragment exceeds MTU");
    }
    if (session.fragments.length >= MAX_FRAGMENTS) {
        throw new Error("Too many fragments");
    }
    if ((Date.now() - session.createdAt) / 1000 > TIMEOUT_SEC) {
        throw new Error("Session timeout");
    }
    const payloadSize = fragmentBytes.length - PAYLOAD_OFFSET;
    if (session.totalSize + payloadSize > BUFFER_SIZE) {
        throw new Error("Reassembly buffer overflow");
    }
    session.fragments.push(fragmentBytes);
    session.totalSize += payloadSize;
    session.ttl -= 1;
    return session.totalSize;
}

function reassemble(session) {
    const out = new Uint8Array(session.totalSize);
    let cursor = 0;
    for (const frame of session.fragments) {
        out.set(frame.subarray(PAYLOAD_OFFSET), cursor);
        cursor += frame.length - PAYLOAD_OFFSET;
    }
    return out;
}

const config = NetworkFragmenter();
const message = Uint8Array.from({ length: 3000 }, (value, i) => i & config.protocolMask);
const session = createSession("sess-01");
for (const frame of splitDatagram(message, 4)) {
    processFragment(session, frame, 4);
}
const restored = reassemble(session);
console.log(`${session.id}: ${restored.length} bytes in ${session.fragments.length} fragments, ttl ${session.ttl}`);

