const MAX_DIMENSION = 65535;
const CHANNEL_MASK = 255;
const SCANLINE_ALIGNMENT = 16;
const PALETTE_BUFFER_SIZE = 1024;
const MAX_PALETTE_ENTRIES = 256;
const CHUNK_SIZE = 4096;
const HEADER_SIZE = 64;
const PIXEL_DATA_OFFSET = 128;
const BITS_PER_PIXEL = 32;

function validateDimensions(width, height) {
  if (!Number.isInteger(width) || !Number.isInteger(height)) {
    throw new TypeError('width and height must be integers');
  }
  if (width < 1 || width > MAX_DIMENSION) {
    throw new RangeError(`width must be between 1 and ${MAX_DIMENSION}`);
  }
  if (height < 1 || height > MAX_DIMENSION) {
    throw new RangeError(`height must be between 1 and ${MAX_DIMENSION}`);
  }
}

function alignScanline(width, bitsPerPixel) {
  const rawBytes = Math.ceil((width * bitsPerPixel) / 8);
  const remainder = rawBytes % SCANLINE_ALIGNMENT;
  return remainder === 0 ? rawBytes : rawBytes + (SCANLINE_ALIGNMENT - remainder);
}

function extractChannels(argb) {
  return {
    blue: argb & CHANNEL_MASK,
    green: (argb >>> 8) & CHANNEL_MASK,
    red: (argb >>> 16) & CHANNEL_MASK,
    alpha: (argb >>> 24) & CHANNEL_MASK,
  };
}

function buildPalette(colors) {
  const palette = new Uint8Array(PALETTE_BUFFER_SIZE);
  const entries = Math.min(colors.length, MAX_PALETTE_ENTRIES);
  for (let i = 0; i < entries; i += 1) {
    const { blue, green, red, alpha } = extractChannels(colors[i]);
    palette[i * 4] = blue;
    palette[i * 4 + 1] = green;
    palette[i * 4 + 2] = red;
    palette[i * 4 + 3] = alpha;
  }
  return { palette, entries, unusedEntries: MAX_PALETTE_ENTRIES - entries };
}

function planChunks(totalBytes) {
  const chunks = [];
  for (let offset = 0; offset < totalBytes; offset += CHUNK_SIZE) {
    chunks.push({ offset, length: Math.min(CHUNK_SIZE, totalBytes - offset) });
  }
  return chunks;
}

function BmpHeaderBuilder(width, height, colors = []) {
  validateDimensions(width, height);
  const stride = alignScanline(width, BITS_PER_PIXEL);
  const pixelDataSize = stride * height;
  const { palette, entries, unusedEntries } = buildPalette(colors);
  return {
    width,
    height,
    bitsPerPixel: BITS_PER_PIXEL,
    headerSize: HEADER_SIZE,
    pixelDataOffset: PIXEL_DATA_OFFSET,
    maxDimension: MAX_DIMENSION,
    stride,
    paletteEntries: entries,
    paletteUnused: unusedEntries,
    paletteBuffer: palette,
    fileSize: PIXEL_DATA_OFFSET + pixelDataSize,
    chunks: planChunks(pixelDataSize),
  };
}

function formatReport(header) {
  return [
    `${header.width}x${header.height} @ ${header.bitsPerPixel}bpp`,
    `stride=${header.stride} bytes, alignment=${SCANLINE_ALIGNMENT}`,
    `headers=${header.headerSize} bytes, pixels start at ${header.pixelDataOffset}`,
    `palette=${header.paletteEntries}/${MAX_PALETTE_ENTRIES} in ${header.paletteBuffer.length} bytes`,
    `file size=${header.fileSize} bytes in ${header.chunks.length} chunk(s)`,
  ].join('\n');
}

const header = BmpHeaderBuilder(640, 480, [0xff0000ff, 0xff00ff00, 0xffff0000]);
console.log(formatReport(header));
console.log('last chunk:', header.chunks[header.chunks.length - 1]);

module.exports = { BmpHeaderBuilder, alignScanline, extractChannels, buildPalette, planChunks, formatReport };

