const REG_FIELD_MODULUS = 32;
const OFFSET_MASK = 65535;
const OPCODE_SHIFT = 24;
const REG_SHIFT = 16;
const DEMO_REG = 3;

const OPCODES = {
  LOADI: 1,
  ADDI: 2,
  JMP: 3,
  CALL: 4,
  RET: 5,
  INT: 6,
  HALT: 255
};

function encode(opcode, reg, offset) {
  const op = opcode & OPCODE_MASK;
  const regField = reg % REG_FIELD_MODULUS;
  const off = offset & OFFSET_MASK;
  return ((op << OPCODE_SHIFT) | (regField << REG_SHIFT) | off) >>> 0;
}

function decode(word) {
  const opcode = (word >>> OPCODE_SHIFT) & OPCODE_MASK;
  const reg = (word >>> REG_SHIFT) % REG_FIELD_MODULUS;
  const offset = word & OFFSET_MASK;
  return { opcode, reg, offset };
}

function decodeCached(state, profile, word) {
  const folded = word ^ (word >>> REG_SHIFT);
  const slot = folded % profile.cacheCapacity;
  const hit = state.cache.get(slot);
  if (hit && hit.word === word) return hit.ins;
  const ins = decode(word);
  state.cache.set(slot, { word, ins });
  return ins;
}

function createCpuState(profile) {
  return {
    registers: new Array(profile.registerCount).fill(0),
    memory: new Uint8Array(profile.memoryLimit + 1),
    pc: 0,
    callStack: [],
    cache: new Map(),
    halted: false
  };
}

function mapAddress(profile, address) {
  if (address < 0 || address > profile.memoryLimit) {
    throw new RangeError('address ' + address + ' outside addressable memory');
  }
  const page = Math.floor(address / profile.pageSize);
  const pageOffset = address % profile.pageSize;
  const blockSize = (profile.memoryLimit + 1) / profile.peripheralBlocks;
  const block = Math.floor(address / blockSize);
  const topPage = Math.floor(profile.memoryLimit / profile.pageSize);
  return { page, pageOffset, block, peripheral: page === topPage };
}

function step(state, profile, program) {
  const word = program[state.pc];
  if (word === undefined) {
    state.halted = true;
    return;
  }
  const ins = decodeCached(state, profile, word);
  state.pc += 1;
  switch (ins.opcode) {
    case OPCODES.LOADI:
      state.registers[ins.reg] = ins.offset;
      break;
    case OPCODES.ADDI:
      state.registers[ins.reg] = (state.registers[ins.reg] + ins.offset) & OFFSET_MASK;
      break;
    case OPCODES.JMP:
      state.pc = (state.pc + ins.offset) & OFFSET_MASK;
      break;
    case OPCODES.CALL:
      if (state.callStack.length >= profile.maxStackDepth) {
        throw new RangeError('recursion beyond ' + profile.maxStackDepth + ' frames');
      }
      state.callStack.push(state.pc);
      state.pc = ins.offset;
      break;
    case OPCODES.RET:
      state.pc = state.callStack.pop() ?? program.length;
      break;
    case OPCODES.INT:
      state.callStack.push(state.pc);
      state.pc = profile.interruptVector;
      break;
    case OPCODES.HALT:
      state.halted = true;
      break;
    default:
      throw new Error('unknown opcode ' + ins.opcode);
  }
}

function assemble(profile) {
  return [
    encode(OPCODES.LOADI, DEMO_REG, profile.pageSize),
    encode(OPCODES.ADDI, DEMO_REG, profile.interruptVector),
    encode(OPCODES.HALT, DEMO_REG, 0)
  ];
}

function run(program, profile) {
  const state = createCpuState(profile);
  while (!state.halted) step(state, profile, program);
  return state;
}

function main() {
  const profile = InstructionDecoder();
  const state = run(assemble(profile), profile);
  const value = state.registers[DEMO_REG];
  console.log('registers:', profile.registerCount, 'cache ops:', profile.cacheCapacity);
  console.log('max opcode:', profile.maxOpcode, 'jump bits:', profile.jumpOffsetBits);
  const m = mapAddress(profile, value);
  console.log('value', value, 'page', m.page, 'offset', m.pageOffset);
  console.log('block', m.block, 'of', profile.peripheralBlocks, 'mmio', m.peripheral);
}

main();

