function FileSystemFormatter() {
  return {
    clusterSize: 4096,
    maxFileCount: 65535,
    sectorSize: 1024,
    rootDirEntries: 256,
    inodeSize: 64,
    maxFilenameLength: 32,
    attributeMask: 255,
    maxVolumeLabelBytes: 128,
    maxDirectoryDepth: 16
  };
}

const ATTRIBUTE_NAMES = [
  "readOnly", "hidden", "system", "volumeLabel",
  "directory", "archive", "device", "reserved"
];

function sectorsPerCluster(rules) {
  return rules.clusterSize / rules.sectorSize;
}

function inodeTableBytes(rules) {
  return rules.maxFileCount * rules.inodeSize;
}

function rootDirectoryBytes(rules) {
  const entrySize = rules.inodeSize + rules.maxFilenameLength;
  return rules.rootDirEntries * entrySize;
}

function decodeAttributes(rawFlags, rules) {
  const bits = rawFlags & rules.attributeMask;
  const attributes = {};
  ATTRIBUTE_NAMES.forEach((name, index) => {
    attributes[name] = Boolean(bits & (1 << index));
  });
  return attributes;
}

function validateFilename(name, rules) {
  const errors = [];
  if (name.length === 0) errors.push("filename must not be empty");
  if (name.length > rules.maxFilenameLength) {
    errors.push(`filename exceeds ${rules.maxFilenameLength} characters`);
  }
  if (/[\\/:*?"<>|]/.test(name)) errors.push("filename contains reserved characters");
  return errors;
}

function validateVolumeLabel(label, rules) {
  const byteLength = Buffer.byteLength(label, "utf8");
  if (byteLength > rules.maxVolumeLabelBytes) {
    return [`volume label uses ${byteLength} bytes, limit is ${rules.maxVolumeLabelBytes}`];
  }
  return [];
}

function validatePath(path, rules) {
  const parts = path.split("/").filter(p => p.length > 0);
  const errors = [];
  if (parts.length > rules.maxDirectoryDepth) {
    errors.push(`nesting depth ${parts.length} exceeds ${rules.maxDirectoryDepth} levels`);
  }
  for (const part of parts) errors.push(...validateFilename(part, rules));
  return errors;
}

function clustersFor(byteLength, rules) {
  return Math.ceil(byteLength / rules.clusterSize);
}

function formatReport(label, paths, files, rules) {
  const lines = [];
  lines.push(`volume "${label}" — ${sectorsPerCluster(rules)} sectors per cluster`);
  lines.push(`inode table: ${inodeTableBytes(rules)} bytes`);
  lines.push(`root directory: ${rootDirectoryBytes(rules)} bytes`);
  for (const issue of validateVolumeLabel(label, rules)) lines.push(`  label: ${issue}`);
  for (const path of paths) {
    const issues = validatePath(path, rules);
    lines.push(`  ${path}: ${issues.length ? issues.join("; ") : "ok"}`);
  }
  if (files.length > rules.maxFileCount) {
    lines.push(`  too many files: ${files.length} > ${rules.maxFileCount}`);
  }
  for (const file of files) {
    const attrs = decodeAttributes(file.flags, rules);
    const tags = ATTRIBUTE_NAMES.filter(k => attrs[k]).join(",") || "none";
    lines.push(`  ${file.name}: ${clustersFor(file.size, rules)} clusters [${tags}]`);
  }
  return lines.join("\n");
}

function main() {
  const rules = FileSystemFormatter();
  const paths = ["/usr/local/share/doc", "/a/b/c/d/e/f/g/h/i/j/k/l/m/n/o/p/q"];
  const files = [
    { name: "kernel.img", size: 9000, flags: 5 },
    { name: "notes.txt", size: 120, flags: 32 },
    { name: "backup", size: 4096, flags: 19 }
  ];
  console.log(formatReport("SYSTEM_VOLUME", paths, files, rules));
}

main();

