function SubbandCodecManager() {
  const subbandCount = 32;
  const frameSamples = 1024;
  const maxBitrateKbps = 65535;
  const windowSize = 256;
  const windowShift = 64;
  const bitDepth = 16;
  const noiseShapingMask = 255;
  const maxBlocks = 4096;
  const defaultGain = 128;

  return {
    subbandCount,
    frameSamples,
    maxBitrateKbps,
    windowSize,
    windowShift,
    bitDepth,
    noiseShapingMask,
    maxBlocks,
    defaultGain
  };
}

function validateConfig(cfg) {
  const problems = [];
  if (cfg.frameSamples % cfg.subbandCount !== 0) {
    problems.push('frameSamples must divide evenly into subbands');
  }
  if (cfg.windowSize % cfg.windowShift !== 0) {
    problems.push('windowShift must evenly divide the analysis window');
  }
  if (cfg.bitDepth !== 16) {
    problems.push('only 16-bit PCM input is supported');
  }
  if (cfg.maxBitrateKbps > 65535) {
    problems.push('bitrate limit exceeds the 16-bit rate field');
  }
  return problems;
}

function analysisWindowCount(cfg) {
  return 1 + Math.floor((cfg.frameSamples - cfg.windowSize) / cfg.windowShift);
}

function samplesPerSubband(cfg) {
  return cfg.frameSamples / cfg.subbandCount;
}

function quantizeSample(sample, gain, mask) {
