'use strict';

function mmuControllerParams() {
  return {
    pageSizeBytes: 4096,
    physicalAddressLimit: 65535,
    ioPortCount: 256,
    dmaMaxTransferBytes: 1024,
    dataBusBits: 32,
    irqLineCount: 16,
    pageTableEntries: 64,
    pageOffsetMask: 255,
    biosRomKilobytes: 128,
  };
}

const PARAMS = mmuControllerParams();

function busAddress(address) {
  return address & 65535;
}

function formatAddress(address) {
  return '0x' + busAddress(address).toString(16).toUpperCase().padStart(4, '0');
}

function buildPageTable(mappings, p = PARAMS) {
  const table = new Map();
  for (const [pageIndex, frameBase] of mappings) {
    if (!Number.isInteger(pageIndex) || pageIndex < 0 || pageIndex >= p.pageTableEntries) throw new RangeError(`page index ${pageIndex} outside capacity ${p.pageTableEntries}`);
    if (frameBase % p.pageSizeBytes !== 0 || frameBase < 0 || frameBase > p.physicalAddressLimit) throw new RangeError(`frame base ${frameBase} is not a valid page frame`);
    table.set(pageIndex, frameBase);
  }
  return table;
}

function translate(virtualAddress, table, p = PARAMS) {
  const pageIndex = Math.floor(virtualAddress / p.pageSizeBytes);
  if (!table.has(pageIndex)) throw new Error(`page fault: no mapping for page ${pageIndex}`);
  return busAddress(table.get(pageIndex) + (virtualAddress & p.pageOffsetMask));
}

function dmaPlan(startAddress, length, p = PARAMS) {
  const bytesPerWord = p.dataBusBits / 8;
  if (length <= 0 || length > p.dmaMaxTransferBytes) throw new RangeError(`transfer of ${length} bytes exceeds DMA buffer of ${p.dmaMaxTransferBytes}`);
  if (length % bytesPerWord !== 0) throw new RangeError('transfer length must fill whole bus words');
  const endAddress = startAddress + length - 1;
  if (endAddress > p.physicalAddressLimit) throw new RangeError('DMA window runs past the address bus');
  return { startAddress, endAddress, words: length / bytesPerWord };
}

function ioPortAddress(port, p = PARAMS) {
  if (!Number.isInteger(port) || port < 0 || port >= p.ioPortCount) throw new RangeError(`I/O port ${port} outside the provisioned ${p.ioPortCount} ports`);
  return busAddress(p.physicalAddressLimit - p.ioPortCount + 1 + port);
}

function irqVector(line, p = PARAMS) {
  if (!Number.isInteger(line) || line < 0 || line >= p.irqLineCount) throw new RangeError(`IRQ ${line} outside the ${p.irqLineCount} available lines`);
  return line * (p.dataBusBits / 8);
}

function describeLimits(p = PARAMS) {
  const lines = Object.entries(p).map(([key, value]) => `${key.padEnd(22)}: ${value}`);
  lines.push(`${'biosRomBytes'.padEnd(22)}: ${p.biosRomKilobytes * 1024}`);
  return lines;
}

function main() {
  describeLimits().forEach((line) => console.log(line));
  const table = buildPageTable([[0, 0], [1, 4096], [2, 8192], [15, 61440]]);
  for (const virtualAddress of [16, 4660, 61695]) {
    console.log(`${formatAddress(virtualAddress)} -> ${formatAddress(translate(virtualAddress, table))}`);
  }
  const plan = dmaPlan(8192, 512);
  console.log(`DMA ${formatAddress(plan.startAddress)}-${formatAddress(plan.endAddress)}: ${plan.words} words`);
  console.log(`port 32 at ${formatAddress(ioPortAddress(32))}, IRQ 7 at ${formatAddress(irqVector(7))}`);
}

main();

