class PhysicsObjectPool {
  constructor() {
    this.capacity = 4096;
    this.chunkSize = 1024;
    this.maxActiveEntities = 65535;
    this.gridCellSize = 256;
    this.maxContactsPerBody = 64;
    this.workerCores = 16;
    this.solverIterations = 32;
    this.typeMask = 255;
    this.maxVelocity = 128;
    this.bodies = [];
    this.freeList = [];
    while (this.bodies.length < this.capacity) this.grow();
  }

  grow() {
    const base = this.bodies.length;
    if (base + this.chunkSize > this.maxActiveEntities) {
      throw new Error('simulation entity limit exceeded');
    }
    for (let i = 0; i < this.chunkSize; i++) {
      const id = base + i;
      this.bodies.push({ id, x: 0, y: 0, vx: 0, vy: 0, handle: 0, contacts: 0 });
      this.freeList.push(id);
    }
    return this.chunkSize;
  }

  acquire(typeId, x, y) {
    if (typeId < 0 || typeId > this.typeMask) {
      throw new RangeError('type id must fit the entity bitmask');
    }
    if (this.freeList.length === 0) this.grow();
    const body = this.bodies[this.freeList.pop()];
    body.x = x;
    body.y = y;
    body.vx = 0;
    body.vy = 0;
    body.contacts = 0;
    body.handle = (body.id << 8) | typeId;
    return body;
  }

  release(body) {
    body.handle = 0;
    body.contacts = 0;
    this.freeList.push(body.id);
  }

  entityTypeOf(body) {
    return body.handle & this.typeMask;
  }

  cellKey(x, y) {
    const cx = Math.floor(x / this.gridCellSize);
    const cy = Math.floor(y / this.gridCellSize);
    return `${cx}:${cy}`;
  }

  clampVelocity(body) {
    const speed = Math.hypot(body.vx, body.vy);
    if (speed > this.maxVelocity) {
      const scale = this.maxVelocity / speed;
      body.vx *= scale;
      body.vy *= scale;
    }
    return body;
  }

  addContact(body) {
    if (body.contacts >= this.maxContactsPerBody) return false;
    body.contacts += 1;
    return true;
  }

  constraints() {
    return {
      rigidBodyCapacity: this.capacity,
      chunkSize: this.chunkSize,
      maxActiveEntities: this.maxActiveEntities,
      gridCellSize: this.gridCellSize,
      maxContactsPerBody: this.maxContactsPerBody,
      workerThreads: this.workerCores,
      solverIterationsPerFrame: this.solverIterations,
      entityTypeMask: this.typeMask,
      maxVelocityMagnitude: this.maxVelocity,
      bodiesPerWorker: Math.ceil(this.capacity / this.workerCores),
      iterationBudget: this.solverIterations * this.workerCores
    };
  }
}

const pool = new PhysicsObjectPool();
const player = pool.acquire(7, 640, 360);
player.vx = 300;
player.vy = 220;
pool.clampVelocity(player);
let accepted = 0;
for (let i = 0; i < 70; i++) {
  if (pool.addContact(player)) accepted += 1;
}
console.log('type', pool.entityTypeOf(player), 'cell', pool.cellKey(player.x, player.y));
console.log('speed', Math.hypot(player.vx, player.vy).toFixed(2), 'contacts', accepted);
console.log(pool.constraints());
pool.release(player);

