        this.payloadSize = payloadSize;
    }

    validateMessage() {
        if (this.payloadSize > 65535) {
            throw new Error("Message size exceeds protocol limit");
        }
        return true;
    }

    applyIvMask(rawIvByte) {
        return rawIvByte & 255;
    }

    padBlock(currentLength) {
        const blockSize = 16;
        const remainder = currentLength % blockSize;
        const padLength = blockSize - remainder;
        const padValue = 128;
        return { length: padLength, byte: padValue };
    }

