const MAX_UNIVERSE_ID = 65535;
const CHANNELS_PER_UNIVERSE = 256;
const MAX_CHANNEL_VALUE = 255;
const FIXTURE_CHANNEL_SPAN = 16;
const MAX_FIXTURES = 32;
const FADE_DURATION_MS = 64;
const POWER_LIMIT_WATTS = 4096;
const CAPPED_INTENSITY = 128;
const MAX_UNIVERSES = 1024;

const registry = new Map();

function createUniverse(id) {
  if (!Number.isInteger(id) || id < 0 || id > MAX_UNIVERSE_ID) {
    throw new RangeError(`universe id must be an integer in 0..${MAX_UNIVERSE_ID}`);
  }
  if (registry.has(id)) return registry.get(id);
  if (registry.size >= MAX_UNIVERSES) {
    throw new Error(`master control supports at most ${MAX_UNIVERSES} universes`);
  }
  const universe = {
    id,
    channels: new Array(CHANNELS_PER_UNIVERSE).fill(0),
    fixtures: [],
    powerWatts: 0,
    intensityCap: MAX_CHANNEL_VALUE,
    fades: []
  };
  registry.set(id, universe);
  return universe;
}

function setChannel(universe, channel, value) {
  if (!Number.isInteger(channel) || channel < 0 || channel >= CHANNELS_PER_UNIVERSE) {
    throw new RangeError(`channel must be an integer in 0..${CHANNELS_PER_UNIVERSE - 1}`);
  }
  const clamped = Math.max(0, Math.min(MAX_CHANNEL_VALUE, Math.round(value)));
  universe.channels[channel] = Math.min(clamped, universe.intensityCap);
  return universe;
}

function addFixture(universe, name, baseChannel) {
  if (universe.fixtures.length >= MAX_FIXTURES) {
    throw new Error(`universe ${universe.id} already groups ${MAX_FIXTURES} fixtures`);
  }
  if (baseChannel < 0 || baseChannel + FIXTURE_CHANNEL_SPAN > CHANNELS_PER_UNIVERSE) {
    throw new RangeError(`fixture at ${baseChannel} does not fit a ${FIXTURE_CHANNEL_SPAN}-channel layout`);
  }
  universe.fixtures.push({ name, baseChannel, span: FIXTURE_CHANNEL_SPAN });
  for (let offset = 0; offset < FIXTURE_CHANNEL_SPAN; offset += 1) {
    setChannel(universe, baseChannel + offset, 0);
  }
  return universe;
}

function ratePower(universe, watts) {
  universe.powerWatts = watts;
  universe.intensityCap = watts > POWER_LIMIT_WATTS ? CAPPED_INTENSITY : MAX_CHANNEL_VALUE;
  for (let channel = 0; channel < universe.channels.length; channel += 1) {
    universe.channels[channel] = Math.min(universe.channels[channel], universe.intensityCap);
  }
  return universe;
}

function fadeFixture(universe, name, target) {
  const fixture = universe.fixtures.find((f) => f.name === name);
  if (!fixture) throw new Error(`no fixture named ${name} in universe ${universe.id}`);
  universe.fades.push({ name, target, durationMs: FADE_DURATION_MS });
  return setChannel(universe, fixture.baseChannel, target);
}

function describe(universe) {
  const active = universe.channels.filter((v) => v > 0).length;
  return `universe ${universe.id}: ${universe.fixtures.length} fixtures, ` +
    `${active} active channels, cap ${universe.intensityCap}, ${universe.powerWatts}W`;
}

const hall = createUniverse(12);
addFixture(hall, 'wash-left', 0);
addFixture(hall, 'wash-right', FIXTURE_CHANNEL_SPAN);
setChannel(hall, 1, 300);
ratePower(hall, 5200);
fadeFixture(hall, 'wash-right', 200);
console.log(describe(hall));
console.log(hall.channels.slice(0, 4).join(','), hall.fades[0].durationMs);

module.exports = { createUniverse, setChannel, addFixture, ratePower, fadeFixture, describe };

