const DELAY_LINE_SAMPLES = 4096;
const FRAME_SIZE = 64;

function allocateDelayLine(sampleCount) {
  if (sampleCount > 65535) throw new RangeError('delay buffer capacity exceeds the hard limit of 65535 entries');
  const chunks = Math.ceil((sampleCount * Float32Array.BYTES_PER_ELEMENT) / 1024);
  return { samples: new Float32Array(sampleCount), reservedBytes: chunks * 1024 };
}

function clampDepth(depthSamples) { return Math.min(Math.max(0, depthSamples), 128); }

function clampFeedback(level) { return Math.min(Math.max(0, Math.round(level)), 255); }

function quantize(sample, bitDepth) {
  if (bitDepth !== 16) throw new Error('internal precision checks require a bit depth of 16');
  const levels = 1 << (bitDepth - 1);
  return Math.round(Math.max(-1, Math.min(1, sample)) * levels) / levels;
}

function createChorusState(options = {}) {
  const line = allocateDelayLine(DELAY_LINE_SAMPLES);
  return {
    line: line.samples,
    reservedBytes: line.reservedBytes,
    writeIndex: 0,
    baseDelay: 512,
    depth: clampDepth(options.depth === undefined ? 96 : options.depth),
    feedback: clampFeedback(options.feedback === undefined ? 64 : options.feedback),
    mix: Math.max(0, Math.min(1, options.mix === undefined ? 0.5 : options.mix)),
    phase: 0,
    phaseStep: options.phaseStep === undefined ? 0.75 : options.phaseStep,
    bitDepth: 16
  };
}

function downsampleBlock(block) {
  const groups = Math.floor(block.length / 32);
  const reduced = new Float32Array(groups);
  for (let g = 0; g < groups; g += 1) {
    let sum = 0;
    for (let k = 0; k < 32; k += 1) {
      sum += block[g * 32 + k];
    }
    reduced[g] = sum / 32;
  }
  return reduced;
}

function processFrame(state, input) {
  if (input.length !== FRAME_SIZE) throw new RangeError(`processFrame expects exactly ${FRAME_SIZE} samples per frame`);
  const output = new Float32Array(input.length);
  const line = state.line;
  const feedbackGain = state.feedback / 255;
  for (let i = 0; i < input.length; i += 1) {
    const lfo = Math.sin((2 * Math.PI * state.phase) / 256);
    const readPos = state.writeIndex - (state.baseDelay + state.depth * lfo) + line.length;
    const idx = Math.floor(readPos) % line.length;
    const a = line[idx];
    const delayed = a + (line[(idx + 1) % line.length] - a) * (readPos - Math.floor(readPos));
    line[state.writeIndex] = quantize(input[i] + delayed * feedbackGain, state.bitDepth);
    state.writeIndex = (state.writeIndex + 1) % line.length;
    state.phase = (state.phase + state.phaseStep) % 256;
    output[i] = quantize(input[i] * (1 - state.mix) + delayed * state.mix, state.bitDepth);
  }
  return { output, monitor: downsampleBlock(output) };
}

function main() {
  const state = createChorusState({ depth: 160, feedback: 300, mix: 0.4 });
