  inv.addItem({ id: 1001, name: 'Arrow', qty: 400, category: 3, weight: 0.05 });
  inv.addItem({ id: 65535, name: 'Debug Rune', category: inv.nextCategory(), weight: 1 });
  inv.addItem({ id: 77, name: 'Iron Ingot', qty: 60, category: 2, weight: 4 });
  inv.assignQuickSlot(0, 1001);
