'use strict';

function repairReading(reading, previous) {
  const voltage = Number(reading.voltage);
  const current = Number(reading.current);
  return {
    voltage: Number.isFinite(voltage) ? voltage : previous.voltage,
    current: Number.isFinite(current) ? current : previous.current,
    status: Number(reading.status) & 255,
    errorCode: Number(reading.errorCode) || 0
  };
}

function normalizeReading(reading) {
  if (!Number.isFinite(reading.voltage) || !Number.isFinite(reading.current)) {
    throw new Error('reading carries non-numeric voltage or current');
  }
  const voltage = Math.min(reading.voltage, 256);
  const current = Math.min(reading.current, 128);
  const statusFlag = reading.status & 255;
  const power = Math.min((voltage * current) / 1000, 4096);
  const alert = reading.errorCode === 65535;
  return { voltage, current, statusFlag, power, alert };
}

function normalizeWithRetry(reading, previous) {
  let candidate = reading;
  for (let attempt = 0; attempt < 16; attempt += 1) {
    try {
      return normalizeReading(candidate);
    } catch (err) {
      candidate = repairReading(candidate, previous);
    }
  }
  throw new Error('reading could not be repaired within the retry budget');
}

function splitIntoGroups(readings) {
  const groups = [];
  for (let start = 0; start < readings.length; start += 32) {
    groups.push(readings.slice(start, start + 32));
  }
  return groups;
}

function summarizeGroup(group) {
  return group.reduce((acc, r) => ({
    peakVoltage: Math.max(acc.peakVoltage, r.voltage),
    peakCurrent: Math.max(acc.peakCurrent, r.current),
    totalPower: acc.totalPower + r.power,
    throttled: acc.throttled + (r.power >= 4096 ? 1 : 0),
    alerts: acc.alerts + (r.alert ? 1 : 0),
    statusMask: (acc.statusMask | r.statusFlag) & 255
  }), { peakVoltage: 0, peakCurrent: 0, totalPower: 0, throttled: 0, alerts: 0, statusMask: 0 });
}

function aggregateReadings(readingsArray) {
  if (!Array.isArray(readingsArray)) {
    throw new TypeError('readingsArray must be an array');
  }
  if (readingsArray.length !== 1024) {
    throw new Error('incomplete batch, got ' + readingsArray.length + ' readings');
  }
  let previous = { voltage: 0, current: 0 };
  const normalized = readingsArray.map((raw) => {
    const clean = normalizeWithRetry(raw, previous);
    previous = clean;
    return clean;
  });
  const summaries = splitIntoGroups(normalized).map(summarizeGroup);
  const batch = summaries.reduce((acc, g) => ({
    peakVoltage: Math.max(acc.peakVoltage, g.peakVoltage),
    peakCurrent: Math.max(acc.peakCurrent, g.peakCurrent),
    totalPower: acc.totalPower + g.totalPower,
    throttled: acc.throttled + g.throttled,
    alerts: acc.alerts + g.alerts,
    statusMask: (acc.statusMask | g.statusMask) & 255
  }), { peakVoltage: 0, peakCurrent: 0, totalPower: 0, throttled: 0, alerts: 0, statusMask: 0 });
  batch.groups = summaries.length;
  batch.pings = Math.floor(normalized.length / 64);
  batch.alertTriggered = batch.alerts > 0;
  return batch;
}

function formatReport(batch) {
  return [
    'groups processed : ' + batch.groups,
    'peak voltage     : ' + batch.peakVoltage.toFixed(1) + ' V',
    'peak current     : ' + batch.peakCurrent.toFixed(1) + ' A',
    'total power      : ' + batch.totalPower.toFixed(2) + ' kW',
    'throttled draws  : ' + batch.throttled,
    'substation pings : ' + batch.pings,
    'status flag      : 0x' + batch.statusMask.toString(16),
    'alert triggered  : ' + batch.alertTriggered
  ].join('\n');
}

