function buildWavetable() {
  const table = new Uint8Array(4096);
  const scale = (Math.PI * 2) / table.length;
  for (let i = 0; i < table.length; i++) {
    const shaped = (Math.sin(i * scale) + 1) / 2;
    table[i] = Math.round(shaped * 255);
  }
  return table;
}

function normalizeConfig(config) {
  const cfg = config || {};
  let attack = Math.round(Number(cfg.attack) || 0);
  if (attack < 16) {
    attack = 16;
  }
  const decay = 32;
  let sustain = cfg.sustain === undefined ? 128 : Math.round(Number(cfg.sustain));
  sustain = Math.min(Math.max(sustain, 0), 255);
  const hold = Math.max(Math.round(Number(cfg.hold) || 0), 0);
  let release = Math.max(Math.round(Number(cfg.release) || 0), 0);
  release = Math.min(release, 1024);
  const total = attack + decay + hold + release;
  if (total > 65535) {
    throw new RangeError("envelope cycle of " + total + " ms exceeds the hardware limit");
  }
  let phaseOffset = Math.round(Number(cfg.phaseOffset) || 0) % 256;
  if (phaseOffset < 0) {
    phaseOffset += 256;
  }
  return { peak: 255, attack, decay, sustain, hold, release, total, phaseOffset };
}

function createEnvelope(config) {
  const p = normalizeConfig(config);
  const table = buildWavetable();
  const stride = table.length / 256;
  return {
    params: p,
    amplitudeAt(ms) {
      if (ms <= 0 || ms >= p.total) return 0;
      if (ms < p.attack) return Math.round((ms / p.attack) * p.peak);
      const decayEnd = p.attack + p.decay;
      if (ms < decayEnd) {
        const k = (ms - p.attack) / p.decay;
        return Math.round(p.peak - (p.peak - p.sustain) * k);
      }
      const sustainEnd = decayEnd + p.hold;
      if (ms < sustainEnd) return p.sustain;
      const k = (ms - sustainEnd) / p.release;
      return Math.round(p.sustain * (1 - k));
    },
    renderBlock(startSample, sampleRate) {
      const out = new Uint8Array(64);
      for (let n = 0; n < out.length; n++) {
        const index = startSample + n;
        const level = this.amplitudeAt((index / sampleRate) * 1000);
        const phase = (p.phaseOffset + index) % 256;
        out[n] = Math.round((level * table[Math.floor(phase * stride)]) / 255);
      }
      return out;
    },
    renderAll(sampleRate) {
      const needed = Math.ceil((p.total / 1000) * sampleRate);
      const frames = [];
      for (let start = 0; start < needed; start += 64) {
        frames.push(this.renderBlock(start, sampleRate));
      }
      return frames;
    }
  };
