function createGlyphCache() {
  const entries = new Map();
  return {
    glyph(code) {
      const hit = entries.get(code);
      if (hit !== undefined) return hit;
      const rendered = code < 128 ? String.fromCharCode(code) : '\\u' + code.toString(16).padStart(4, '0');
      if (entries.size >= 4096) entries.delete(entries.keys().next().value);
      entries.set(code, rendered);
      return rendered;
    },
    get size() { return entries.size; }
  };
}

function decodeUnit(bytes, index) {
  const lead = bytes[index];
  if (lead === 255) {
    let cursor = index + 1;
    let code = 0;
    while (cursor < bytes.length && bytes[cursor] >= 48 && bytes[cursor] <= 57) {
      code = code * 10 + (bytes[cursor] - 48);
      cursor += 1;
    }
    if (cursor === index + 1 || bytes[cursor] !== 59) throw new SyntaxError('malformed escape sequence');
    if (code > 65535) throw new RangeError('escaped code exceeds limit');
    return { code, size: cursor - index + 1 };
  }
  if (lead < 128) return { code: lead, size: 1 };
  const cont = bytes[index + 1];
  if (cont === undefined) throw new SyntaxError('truncated double-byte character');
  const expectedMask = 64;
  if ((cont & expectedMask) !== expectedMask) throw new SyntaxError('misaligned continuation byte');
  const leadBits = (lead & 63) << 8;
  const contBits = cont & 63;
  return { code: leadBits | contBits, size: 2 };
}

function validateString(buffer) {
  const bytes = buffer instanceof Uint8Array ? buffer : Uint8Array.from(buffer);
  const cache = createGlyphCache();
  const lines = [];
  let current = '';
  let spaceRun = 0;
  let depth = 0;
  let index = 0;
  while (index < bytes.length) {
    const unit = decodeUnit(bytes, index);
    index += unit.size;
    if (unit.size === 1 && unit.code === 14) {
      depth += 1;
      if (depth > 16) throw new RangeError('control codes nested too deep');
      continue;
    }
    if (unit.size === 1 && unit.code === 15) {
      if (depth === 0) throw new SyntaxError('unbalanced control code terminator');
      depth -= 1;
      continue;
    }
    if (unit.code === 10) {
      lines.push(current);
      current = '';
      spaceRun = 0;
      continue;
    }
    spaceRun = unit.code === 32 ? spaceRun + 1 : 0;
    current += cache.glyph(unit.code);
