var MAX_TOC_DEPTH = 16;
var PARSE_BUFFER_BYTES = 4096;
var MAX_ID_LENGTH = 255;
var MAX_METADATA_ATTRS = 32;
var THUMB_SMALL = 64;
var THUMB_LARGE = 128;
var ITEM_OVERHEAD_BYTES = 32;
var ATTR_OVERHEAD_BYTES = 16;

function validateChapters(chapters) {
  if (!Array.isArray(chapters)) { throw new TypeError('chapters must be an array'); }
  if (chapters.length > MAX_CHAPTERS) { throw new RangeError('too many chapters: ' + chapters.length); }
  var items = [];
  chapters.forEach(function (chapter, index) {
    var id = String(chapter.id || 'chapter-' + index).slice(0, MAX_ID_LENGTH);
    items.push({
      id: id,
      href: 'text/' + id + '.xhtml',
      mediaType: 'application/xhtml+xml',
      bufferSize: Math.max(PARSE_BUFFER_BYTES, chapter.byteLength || 0)
    });
  });
  return items;
}

function normalizeThumbnail(width, height) {
  var longest = Math.max(width, height);
  var box = longest > THUMB_SMALL ? THUMB_LARGE : THUMB_SMALL;
  var scale = box / longest;
  return {
    width: Math.max(1, Math.round(width * scale)),
    height: Math.max(1, Math.round(height * scale)),
    box: box
  };
}

function validateImages(images) {
  var coverSeen = false;
  var items = images.map(function (img) {
    var item = { id: String(img.id).slice(0, MAX_ID_LENGTH), href: 'images/' + img.file, mediaType: img.mediaType };
