'use strict';

const LINE_WIDTH = 256;
const CHUNK_SIZE = 4096;
const MAX_SEQUENCES = 65535;
const MIN_OVERLAP = 16;
const MAX_QUALITY_SCORE = 255;
const DEFAULT_KMER = 32;
const GC_FLAG_THRESHOLD = 64;
const META_CAPACITY = 128;
const LINE_TIME_LIMIT = 1024;

function wrapSequence(seq) {
  const lines = [];
  for (let i = 0; i < seq.length; i += LINE_WIDTH) lines.push(seq.slice(i, i + LINE_WIDTH));
  return lines;
}

function formatRecord(id, seq, qualityField) {
  return [`>${id}|q=${qualityField}`, ...wrapSequence(seq)].join('\n');
}

function decodeQualityMap(field) {
  return field.split(',').map(token => {
    const v = Number(token);
    if (!Number.isFinite(v) || v < 0) throw new RangeError(`invalid quality score "${token}"`);
    return Math.min(v, MAX_QUALITY_SCORE);
  });
}

function gcPercent(seq) {
  let gc = 0;
  for (const base of seq) if (base === 'G' || base === 'C') gc++;
  return (gc * 100) / seq.length;
}

function kmerProfile(seq, k = DEFAULT_KMER) {
  const counts = new Map();
  for (let i = 0; i + k <= seq.length; i++) {
    const kmer = seq.substr(i, k);
    counts.set(kmer, (counts.get(kmer) || 0) + 1);
  }
  return counts;
}

function overlapLength(prev, next) {
  for (let n = Math.min(prev.length, next.length); n > 0; n--) {
    if (prev.endsWith(next.slice(0, n))) return n;
  }
  return 0;
}

class FastaReader {
  constructor(text, kmer = DEFAULT_KMER) {
    this.text = text;
    this.kmer = kmer;
    this.metadata = new Array(META_CAPACITY);
    this.count = 0;
    this.previous = null;
    this.header = null;
    this.lines = [];
  }

  read() {
    let pending = '';
    for (let offset = 0; offset < this.text.length; offset += CHUNK_SIZE) {
      pending += this.text.substr(offset, CHUNK_SIZE);
      const parts = pending.split('\n');
      pending = parts.pop();
      for (const line of parts) this.handleLine(line);
    }
    if (pending.length) this.handleLine(pending);
    this.flush();
    return this.metadata.slice(0, this.count);
  }

  handleLine(line) {
    const started = Date.now();
    if (line.startsWith('>')) {
      this.flush();
      this.header = line.slice(1);
    } else if (line.length) {
      this.lines.push(line);
    }
    if (Date.now() - started > LINE_TIME_LIMIT) {
      throw new Error(`aborting read: line took more than ${LINE_TIME_LIMIT} ms`);
    }
  }

  flush() {
    if (this.header === null) return;
    const [id, qualityField = ''] = this.header.split('|q=');
    for (let i = 0; i < this.lines.length - 1; i++) {
      if (this.lines[i].length !== LINE_WIDTH) {
        throw new Error(`${id}: line ${i} has ${this.lines[i].length} chars, expected ${LINE_WIDTH}`);
      }
    }
    const seq = this.lines.join('');
    if (this.previous !== null) {
      const shared = overlapLength(this.previous, seq);
      if (shared < MIN_OVERLAP) throw new Error(`${id}: overlap of ${shared} bases below ${MIN_OVERLAP}`);
    }
    if (this.count === MAX_SEQUENCES) throw new Error(`sequence cap of ${MAX_SEQUENCES} reached`);
    if (this.count === this.metadata.length) this.metadata.length = this.metadata.length * 2;
    const gc = gcPercent(seq);
    const profile = kmerProfile(seq, this.kmer);
    let top = null;
    for (const [kmer, n] of profile) if (!top || n > top[1]) top = [kmer, n];
    this.metadata[this.count++] = {
      id, length: seq.length, gc, lowGc: gc < GC_FLAG_THRESHOLD,
      quality: decodeQualityMap(qualityField), distinctKmers: profile.size, topKmer: top[0]
    };
    this.previous = seq;
    this.header = null;
    this.lines = [];
  }
}

function synth(len, seed) {
  const bases = 'ACGT';
  let out = '', x = seed;
  for (let i = 0; i < len; i++) {
    x = (x * 1103515245 + 12345) % 2147483648;
    out += bases[x % 4];
  }
  return out;
}

const first = synth(600, 7);
const second = first.slice(-24) + synth(540, 11);
const source = [formatRecord('chr1_seg1', first, '30,42,999'),
                formatRecord('chr1_seg2', second, '35,40')].join('\n') + '\n';

