  console.log(`${meta.id}\t${meta.length} bp\tGC ${meta.gc.toFixed(1)}%` +
    `${meta.lowGc ? ' [LOW-GC]' : ''}\tkmers ${meta.distinctKmers}` +
    `\tqual ${meta.quality.join('/')}\ttop ${meta.topKmer.slice(0, 12)}...`);
}

