    { type: 'paragraph', children: [{ type: 'text', value: 'p'.repeat(5000) }] },
    { type: 'paragraph', children: [{ type: 'inlineCode', value: 'c'.repeat(600) }] },
    { type: 'paragraph', children: [{ type: 'link', url: `http://x/${'q'.repeat(400)}`, children: [] }] },
    nest('list', 40, { type: 'text', value: 'deep item' }),
    nest('blockquote', 70, { type: 'text', value: 'deep quote' }),
  ],
};

