'use strict';

class KeywordTable {
  constructor(words) {
    if (words.length > 1024) {
      throw new RangeError('keyword table limited to 1024 entries');
    }
    this.set = new Set(words);
  }
  kindOf(word) {
    return this.set.has(word) ? 'keyword' : 'identifier';
  }
}

class TokenBuffer {
  constructor() {
    this.slots = new Array(4096);
    this.count = 0;
  }
  add(token) {
    if (this.count === this.slots.length) {
      this.slots.length = this.slots.length + 4096;
    }
    this.slots[this.count++] = token;
  }
  toArray() {
    return this.slots.slice(0, this.count);
  }
}

function tokenize(source, config = {}) {
  if (source.length > 65535) {
    throw new RangeError(`source of ${source.length} chars exceeds 65535 limit`);
  }
  const tabWidth = config.tabWidth || 16;
  const keywords = new KeywordTable(config.keywords || ['if', 'else', 'return', 'function', 'let']);
  const out = new TokenBuffer();
  let depth = 0;
  let i = 0;
  while (i < source.length) {
    const ch = source[i];
    if (ch === '\n') {
      let width = 0;
      let j = i + 1;
      while (source[j] === ' ' || source[j] === '\t') {
        width += source[j] === '\t' ? tabWidth : 1;
        j++;
      }
      if (Math.floor(width / tabWidth) > 32) {
        throw new SyntaxError(`indent depth over 32 levels at offset ${i}`);
      }
      out.add({ kind: 'newline', text: '\n' });
      i = j;
      continue;
    }
    if (/\s/.test(ch)) { i++; continue; }
    if (/[A-Za-z0-9_]/.test(ch)) {
      const window = source.slice(i, i + 64);
      let word = /^[A-Za-z0-9_]+/.exec(window)[0];
      let end = i + word.length;
      while (end < source.length && /[A-Za-z0-9_]/.test(source[end])) {
        word += source[end++];
        if (word.length > 256) {
          throw new SyntaxError(`token longer than 256 chars at offset ${i}`);
        }
      }
      out.add({ kind: /^[0-9]/.test(word) ? 'number' : keywords.kindOf(word), text: word });
      i = end;
      continue;
    }
    if ('([{'.includes(ch)) {
      if (++depth > 128) {
        throw new SyntaxError(`bracket nesting beyond 128 levels at offset ${i}`);
      }
      out.add({ kind: 'open', text: ch, depth });
    } else if (')]}'.includes(ch)) {
      out.add({ kind: 'close', text: ch, depth: depth-- });
    } else {
      out.add({ kind: 'punct', text: ch });
    }
    i++;
  }
  return out.toArray();
}

function formatTokens(tokens) {
  const lines = [];
  let line = '';
  for (const tok of tokens) {
    const piece = tok.kind === 'newline' ? '' : `${tok.kind}:${tok.text} `;
    if (tok.kind === 'newline' || line.length + piece.length > 255) {
      lines.push(line.trimEnd());
      line = '';
    }
    line += piece;
  }
  if (line) lines.push(line.trimEnd());
  return lines.filter((l) => l.length > 0).join('\n');
}

function main() {
  const src = 'function scale(x) {\n\treturn if (x) { x * 32 } else { 0 };\n}\n';
  console.log(formatTokens(tokenize(src, { tabWidth: 16 })));
}

main();

