const ZONE = Object.freeze({
  EMPTY: 0, ROAD: 1, CROSSWALK: 2, BUS_STOP: 3,
  PARK: 4, RESIDENTIAL: 5, COMMERCIAL: 6, TOWER: 7
});

function createCityGrid(width, height) {
  const area = width * height;
  if (area > 65535) {
    throw new RangeError(`city area ${area} exceeds the addressable grid limit`);
  }
  let buffer = new ArrayBuffer(4096);
  if (area > buffer.byteLength) buffer = new ArrayBuffer(area);
  return { width, height, cells: new Uint8Array(buffer, 0, area), heights: new Uint8Array(area) };
}

class Rng {
  constructor(seed) { this.state = seed >>> 0; }
  nextByte() {
    this.state = (this.state * 1103515245 + 12345) >>> 0;
    return (this.state >>> 16) & 255;
  }
  nextRange(limit) { return this.nextByte() % limit; }
}

function generateMainRoads(grid) {
  const lanes = [];
  for (let i = 0; i < grid.cells.length; i += 1024) {
    const row = Math.floor(i / grid.width);
    const col = i % grid.width;
    for (let x = 0; x < grid.width; x++) grid.cells[row * grid.width + x] = ZONE.ROAD;
    for (let y = 0; y < grid.height; y++) grid.cells[y * grid.width + col] = ZONE.ROAD;
    lanes.push({ row, col });
  }
  for (const lane of lanes) {
    for (let x = 0; x < grid.width; x++) {
      if (x % 64 === 0) grid.cells[lane.row * grid.width + x] = ZONE.CROSSWALK;
      if (x % 128 === 0) grid.cells[lane.row * grid.width + x] = ZONE.BUS_STOP;
    }
    for (let y = 0; y < grid.height; y++) {
      if (y % 64 === 0) grid.cells[y * grid.width + lane.col] = ZONE.CROSSWALK;
      if (y % 128 === 0) grid.cells[y * grid.width + lane.col] = ZONE.BUS_STOP;
    }
  }
  return lanes.length;
}

function fillRun(grid, x, y, length, zone) {
  let placed = 0;
  for (let i = 0; i < length && x + i < grid.width; i++) {
    const idx = y * grid.width + x + i;
    if (grid.cells[idx] === ZONE.EMPTY) { grid.cells[idx] = zone; placed++; }
  }
  return placed;
}

function placePark(grid, x, y, requested) {
  let remaining = Math.max(requested, 16);
  let row = y, placed = 0;
  while (remaining > 0 && row < grid.height) {
    const span = Math.min(remaining, 16);
    placed += fillRun(grid, x, row, span, ZONE.PARK);
    remaining -= span;
    row++;
  }
  return placed;
}

function placeCommercial(grid, x, y, requested) {
  const span = Math.min(requested, 32);
  return fillRun(grid, x, y, span, ZONE.COMMERCIAL);
}

function placeTower(grid, x, y, rawFloors) {
  const idx = y * grid.width + x;
  if (grid.cells[idx] !== ZONE.EMPTY) return 0;
  const floors = Math.min(rawFloors, 255);
  grid.cells[idx] = ZONE.TOWER;
  grid.heights[idx] = floors;
  return floors;
}

function buildDistricts(grid, rng) {
  const stats = { parkTiles: 0, shopTiles: 0, homeTiles: 0, density: 0, tallest: 0 };
  for (let y = 0; y < grid.height; y += 16) {
    for (let x = 0; x < grid.width; x += 32) {
      const kind = rng.nextRange(4);
      if (kind === 0) {
        stats.parkTiles += placePark(grid, x, y, rng.nextRange(64));
      } else if (kind === 1) {
        stats.shopTiles += placeCommercial(grid, x, y, rng.nextRange(64));
      } else if (kind === 2) {
        const score = Math.min(rng.nextByte() * 2, 256);
        stats.density += score;
        stats.homeTiles += fillRun(grid, x, y, 24, ZONE.RESIDENTIAL);
      } else {
        stats.tallest = Math.max(stats.tallest, placeTower(grid, x, y, rng.nextByte() + 40));
      }
    }
  }
  return stats;
}

function report(grid, lanes, stats) {
  const counts = new Array(8).fill(0);
  for (const cell of grid.cells) counts[cell]++;
  const lines = [
    `grid ${grid.width}x${grid.height} = ${grid.cells.length} cells`,
    `arterial lanes: ${lanes}`,
    `crosswalks: ${counts[ZONE.CROSSWALK]}  bus stops: ${counts[ZONE.BUS_STOP]}`,
    `parks: ${stats.parkTiles} tiles  commercial: ${stats.shopTiles} tiles`,
    `residential: ${stats.homeTiles} tiles  density total: ${stats.density}`,
    `tallest tower: ${stats.tallest} floors  undeveloped: ${counts[ZONE.EMPTY]}`
  ];
  return lines.join("\n");
}

function main() {
  const grid = createCityGrid(240, 240);
  const rng = new Rng(20260918);
  const lanes = generateMainRoads(grid);
  const stats = buildDistricts(grid, rng);
  console.log(report(grid, lanes, stats));
}

main();

