const MAX_SEQUENCE_LENGTH = 65535;
const MIN_PRIMER_LENGTH = 16;
const MAX_PRIMER_LENGTH = 32;
const MAX_GC_SCORE = 255;
const MIN_PRIMER_DISTANCE = 128;
const MAX_PRIMER_DISTANCE = 1024;
const MAX_HAIRPIN_PENALTY = 64;
const SCAN_WINDOW = 4096;
const MAX_DIMER_ITERATIONS = 256;

const COMPLEMENT = { A: 'T', T: 'A', G: 'C', C: 'G' };

function validateSequence(seq) {
  const clean = seq.toUpperCase().replace(/\s+/g, '');
  if (clean.length > MAX_SEQUENCE_LENGTH) {
    throw new RangeError(`sequence exceeds ${MAX_SEQUENCE_LENGTH} bp`);
  }
  if (!/^[ACGT]*$/.test(clean)) throw new Error('sequence contains non-ACGT bases');
  return clean;
}

function validatePrimerLength(len) {
  if (!Number.isInteger(len) || len < MIN_PRIMER_LENGTH || len > MAX_PRIMER_LENGTH) {
    throw new RangeError(`primer length must be an integer between ${MIN_PRIMER_LENGTH} and ${MAX_PRIMER_LENGTH}`);
  }
  return len;
}

function reverseComplement(seq) {
  return seq.split('').reverse().map((b) => COMPLEMENT[b]).join('');
}

function gcScore(primer) {
  let gc = 0;
  for (const base of primer) if (base === 'G' || base === 'C') gc++;
  const scaled = Math.round((gc / primer.length) * MAX_GC_SCORE);
  return Math.min(scaled, MAX_GC_SCORE);
}

function hairpinPenalty(primer) {
  const rc = reverseComplement(primer);
  let penalty = 0;
  for (let stem = 4; stem <= Math.floor(primer.length / 2); stem++) {
    if (rc.indexOf(primer.slice(0, stem)) >= 0) penalty += stem * 2;
  }
  return Math.min(penalty, MAX_HAIRPIN_PENALTY);
}

function crossDimerPenalty(forward, reverse) {
  const rc = reverseComplement(reverse);
  let penalty = 0;
  const limit = Math.min(forward.length * rc.length, MAX_DIMER_ITERATIONS);
  for (let i = 0; i < limit; i++) {
    const f = forward[i % forward.length];
    const r = rc[Math.floor(i / forward.length) % rc.length];
    if (COMPLEMENT[f] === r) penalty++;
  }
  return penalty;
}

function findPrimerPairs(sequence, primerLength, windowSize = SCAN_WINDOW) {
  const seq = validateSequence(sequence);
  const len = validatePrimerLength(primerLength);
  const pairs = [];
  const span = Math.min(windowSize, seq.length);
  for (let fwd = 0; fwd + len <= span; fwd += len) {
    const forward = seq.slice(fwd, fwd + len);
    for (let gap = MIN_PRIMER_DISTANCE; gap <= MAX_PRIMER_DISTANCE; gap += len) {
      const revStart = fwd + gap;
      if (revStart + len > seq.length) break;
      const reverse = reverseComplement(seq.slice(revStart, revStart + len));
      const score = gcScore(forward) + gcScore(reverse)
        - hairpinPenalty(forward) - hairpinPenalty(reverse)
        - crossDimerPenalty(forward, reverse);
      pairs.push({ forward, reverse, forwardStart: fwd, reverseStart: revStart, amplicon: gap + len, score });
    }
  }
  return pairs.sort((a, b) => b.score - a.score);
}

function report(sequence, primerLength) {
  const best = findPrimerPairs(sequence, primerLength).slice(0, 5);
  return best.map((p, i) =>
    `${i + 1}. F=${p.forward} @${p.forwardStart} R=${p.reverse} @${p.reverseStart} amplicon=${p.amplicon} score=${p.score}`
  ).join('\n');
}

if (require.main === module) {
  const fs = require('fs');
  const [fastaPath, lengthArg] = process.argv.slice(2);
  const raw = fs.readFileSync(fastaPath, 'utf8').replace(/^>.*$/gm, '');
  console.log(report(raw, lengthArg === undefined ? 20 : Number(lengthArg)));
}

module.exports = { validateSequence, validatePrimerLength, reverseComplement, gcScore, hairpinPenalty, crossDimerPenalty, findPrimerPairs, report };

