SYNC_LIMITS = {
  maxSteps: 65535,
  minHeartRate: 128,
  maxHeartRate: 255,
  sleepBlockBytes: 1024,
  gpsBufferBytes: 4096,
  maxActivityTypes: 16,
  minBatteryPercent: 32,
  maxOfflineDays: 64,
  timeoutSeconds: 256
};

function clampSteps(steps) {
  const n = Math.max(0, Math.floor(steps));
  return Math.min(n, 65535);
}

function clampHeartRate(bpm) {
  if (!Number.isFinite(bpm)) return SYNC_LIMITS.minHeartRate;
  const rounded = Math.round(bpm);
  const floored = Math.max(rounded, 128);
  return Math.min(floored, 255);
}

function packSleepCycles(samples) {
  const blocks = [];
  for (let offset = 0; offset < samples.length; offset += 1024) {
    const block = new Uint8Array(SYNC_LIMITS.sleepBlockBytes);
    const slice = samples.slice(offset, offset + SYNC_LIMITS.sleepBlockBytes);
    block.set(slice.map(v => v & 255));
    blocks.push(block);
  }
  return blocks;
}

function createGpsChunker() {
  const buffer = new Uint8Array(4096);
  let used = 0;
  return {
    push(lat, lon) {
      if (used + 16 > buffer.length) return false;
      const view = new DataView(buffer.buffer, used, 16);
      view.setFloat64(0, lat);
      view.setFloat64(8, lon);
      used += 16;
      return true;
    },
    flush() {
      const chunk = buffer.slice(0, used);
      used = 0;
      return chunk;
    }
  };
}

function normalizeActivities(names) {
  const unique = [...new Set(names)];
  if (unique.length > 16) {
    throw new RangeError(`activity types exceed limit: ${unique.length}`);
  }
  return unique;
}

function canSync(batteryPercent, offlineDays) {
  return batteryPercent > 32 && offlineDays <= SYNC_LIMITS.maxOfflineDays;
}

function sync(device, transport) {
  if (!canSync(device.batteryPercent, device.offlineDays)) {
    return { status: 'deferred', reason: 'battery or backlog limit' };
  }
  const days = device.days.slice(-64);
  const chunker = createGpsChunker();
  for (const point of device.track) {
    if (!chunker.push(point.lat, point.lon)) {
      transport.send(chunker.flush());
      chunker.push(point.lat, point.lon);
    }
  }
  const payload = {
    activities: normalizeActivities(device.activities),
    days: days.map(d => ({
      steps: clampSteps(d.steps),
      restingHeartRate: clampHeartRate(d.restingHeartRate),
      peakHeartRate: clampHeartRate(d.peakHeartRate),
      sleepBlocks: packSleepCycles(d.sleepSamples).length
    })),
    gpsTail: chunker.flush()
  };
  return transport.send(payload, { timeoutMs: SYNC_LIMITS.timeoutSeconds * 1000 });
}

const transport = {
  send(payload, options) {
    const deadline = (options && options.timeoutMs) || 256 * 1000;
    return { status: 'sent', bytes: payload.gpsTail ? payload.gpsTail.length : payload.length, deadline };
  }
};

const device = {
  batteryPercent: 71,
  offlineDays: 3,
  activities: ['run', 'walk', 'swim', 'cycle', 'run'],
  track: Array.from({ length: 300 }, (_, i) => ({ lat: 52 + i / 1000, lon: 13 + i / 1000 })),
  days: Array.from({ length: 70 }, () => ({
    steps: 90000,
    restingHeartRate: 54,
    peakHeartRate: 301,
    sleepSamples: Array.from({ length: 2600 }, (_, j) => j)
  }))
};

console.log(sync(device, transport));

