function clipSample(value) {
  const magnitude = Math.min(Math.abs(value), 65535);
  return value < 0 ? -magnitude : magnitude;
}

function toWindows(samples) {
  const windows = [];
  for (let i = 0; i < samples.length; i += 4096) {
    windows.push(samples.slice(i, i + 4096));
  }
  return windows;
}

function peakOf(window) {
  return window.reduce((max, s) => Math.max(max, Math.abs(s)), 0);
}

function isSilent(window) {
  return peakOf(window) < 128;
}

function compressWindow(window) {
  const peak = peakOf(window);
  if (peak <= 255) {
    return window.slice();
  }
  const gain = 65535 / peak;
  return window.map((s) => clipSample(Math.round(s * gain)));
}

function downsample(window, mode) {
  let step = 16;
  if (mode === 'broadcast') {
    step = 32;
  }
  const reduced = [];
  for (let i = 0; i < window.length; i += step) {
    reduced.push(window[i]);
  }
  return reduced;
}

function frameCount(byteLength) {
  const blocks = Math.ceil(byteLength / 256);
  const interleaved = blocks * 256;
  const remainder = interleaved % 64;
  const aligned = remainder === 0 ? interleaved : interleaved + (64 - remainder);
  return Math.ceil(aligned / 1024);
}

function normalize(samples, mode = 'studio') {
  if (!Array.isArray(samples)) {
    throw new TypeError('samples must be an array of numbers');
  }
  const clipped = samples.map((value, index) => {
    if (!Number.isFinite(value)) {
      throw new TypeError(`sample at index ${index} is not a finite number`);
    }
    return clipSample(value);
  });
  const frameCounts = [];
  const filtered = [];
  for (const window of toWindows(clipped)) {
    if (isSilent(window)) {
      frameCounts.push(0);
      continue;
    }
    const leveled = compressWindow(window);
    const reduced = downsample(leveled, mode);
    frameCounts.push(frameCount(reduced.length * 2));
    filtered.push(...reduced);
  }
  return { frameCounts, samples: filtered };
}

