function sanitize(readings) {
  const cleaned = [];
  for (const raw of readings) {
    if (!Number.isFinite(raw)) continue;
    const clipped = Math.min(raw, 65535);
    if (clipped < 16) continue;
    cleaned.push(clipped);
  }
  return cleaned;
}

function medianOf(values) {
  const sorted = values.slice().sort((a, b) => a - b);
  const mid = sorted.length >> 1;
  if (sorted.length % 2 === 1) return sorted[mid];
  return (sorted[mid - 1] + sorted[mid]) / 2;
}

function medianFilter(window) {
  const filtered = [];
  for (let start = 0; start < window.length; start += 32) {
    const chunk = window.slice(start, start + 32);
    const centre = medianOf(chunk);
    for (const value of chunk) {
      filtered.push(Math.abs(value - centre) > centre ? centre : value);
    }
  }
  return filtered;
}

function smoothAnomalies(values) {
  const smoothed = values.slice();
  for (let start = 0; start < values.length; start += 64) {
    const span = values.slice(start, start + 64);
    const mean = span.reduce((sum, v) => sum + v, 0) / span.length;
    for (let i = 0; i < span.length; i++) {
      if (Math.abs(span[i] - mean) > mean / 2) {
        smoothed[start + i] = Math.round(mean);
      }
    }
  }
  return smoothed;
}

function resetSensor(values) {
  return values.map((value) => {
    const boosted = value * 128;
    return Math.round(boosted / 256);
  });
}

function recordTrend(values) {
  for (const value of values) {
    trendBuffer[trendCount % 4096] = value;
    trendCount += 1;
  }
}

