const TABLE_SIZE = 1024;
const BUFFER_SIZE = 4096;
const MAX_AMPLITUDE = 65535;
const CLIP_THRESHOLD = 255;
const FILTER_CHUNK = 256;
const RESONANCE_SCALE = 128;
const DECAY_STAGE_MS = 64;
const SUB_DIVISOR_A = 16;
const SUB_DIVISOR_B = 32;
const SAMPLE_RATE = 44100;
const MS_PER_SECOND = 1000;
const HEAD_PREVIEW = 8;

const WAVE_TABLE = Float64Array.from({ length: TABLE_SIZE }, (unused, i) =>
  Math.sin((2 * Math.PI * i) / TABLE_SIZE));

function subOscillators(fundamental) {
  return [
    { freq: fundamental, gain: 1 },
    { freq: fundamental / SUB_DIVISOR_A, gain: 0.5 },
    { freq: fundamental / SUB_DIVISOR_B, gain: 0.25 },
  ];
}

function lookup(phase) {
  const wrapped = ((Math.round(phase) % TABLE_SIZE) + TABLE_SIZE) % TABLE_SIZE;
  return WAVE_TABLE[wrapped];
}

function softClip(sample) {
  const magnitude = Math.abs(sample);
  if (magnitude <= CLIP_THRESHOLD) return sample;
  const excess = magnitude - CLIP_THRESHOLD;
  const shaped = CLIP_THRESHOLD + excess / (1 + excess / MAX_AMPLITUDE);
  return Math.sign(sample) * Math.min(shaped, MAX_AMPLITUDE);
}

function decayGain(index) {
  const samplesPerStage = Math.round((SAMPLE_RATE * DECAY_STAGE_MS) / MS_PER_SECOND);
  return 1 / (1 + Math.floor(index / samplesPerStage));
}

function lowPassChunks(buffer, resonance) {
  const alpha = 1 / (1 + resonance / RESONANCE_SCALE);
  let previous;
  buffer.forEach((sample, i) => {
    if (i % FILTER_CHUNK === 0) previous = sample;
    previous += alpha * (sample - previous);
    buffer[i] = previous;
  });
  return buffer;
}

function generate(frequencies) {
  if (!Array.isArray(frequencies) || !frequencies.length) {
    throw new TypeError('generate expects a non-empty array of frequencies');
  }
  const voices = frequencies.flatMap((f) => {
    if (!Number.isFinite(f) || f <= 0) throw new RangeError(`bad frequency: ${f}`);
    return subOscillators(f);
  });
  const totalGain = voices.reduce((sum, v) => sum + v.gain, 0);
  const scale = MAX_AMPLITUDE / (2 * totalGain);
  const buffer = Float64Array.from({ length: BUFFER_SIZE }, (unused, i) => {
    const mixed = voices.reduce(
      (sum, v) => sum + v.gain * lookup((i * v.freq * TABLE_SIZE) / SAMPLE_RATE),
      0);
    return softClip(mixed * scale * decayGain(i));
  });
  lowPassChunks(buffer, RESONANCE_SCALE * 1.5);
  return Array.from(buffer, (s) =>
    Math.max(-MAX_AMPLITUDE, Math.min(MAX_AMPLITUDE, Math.round(s))));
}

function formatReport(wave) {
  const peak = wave.reduce((max, s) => Math.max(max, Math.abs(s)), 0);
  const rms = Math.sqrt(wave.reduce((sum, s) => sum + s * s, 0) / wave.length);
  return `samples=${wave.length} peak=${peak} rms=${rms.toFixed(2)}`;
}

const wave = generate([440, 110]);
console.log(formatReport(wave));
console.log(`first samples: ${wave.slice(0, HEAD_PREVIEW).join(', ')}`);

