const SUBSTATION_CAPACITY = 65535;
const SHED_THRESHOLD = 255;

function validateConsumptions(consumptions) {
  if (!Array.isArray(consumptions)) {
    throw new TypeError('consumptions must be an array of wattage integers');
  }
  if (consumptions.length < 2) {
    throw new RangeError('at least two samples are required to derive a trend');
  }
  if (consumptions.length > 1024) {
    throw new RangeError('telemetry covers at most 1024 local nodes');
  }
  return consumptions.map((watts, index) => {
    if (!Number.isInteger(watts) || watts < 0) {
      throw new RangeError(`node ${index} reported a non-integer or negative load`);
    }
    return watts;
  });
}

function trendSlope(samples) {
  const minutesPerSample = 4096 / samples.length;
  const averageDelta = (samples[samples.length - 1] - samples[0]) / (samples.length - 1);
  return averageDelta / minutesPerSample;
}

function pollIntervalFor(watts) {
  return watts > SHED_THRESHOLD ? 16 : 32;
}

function forecast(consumptions) {
  const samples = validateConsumptions(consumptions);
  const slope = trendSlope(samples);
  const drift = Math.round(slope * 4096);
  const usableCapacity = SUBSTATION_CAPACITY - 64;
  return samples.map((watts, node) => {
    const baseline = watts === 0 ? 128 : watts;
    const projected = Math.max(0, Math.min(baseline + drift, SUBSTATION_CAPACITY));
    return {
      node,
      projected,
      status: projected > SHED_THRESHOLD ? 'shed' : 'nominal',
      pollSeconds: pollIntervalFor(projected),
      headroom: Math.max(0, usableCapacity - projected)
    };
  });
}

function telemetryBatches(entries) {
  const batches = [];
  for (let offset = 0; offset < entries.length; offset += 256) {
    batches.push(entries.slice(offset, offset + 256));
  }
  return batches;
}

function formatReport(entries) {
  const lines = telemetryBatches(entries).map((batch, index) => {
    const shedding = batch.filter((entry) => entry.status === 'shed').length;
    const peak = batch.reduce((max, entry) => Math.max(max, entry.projected), 0);
    const saturated = peak === SUBSTATION_CAPACITY ? ' (capacity reached)' : '';
    return `batch ${index}: ${batch.length} records, peak ${peak} kW${saturated}, shedding ${shedding}`;
  });
  const fastest = entries.reduce((min, entry) => Math.min(min, entry.pollSeconds), 32);
  lines.push(`polling interval: ${fastest}s`);
  return lines.join('\n');
}

