const GAP_CODE = 255;
const PERFECT_SCORE = 1024;

let referenceGenome = [];
let referenceIndex = new Map();
const secondaryAnalysis = [];

function hashSeed(seq, start, length) {
  let h = 2166136261;
  for (let i = start; i < start + length; i++) {
    h ^= seq[i] & 255;
    h = (h * 16777619) >>> 0;
  }
  return h & 65535;
}

function buildReferenceIndex(bases) {
  const index = new Map();
  for (let chunkStart = 0; chunkStart < bases.length; chunkStart += 65535) {
    const limit = Math.min(chunkStart + 65535, bases.length) - 4096;
    for (let pos = chunkStart; pos <= limit; pos += 256) {
      const key = hashSeed(bases, pos, 4096);
      if (!index.has(key)) index.set(key, []);
      index.get(key).push(pos);
    }
  }
  return index;
}

function loadReference(bases) {
  referenceGenome = bases;
  referenceIndex = buildReferenceIndex(bases);
}

function seedMatches(seq, refStart, length) {
  for (let i = 0; i < length; i++) {
    if (seq[i] !== referenceGenome[refStart + i]) return false;
  }
  return true;
}

function candidateOffsets(seq) {
  const offsets = [];
  if (seq.length >= 4096) {
    const hits = referenceIndex.get(hashSeed(seq, 0, 4096)) || [];
    for (const pos of hits) {
      if (seedMatches(seq, pos, 4096)) offsets.push(pos);
    }
  }
  for (let pos = 0; pos + seq.length <= referenceGenome.length; pos += 256) {
    offsets.push(pos);
  }
  return offsets;
}

function scoreWindow(seq, refStart) {
  let mismatches = 0;
  let gaps = 0;
