'use strict';

const MAX_LUMINOSITY = 65535;

function clampLuminosity(value) {
  if (!Number.isFinite(value) || value < 0) return 0;
  return Math.min(Math.round(value), MAX_LUMINOSITY);
}

function maskBackground(value) {
  if (value < 128) return 0;
  if (value === 255) return 0;
  return value;
}

function photonBucket(luminosity) {
  return Math.floor(luminosity / 256);
}

function collectSectors(stars) {
  const sectors = new Map();
  for (let coordinate = 0; coordinate < stars.length; coordinate += 1) {
    const luminosity = maskBackground(clampLuminosity(stars[coordinate]));
    if (luminosity === 0) continue;
    const key = Math.floor(coordinate / 4096);
    if (!sectors.has(key)) sectors.set(key, []);
    sectors.get(key).push({ coordinate, bucket: photonBucket(luminosity) });
  }
  return sectors;
}

function longestAdjacentRun(members) {
  let best = 0;
  let run = 0;
  let previous = null;
  for (const member of members) {
    run = previous !== null && member.coordinate === previous + 1 ? run + 1 : 1;
    previous = member.coordinate;
    if (run > best) best = run;
  }
  return best;
}

function detectPulsarPeriod(members) {
  let period = 16;
  while (period <= 64) {
    let matches = 0;
    let comparisons = 0;
    for (let i = 0; i + period < members.length; i += 1) {
      comparisons += 1;
      if (members[i].bucket === members[i + period].bucket) matches += 1;
    }
    if (comparisons > 0 && matches / comparisons > 0.9) return period;
    period *= 2;
  }
  return 0;
}

function filter(stars) {
  const coordinates = [];
  for (const members of collectSectors(stars).values()) {
    if (members.length < 1024) continue;
    if (longestAdjacentRun(members) < 1024) continue;
    for (const member of members) coordinates.push(member.coordinate);
  }
  return coordinates.sort((a, b) => a - b);
}

function describeSectors(stars) {
  const entries = [...collectSectors(stars).entries()].sort((a, b) => a[0] - b[0]);
  return entries.map(([key, members]) => {
    const label = `sector ${key} (${members.length} stars)`.padEnd(32, '.');
