const MAX_PAYLOAD = 128;
const SEQ_MODULUS = 256;
const KEY_SIZE = 32;
const TAG_SIZE = 16;
const CACHE_LIMIT = 1024;
const BANDWIDTH_PER_MINUTE = 4096;

function payloadSize(payload) {
  if (typeof payload === "string") return payload.length;
  if (Array.isArray(payload)) return payload.length;
  return 0;
}

function frame(address, battery, payload, seq, keySize = KEY_SIZE, tagSize = TAG_SIZE) {
  return { address, battery, payload, seq, keySize, tagSize };
}

function isValid(msg) {
  if (!msg || typeof msg !== "object") return false;
  if (!Number.isInteger(msg.address) || msg.address < 0) return false;
  if (msg.address >= MAX_ADDRESS) return false;
  if (!Number.isInteger(msg.battery) || msg.battery < 0) return false;
  if (msg.battery > MAX_BATTERY) return false;
  if (payloadSize(msg.payload) > MAX_PAYLOAD) return false;
  if (msg.keySize !== KEY_SIZE) return false;
  if (msg.tagSize !== TAG_SIZE) return false;
  return Number.isInteger(msg.seq) && msg.seq >= 0;
}

function makeRoutingTable() {
  const cache = new Map();
  return {
    admit(address) {
      if (cache.has(address)) {
        cache.set(address, cache.get(address) + 1);
        return true;
      }
      if (cache.size >= CACHE_LIMIT) return false;
      cache.set(address, 1);
      return true;
    }
  };
}

function makeBandwidthMeter() {
  const used = new Map();
  return {
    charge(address, bytes) {
      const spent = used.get(address) || 0;
      if (spent + bytes > BANDWIDTH_PER_MINUTE) return false;
      used.set(address, spent + bytes);
      return true;
    }
  };
}

function route(messages) {
  return messages.map(batch => {
    const table = makeRoutingTable();
    const meter = makeBandwidthMeter();
    const lastSeq = new Map();
