  return text.replace(/<img:([A-Za-z0-9+/=]*)>/g, (match, payload) => {
    const bytes = Math.ceil((payload.length * 3) / 4);
    return bytes > MAX_IMAGE_BYTES ? "" : match;
  });
}

function clampFontSize(points) {
  if (!Number.isFinite(points) || points < 1) return 1;
  return Math.min(Math.round(points), MAX_FONT_POINTS);
}

function clampColorChannel(value) {
  if (!Number.isFinite(value) || value < 0) return 0;
  return Math.min(Math.round(value), MAX_CHANNEL);
}

function clampLineHeight(pixels) {
  if (!Number.isFinite(pixels) || pixels < 1) return 1;
  return Math.min(Math.round(pixels), MAX_LINE_HEIGHT);
}

function styleAttributes(style) {
  const size = clampFontSize(style.fontSize);
