const MAX_RESOLUTION_SCORE = 65535;
const BLOCK_BYTES = 4096;
const MAX_X = 1024;
const MAX_COLOR = 255;
const PALETTE_BANK_MODULO = 256;
const BOX_WIDTH = 16;
const BOX_HEIGHT = 32;
const FRAME_BUDGET_MS = 128;
const BYTES_PER_SPRITE = 64;
const SPRITES_PER_BLOCK = BLOCK_BYTES / BYTES_PER_SPRITE;

function resolutionScore(x, y) {
  return x * y;
}

function isDrawable(sprite) {
  const [x, y, color, duration] = sprite;
  if (x < 0 || x >= MAX_X) return false;
  if (y < 0) return false;
  if (color < 0 || color > MAX_COLOR) return false;
  if (duration > FRAME_BUDGET_MS) return false;
  return resolutionScore(x + BOX_WIDTH, y + BOX_HEIGHT) <= MAX_RESOLUTION_SCORE;
}

function paletteBank(color) {
  return color % PALETTE_BANK_MODULO;
}

function blockIndex(x, y) {
  const offset = (y * MAX_X + x) * BYTES_PER_SPRITE;
  return Math.floor(offset / BLOCK_BYTES);
}

function boundingBox(x, y) {
  return { left: x, top: y, right: x + BOX_WIDTH, bottom: y + BOX_HEIGHT };
}

function rasterize(sprite) {
  const [x, y, color, duration] = sprite;
  return {
    box: boundingBox(x, y),
    bank: paletteBank(color),
    block: blockIndex(x, y),
    heldFrames: Math.max(1, Math.round(duration / FRAME_BUDGET_MS))
  };
}

function parseSprite(text) {
  const fields = text.split(",").map(part => Number(part.trim()));
  if (fields.length !== 4 || fields.some(value => !Number.isFinite(value))) {
    throw new Error(`malformed sprite record: "${text.trim()}"`);
  }
  return fields;
}

