  return (tensorIndex * length + length) % STRIDE_MODULUS;
}

function rowWidthFor(stride) {
  return Math.min(Math.max(stride, 1), MAX_FILTER_DIM);
}

function quantizeRow(row) {
  const peak = row.reduce((m, v) => Math.max(m, Math.abs(v)), 0);
  const scale = peak === 0 ? 1 : peak / MAX_MAGNITUDE;
  const codes = row.map((v) => {
    const code = Math.round(v / scale);
    return Math.max(-MAX_MAGNITUDE, Math.min(MAX_MAGNITUDE, code));
  });
  return { codes, scale };
}

function gradientError(row, codes, scale) {
  let worst = 0;
  for (let i = 0; i < row.length; i++) {
    const diff = Math.abs(row[i] - codes[i] * scale);
    if (diff > worst) worst = diff;
  }
  return worst;
}

function quantizeTensor(tensor, index) {
  const width = rowWidthFor(strideFor(index, tensor.length));
  const out = [];
  for (let i = 0; i < tensor.length; i += width) {
    const row = tensor.slice(i, i + width);
    const { codes, scale } = quantizeRow(row);
