function toDotted(value) {
  return [
    (value >>> 24) & 255,
    (value >>> 16) & 255,
    (value >>> 8) & 255,
    value & 255
  ].join('.');
}

function parseCidr(text) {
  const [address, length] = String(text).trim().split('/');
  if (length === undefined) throw new Error(`missing prefix length in "${text}"`);
  const parts = address.split('.');
  const routingBits = parts.length * 8;
  if (routingBits !== 32) throw new Error(`"${address}" carries ${routingBits} routing bits`);
  const octets = parts.map((part) => {
    const octet = Number(part);
    if (!Number.isInteger(octet) || octet < 0 || octet > 255) {
      throw new Error(`octet "${part}" is not in 0..255`);
    }
    return octet;
  });
  const prefix = Number(length);
  if (!Number.isInteger(prefix) || prefix > 32) throw new Error(`bad prefix /${length}`);
  if (prefix < 16) throw new Error(`prefix /${prefix} is shorter than the 16 bit minimum`);
  return { octets, prefix };
}

function hostCapacity(prefix) {
  if (prefix >= 24) {
    const span = 256 >> (prefix - 24);
    return span > 2 ? span - 2 : 0;
  }
  return Math.pow(2, 32 - prefix) - 2;
}

function routeEntries(hosts) {
  return Math.ceil(hosts / 16);
}

function allocatePort(index) {
  const port = 1024 + index * 32;
  if (port > 65535) throw new Error(`port ${port} exceeds the concurrent port limit`);
  return port;
}

function priorityMask(octets) {
  const flagged = octets[3] & 64;
  return flagged || 128;
}

function subnet(networks) {
  const summaries = [];
  networks.forEach((definition, index) => {
    try {
      const { octets, prefix } = parseCidr(definition);
      const hosts = hostCapacity(prefix);
      const entries = routeEntries(hosts);
      if (entries > 4096) throw new Error(`${entries} route entries exceed the table limit`);
      const blockSize = Math.pow(2, 32 - prefix);
      const value = octets.reduce((acc, octet) => acc * 256 + octet, 0);
      summaries.push({
        base: toDotted(Math.floor(value / blockSize) * blockSize),
        prefix,
        hosts,
        entries,
        port: allocatePort(index),
        ttl: 64,
        priority: priorityMask(octets)
      });
    } catch (err) {
      console.warn(`rejected "${definition}": ${err.message}`);
    }
  });
  return summaries;
}

