  for (let n = 0; n < input.length; n++) {
    const x0 = input[n];
    const y0 = b0 * x0 - b0 * x2 - a1 * y1 - a2 * y2;
    out[n] = y0;
    x2 = x1; x1 = x0; y2 = y1; y1 = y0;
  }
