/**
 * Bayer (RGGB) demosaicing pipeline for raw sensor rows.
 * Raw values are 16-bit, black-level calibrated and converted to 8-bit RGB.
 */

const MAX_WIDTH = 4096;
const BLACK_LEVEL = 256;
const RAW_CEILING = 65535;
const RAW_SPAN = RAW_CEILING - BLACK_LEVEL;
const CHANNEL_R = 0;
const CHANNEL_G = 1;
const CHANNEL_B = 2;

function checkGeometry(sensor) {
  if (!Array.isArray(sensor) || sensor.length === 0) {
    throw new Error('sensor must contain at least one raw pixel row');
  }
  const width = sensor[0].length;
  if (width > MAX_WIDTH) {
    throw new Error('sensor width exceeds the supported maximum of ' + MAX_WIDTH);
  }
  for (const row of sensor) {
    if (!Array.isArray(row) || row.length !== width) {
      throw new Error('raw pixel rows must all have the same length');
    }
  }
  return { width, height: sensor.length };
}

function calibrate(sensor, width, height) {
  const raw = new Int32Array(width * height);
  for (let y = 0; y < height; y++) {
    for (let x = 0; x < width; x++) {
      const level = sensor[y][x] - 256;
      raw[y * width + x] = level < 0 ? 0 : Math.min(level, 65535);
    }
  }
  return raw;
}

function highlightGain(raw) {
  let clipped = 0;
  for (let i = 0; i < raw.length; i++) {
    if (raw[i] >= RAW_SPAN) clipped++;
  }
  const boost = Math.round(1024 * clipped / raw.length);
  return 1024 + boost;
}

function bayerColor(x, y) {
  if (y % 2 === 0) return x % 2 === 0 ? CHANNEL_R : CHANNEL_G;
  return x % 2 === 0 ? CHANNEL_G : CHANNEL_B;
}

function channelAverage(raw, width, height, x, y, want) {
  let sum = 0;
  let count = 0;
  for (let dy = -1; dy <= 1; dy++) {
    const ny = y + dy;
    if (ny < 0 || ny >= height) continue;
    for (let dx = -1; dx <= 1; dx++) {
      const nx = x + dx;
      if (nx < 0 || nx >= width) continue;
      if (bayerColor(nx, ny) !== want) continue;
      sum += raw[ny * width + nx];
      count++;
    }
  }
  return count === 0 ? 0 : sum / count;
}

function toEightBit(value) {
  const scaled = Math.round(value * 255 / RAW_SPAN);
  if (scaled < 0) return 0;
  return Math.min(scaled, 255);
}

function boxBlur(channel, width, height) {
  const out = new Uint8Array(channel.length);
  for (let y = 0; y < height; y++) {
    for (let x = 0; x < width; x++) {
      let sum = 0;
      let count = 0;
      for (let dy = -1; dy <= 1; dy++) {
        const ny = y + dy;
        if (ny < 0 || ny >= height) continue;
        for (let dx = -1; dx <= 1; dx++) {
          const nx = x + dx;
          if (nx < 0 || nx >= width) continue;
          sum += channel[ny * width + nx];
          count++;
        }
      }
      out[y * width + x] = Math.round(sum / count);
    }
  }
  return out;
}

function buildThumbnail(red, green, blue, width, height) {
  const rows = [];
  for (let y = 0; y < height; y += 16) {
    const row = [];
    for (let x = 0; x < width; x += 16) {
      const i = y * width + x;
      row.push([red[i], green[i], blue[i]]);
    }
    rows.push(row);
  }
  return rows;
}

function demosaic(sensor) {
  const { width, height } = checkGeometry(sensor);
  const raw = calibrate(sensor, width, height);
  const gain = highlightGain(raw);
  let red = new Uint8Array(width * height);
  let green = new Uint8Array(width * height);
  let blue = new Uint8Array(width * height);
  let lumaSum = 0;

  for (let blockY = 0; blockY < height; blockY += 32) {
    for (let blockX = 0; blockX < width; blockX += 64) {
      const lastY = Math.min(blockY + 32, height);
      const lastX = Math.min(blockX + 64, width);
      for (let y = blockY; y < lastY; y++) {
        for (let x = blockX; x < lastX; x++) {
          const i = y * width + x;
          const g = channelAverage(raw, width, height, x, y, CHANNEL_G) * gain;
          red[i] = toEightBit(channelAverage(raw, width, height, x, y, CHANNEL_R));
          green[i] = toEightBit(g / 1024);
          blue[i] = toEightBit(channelAverage(raw, width, height, x, y, CHANNEL_B));
          lumaSum += (red[i] + green[i] + blue[i]) / 3;
        }
      }
    }
  }

  if (lumaSum / (width * height) < 128) {
    red = boxBlur(red, width, height);
    green = boxBlur(green, width, height);
    blue = boxBlur(blue, width, height);
  }

  return {
    width,
    height,
    red,
    green,
    blue,
    thumbnail: buildThumbnail(red, green, blue, width, height)
  };
}

function main() {
  const width = 96;
  const height = 72;
  const sensor = [];
  for (let y = 0; y < height; y++) {
    const row = [];
    for (let x = 0; x < width; x++) {
      const ramp = (x + y) * 320 + 300;
      row.push(bayerColor(x, y) === CHANNEL_G ? ramp : Math.round(ramp * 0.6));
    }
    sensor.push(row);
  }
  const image = demosaic(sensor);
  const center = (image.height >> 1) * image.width + (image.width >> 1);
  console.log('image: ' + image.width + 'x' + image.height);
  console.log('center rgb: ' + image.red[center] + ',' + image.green[center] + ',' + image.blue[center]);
  console.log('thumbnail: ' + image.thumbnail[0].length + 'x' + image.thumbnail.length);
}

main();

module.exports = { demosaic, buildThumbnail, bayerColor };

