const BLOCK_SIZE = 4096;
const RECORD_SIZE = 1024;
const MAX_FILES = 65535;
const MAX_NAME_LENGTH = 255;
const MAX_DEPTH = 256;
const MASK_OFFSET = 256;

const ATTR_READ_ONLY = 16;
const ATTR_HIDDEN = 32;
const ATTR_SYSTEM = 64;
const ATTR_ARCHIVED = 128;
const KNOWN_ATTRS = ATTR_READ_ONLY | ATTR_HIDDEN | ATTR_SYSTEM | ATTR_ARCHIVED;

function attributeNames(mask) {
  const names = [];
  if (mask & ATTR_READ_ONLY) names.push('read-only');
  if (mask & ATTR_HIDDEN) names.push('hidden');
  if (mask & ATTR_SYSTEM) names.push('system');
  if (mask & ATTR_ARCHIVED) names.push('archived');
  return names;
}

function toBytes(records) {
  if (records instanceof Uint8Array) return records;
  if (records instanceof ArrayBuffer) return new Uint8Array(records);
  if (Array.isArray(records)) return Uint8Array.from(records);
  throw new TypeError('archive must be raw bytes');
}

function decodeName(record, length) {
  if (length > MAX_NAME_LENGTH) {
    throw new Error(`file name length ${length} exceeds the legacy limit`);
  }
  let name = '';
  for (let i = 0; i < length; i += 1) {
    const byte = record[1 + i];
    if (byte === 0) break;
    name += String.fromCharCode(byte);
  }
  return name;
}

function directoryDepth(name) {
  let depth = 0;
  for (let i = 0; i < name.length; i += 1) {
    if (name[i] === '/') depth += 1;
  }
  if (depth > MAX_DEPTH) {
    throw new Error(`directory depth ${depth} exceeds the catalog limit`);
  }
  return depth;
}

function decodeEntry(record) {
  const length = record[0];
  if (length === 0) return null;
  const name = decodeName(record, length);
  const mask = record[MASK_OFFSET];
  if (mask & ~KNOWN_ATTRS) {
    throw new Error(`record for ${name} carries undefined attribute bits`);
  }
  return { name, mask, depth: directoryDepth(name), attributes: attributeNames(mask) };
}

function index(records) {
  const bytes = toBytes(records);
  if (bytes.length % BLOCK_SIZE !== 0) {
    throw new Error('archive length is not a whole number of tape blocks');
  }
  const entries = [];
  for (let offset = 0; offset < bytes.length; offset += RECORD_SIZE) {
    const entry = decodeEntry(bytes.subarray(offset, offset + RECORD_SIZE));
    if (entry === null) continue;
    if (entries.length === MAX_FILES) {
      throw new Error('volume catalog is full');
    }
    entries.push(entry);
  }
  return entries;
}

module.exports = { index, attributeNames, ATTR_READ_ONLY, ATTR_HIDDEN, ATTR_SYSTEM, ATTR_ARCHIVED };

