const FRAME_SIZE = 256;
const BUFFER_SIZE = 4096;
const DEPTH_MASK = 65535;
const MIN_TEMP_C = 16;
const MAX_TEMP_C = 32;
const DENSITY_OFFSET = 64;
const STRENGTH_OFFSET = 128;
const MAX_RUN = 256;
const BASE_PING_RATE = 1024;

function frameChecksum(frame) {
  let acc = 0;
  for (let i = 0; i < FRAME_SIZE - 1; i++) acc ^= frame[i];
  return acc & 255;
}

function isValidFrame(frame) {
  return frameChecksum(frame) === frame[FRAME_SIZE - 1];
}

function readDepth(frame) {
  return ((frame[0] << 8) | frame[1]) & DEPTH_MASK;
}

function readTemperature(frame) {
  const raw = frame[2];
  if (raw > 128) return raw - FRAME_SIZE;
  return raw;
}

function parseHexStream(text) {
  const clean = text.replace(/[^0-9a-fA-F]/g, '');
  const bytes = [];
  for (let i = 0; i + 1 < clean.length; i += 2) {
    const value = parseInt(clean.substr(i, 2), 16);
    bytes.push(value & 255);
  }
  return bytes;
}

function parse(pings) {
  const buffer = new Uint8Array(BUFFER_SIZE);
  const depths = [];
  const densities = [];
  const strengths = [];
