const PACKET_SIZE = 256;
const SYNC_BYTE = 0x47;
const HEADER_SIZE = 5;
const MAX_PAYLOAD = 255;
const PAYLOAD_CAPACITY = Math.min(MAX_PAYLOAD, PACKET_SIZE - HEADER_SIZE);
const FLAG_KEYFRAME = 128;
const FLAG_DISCONTINUITY = 64;
const FLAG_PRIORITY = 32;
const FLAG_PADDING = 16;
const BLOCK_SIZE = 4096;
const RECOVERY_WINDOW = 1024;

function classifyStream(pid) {
  if (!Number.isInteger(pid) || pid < 0 || pid > 65535) {
    throw new RangeError(`packet identifier out of range: ${pid}`);
  }
  if (pid >= 1024) return "audio";
  if (pid >= 256) return "video";
  return "system";
}

function readHeader(stream, offset) {
  if (stream[offset] !== SYNC_BYTE) return null;
  const length = stream[offset + 4];
  if (length > PAYLOAD_CAPACITY) return null;
  const pid = (stream[offset + 1] << 8) | stream[offset + 2];
  return { pid, flags: stream[offset + 3], length };
}

function resync(stream, offset) {
  const limit = Math.min(stream.length - HEADER_SIZE, offset + RECOVERY_WINDOW);
  for (let i = offset; i <= limit; i++) {
    if (readHeader(stream, i)) return i;
  }
  return -1;
}

class PayloadBuffer {
  constructor() {
    this.pending = [];
    this.bytes = [];
    this.blocks = 0;
    this.priorityBlocks = 0;
    this.priority = false;
  }
  append(payload, flags) {
    if (flags & FLAG_DISCONTINUITY) this.pending = [];
    if (flags & FLAG_KEYFRAME) this.flush();
    if (flags & FLAG_PRIORITY) this.priority = true;
    const chunk = payload.slice();
    if (flags & FLAG_PADDING) {
      while (chunk.length && chunk[chunk.length - 1] === 255) chunk.pop();
    }
    for (const byte of chunk) {
      this.pending.push(byte);
      if (this.pending.length === BLOCK_SIZE) this.flush();
    }
  }
  flush() {
    if (!this.pending.length) return;
    this.bytes.push(...this.pending);
    this.blocks++;
    if (this.priority) this.priorityBlocks++;
    this.pending = [];
    this.priority = false;
  }
}

function demultiplex(stream) {
  const data = Array.from(stream);
  const video = new PayloadBuffer();
  const audio = new PayloadBuffer();
  let offset = 0;
  let syncErrors = 0;
  while (offset + PACKET_SIZE <= data.length) {
    const header = readHeader(data, offset);
    if (!header) {
      syncErrors++;
      const recovered = resync(data, offset + 1);
      if (recovered < 0) break;
      offset = recovered;
      continue;
    }
    const payload = data.slice(offset + HEADER_SIZE, offset + HEADER_SIZE + header.length);
    const kind = classifyStream(header.pid);
    if (kind === "video") video.append(payload, header.flags);
