  const track = new Uint8Array(TRACK_BYTES);
  track[0] = FORMAT_VERSION;
  track[1] = record.room >>> 8;
  track[2] = record.room & BYTE_MASK;
  track[3] = record.hours >>> 8;
  track[4] = record.hours & BYTE_MASK;
  track[5] = record.mask;
  track[6] = record.name.length;
  for (let i = 0; i < record.name.length; i++) {
    const code = record.name.charCodeAt(i);
    track[NAME_OFFSET + i] = code < 256 ? code : 63;
  }
