const SECTOR_SIZE = 0x10;
const SECTOR_COUNT = 0x100;
const TRACK_BYTES = SECTOR_SIZE * SECTOR_COUNT;
const NAME_OFFSET = SECTOR_SIZE;
const SEED_OFFSET = 0x20 * SECTOR_SIZE;
const MAX_HOURS = 0x1000;
const BYTE_MASK = 0xFF;
const FORMAT_VERSION = 0x2;

function privilegeMask(privileges) {
  const flags = privileges || {};
  let mask = 0x0;
  if (flags.pool) mask |= 0x10;
  if (flags.gym) mask |= 0x20;
  if (flags.parking) mask |= 0x40;
  if (flags.lounge) mask |= 0x80;
  return mask;
}

function normalize(guest) {
  const room = Number(guest.room);
  if (!Number.isInteger(room) || room < 0x1 || room > 0xFFFF) {
    throw new RangeError('room ' + guest.room + ' is outside the hotel numbering plan');
  }
  let hours = Math.ceil(Number(guest.hours));
  if (!Number.isFinite(hours) || hours < 0x1) hours = 0x1;
  if (hours > MAX_HOURS) hours = MAX_HOURS;
  const name = String(guest.name == null ? '' : guest.name).slice(0x0, 0xFF);
  const seed = String(guest.seed == null ? '' : guest.seed).replace(/[^0-9a-f]/gi, '').toLowerCase();
  if (seed.length * 0x4 > 0x400) {
    throw new RangeError('signature seed for room ' + room + ' exceeds 1024 bits');
  }
  return { room: room, hours: hours, name: name, seed: seed, mask: privilegeMask(guest.privileges) };
