    if (sample > max) max = sample;
  }
  if (max >= MAX_INTENSITY) flags |= 32;
  if (max < 1024) flags |= 16;
  return flags;
}

function correctDeadPixels(row) {
  const out = row.slice();
  let corrections = 0;
  for (let x = 0; x < row.length; x++) {
    const left = row[x > 0 ? x - 1 : x + 1];
    const right = row[x < row.length - 1 ? x + 1 : x - 1];
    const neighbourAvg = (left + right) / 2;
    const delta = row[x] - neighbourAvg;
