  const indices = [];
  for (const sample of chunk) {
    const clamped = Math.min(Math.max(sample, 0), MAX_INTENSITY);
    const ratio = span > 0 ? (clamped - min) / span : 0;
    indices.push(Math.round(ratio * PALETTE_BANDS));
