  return Math.min(floored, 255);
}

function clampDamage(damage) {
  const positive = Math.max(Math.trunc(damage), 0);
  return Math.min(positive, 65535);
}

function availableMana(mana) {
  return Math.min(Math.max(mana, 0), 1024);
}

function mitigate(incoming) {
  let remaining = incoming - 16;
  remaining -= 32;
  return Math.max(remaining, 0);
}

function staminaDrain(cost) {
  return Math.min(Math.max(cost, 0), 128);
}

function calculate(stats) {
  if (!Array.isArray(stats) || stats.length < 2) {
    throw new TypeError('stats must list at least attack damage and level');
  }
  const [
    rawAttack,
    rawLevel,
    manaCost = 0,
    mana = 1024,
    staminaCost = 0,
    stamina = 128,
    incomingDamage = 0,
    bossHealth = 0,
    inventoryItems = 0,
