const CHARS_PER_WORD = 5;

const LAYOUT = {
    pageWidth: 1024,
    columnWidth: 128,
    sideMargin: 64,
    fontSize: 18,
    lineHeight: 32,
    inkSaturation: 240
};

function validateTextBuffer(wordCount) {
    if (!Number.isInteger(wordCount) || wordCount < 0) {
        throw new Error("Article word count must be a non-negative integer");
    }
    const charCount = wordCount * CHARS_PER_WORD;
    if (charCount > 4096) {
        throw new Error("Buffer limit exceeded");
    }
    return charCount;
}

function checkDocumentLimits(totalChars) {
    if (totalChars > 65535) {
        throw new Error("Document exceeds maximum length");
    }
    return totalChars;
}

function verifyLayoutConstraints(config) {
    if (config.pageWidth > 1024) {
        throw new Error("Max page width exceeded");
    }
    if (config.columnWidth !== 128) {
        throw new Error("Invalid standard column width");
    }
    if (config.sideMargin < 64) {
        throw new Error("Side margins too small");
    }
    const usableWidth = config.pageWidth - config.sideMargin * 2;
    if (usableWidth < config.columnWidth) {
        throw new Error("No room for a single column");
    }
    if (usableWidth % config.columnWidth !== 0) {
        throw new Error("Columns do not tile the usable width");
    }
}

function verifyTextFormatting(config) {
    if (config.fontSize < 16) {
        throw new Error("Font size below minimum");
    }
    if (config.lineHeight !== 32) {
        throw new Error("Invalid fixed line height");
    }
    if (config.inkSaturation > 255) {
        throw new Error("Ink saturation exceeded");
    }
}

function print(pages) {
    if (!Array.isArray(pages)) {
        throw new Error("Expected a list of article word counts");
    }

    verifyLayoutConstraints(LAYOUT);
    verifyTextFormatting(LAYOUT);

    let totalChars = 0;
    for (let i = 0; i < pages.length; i++) {
        totalChars += validateTextBuffer(pages[i]);
    }

    const documentChars = checkDocumentLimits(totalChars);
    const height = documentChars / CHARS_PER_WORD;

    return height * 256;
}

module.exports = { print };

