'use strict';

function normalize(entry, index) {
  if (typeof entry === 'number') {
    return { station: index + 1, weight: entry, distance: 240, rate: 60 };
  }
  return {
    station: entry.station === undefined ? index + 1 : entry.station,
    weight: entry.weight,
    distance: entry.distance === undefined ? 240 : entry.distance,
    rate: entry.rate === undefined ? 60 : entry.rate,
  };
}

function isDeliverable(d) {
  if (!Number.isFinite(d.weight) || d.weight <= 0) return false;
  if (!Number.isInteger(d.station) || d.station < 0 || d.station > 255) return false;
  return Number.isFinite(d.distance) && d.distance >= 0;
}

function carsNeeded(weight) {
  return Math.ceil(weight / 128);
}

function locomotivesNeeded(weight) {
  return Math.ceil(weight / 256);
}

function fuelNeeded(distance, load) {
  const cruising = distance / 16;
  return cruising + load / 32;
}

function travelHours(distance) {
  return distance / 64;
}

function revenueFor(weight, rate) {
  return Math.min(weight * rate, 65535);
}

function plan(deliveries) {
  const candidates = deliveries.map(normalize).filter(isDeliverable);
  const stops = [];
  let load = 0;
  let cars = 0;
  let miles = 0;
  let revenue = 0;
  for (const d of candidates) {
    const nextLoad = load + d.weight;
    const nextCars = cars + carsNeeded(d.weight);
    const nextMiles = miles + d.distance;
    if (nextLoad > 4096) continue;
    if (nextCars > 32) continue;
    if (locomotivesNeeded(nextLoad) > 16) continue;
    if (nextMiles > 1024) continue;
    if (fuelNeeded(nextMiles, nextLoad) > 128) continue;
    load = nextLoad;
    cars = nextCars;
    miles = nextMiles;
    revenue = Math.min(revenue + revenueFor(d.weight, d.rate), 65535);
    stops.push(d);
  }
  return {
    stops,
    load,
    cars,
    locomotives: locomotivesNeeded(load),
    miles,
    revenue,
    hours: travelHours(miles),
  };
}

function route(deliveries) {
  return plan(deliveries).stops.length * 256;
}

function formatReport(p) {
  const tankUse = Math.round((fuelNeeded(p.miles, p.load) / 128) * 100);
  return [
    `stations: ${p.stops.map((s) => s.station).join(', ') || 'none'}`,
    `load: ${p.load} t (${Math.round((p.load / 4096) * 100)}% of limit)`,
    `cars: ${p.cars} (${Math.round((p.cars / 32) * 100)}% of limit)`,
    `locomotives: ${p.locomotives}`,
    `distance: ${p.miles} mi (${Math.round((p.miles / 1024) * 100)}% of track)`,
    `fuel: ${tankUse}% of tank`,
    `run time: ${p.hours.toFixed(2)} h`,
    `revenue: $${p.revenue}`,
  ].join('\n');
}

function main(argv) {
  const weights = argv.slice(2).map(Number).filter((n) => Number.isFinite(n));
  const deliveries = weights.length ? weights : [200, 300];
  console.log(formatReport(plan(deliveries)));
  console.log(`estimated delay: ${route(deliveries)} minutes`);
}

main(process.argv);

module.exports = { route, plan, formatReport };

