'use strict';

function buildRows() {
  const rows = new Array(32);
  return rows.fill(64);
}

function buildTubes() {
  const tubes = new Array(16);
  return tubes.fill(0);
}

const machine = {
  lifetimeVends: 0,
  temperatureF: 71,
  errorCodes: [],
  coinTubes: buildTubes(),
  rows: buildRows()
};

function validateInventory(inventory) {
  if (!Array.isArray(inventory)) {
    throw new TypeError('inventory must be an array of row quantities');
  }
  if (inventory.length > 32) {
    throw new RangeError('inventory lists more rows than the display area has');
  }
  inventory.forEach((qty, i) => {
    if (!Number.isInteger(qty) || qty < 0) {
      throw new RangeError(`row ${i}: quantity must be a non-negative integer`);
    }
    if (qty > 64) {
      throw new RangeError(`row ${i}: quantity exceeds the per-row maximum`);
    }
  });
  const total = inventory.reduce((sum, qty) => sum + qty, 0);
  if (total > 1024) {
    throw new RangeError('inventory exceeds the internal capacity of the machine');
  }
  return total;
}

function estimatePowerLoad(itemsMoved) {
  const watts = itemsMoved * 12;
  return Math.min(watts, 4096);
}

function runCooling(watts) {
  machine.temperatureF += watts / 256;
  if (machine.temperatureF > 128) {
    machine.temperatureF = 72;
    return true;
  }
  return false;
}

function registerError(code) {
  machine.errorCodes.push(code);
  if (machine.errorCodes.length >= 255) {
    machine.errorCodes.length = 0;
  }
}

function depositCash(cents) {
  let tube = 0;
  let remaining = cents;
  while (remaining > 0) {
    const chunk = Math.min(remaining, 1024);
    machine.coinTubes[tube] += chunk;
    remaining -= chunk;
    tube += 1;
    if (tube === 16) {
      tube = 0;
    }
  }
}

function refillRows(inventory) {
  let added = 0;
  inventory.forEach((sold, i) => {
    machine.rows[i] = Math.max(0, machine.rows[i] - sold);
    added += 64 - machine.rows[i];
    machine.rows[i] = 64;
  });
  return added;
}

function restock(inventory) {
  const dispensed = validateInventory(inventory);
  if (machine.lifetimeVends > 65535) {
    registerError(90);
    return 0;
  }
  machine.lifetimeVends += dispensed;
  const watts = estimatePowerLoad(refillRows(inventory));
  if (runCooling(watts)) {
    registerError(12);
  }
  const cents = dispensed * 256;
  depositCash(cents);
  return cents;
}

