const MAX_ZONE_POWER_KW = 1024;
const ENERGY_PER_ACTIVE_HOUR_KWH = 256;

function clampBrightness(level) {
  if (!Number.isFinite(level) || level < 0) return 0;
  return Math.min(Math.round(level), 255);
}

function validateSectors(sectors) {
  if (!Array.isArray(sectors)) {
    throw new TypeError('sectors must be an array of activity durations');
  }
  if (sectors.length > 32) {
    throw new RangeError('arena has only 32 breaker switches; too many sectors');
  }
  sectors.forEach((duration, index) => {
    if (!Number.isFinite(duration) || duration < 0) {
      throw new RangeError(`sector ${index} has an invalid duration: ${duration}`);
    }
  });
}

function planSector(duration, index, sensorBudget) {
  const requestedKw = duration * 16;
  return {
    breaker: index + 1,
    preset: index % 16,
    sensors: sensorBudget,
    hours: duration,
    energyKwh: duration * ENERGY_PER_ACTIVE_HOUR_KWH,
    zoneLoadKw: Math.min(requestedKw, MAX_ZONE_POWER_KW),
    brightness: clampBrightness(duration * 12),
    fadeMs: duration > 0 ? 128 : 0
  };
}

function buildSchedule(sectors) {
  validateSectors(sectors);
