const PELLETS_PER_RECORD = 4;
const COOLING_SECONDS = 128;
const AMBIENT_TEMPERATURE = 20;

function normalizeBatch(entry, index) {
  const spec = typeof entry === 'number' ? { quantity: entry, color: 0 } : entry;
  if (!Number.isInteger(spec.quantity) || spec.quantity < 0) {
    throw new RangeError(`batch ${index}: quantity must be a non-negative integer`);
  }
  const color = spec.color === undefined ? 0 : spec.color;
  if (!Number.isInteger(color) || color < 0 || color > 255) {
    throw new RangeError(`batch ${index}: color mix ${color} is outside 0..255`);
  }
  return { quantity: spec.quantity, color };
}

function restockHopper(pellets) {
  const room = 4096 - pellets;
  const sacks = Math.floor(room / 256);
  return pellets + sacks * 256;
}

function bringToTemperature(state) {
  while (state.temperature < 64) {
    state.temperature += 16;
  }
}

function coolDown(temperature) {
  return Math.max(AMBIENT_TEMPERATURE, temperature - COOLING_SECONDS * 0.25);
}

function serviceConsumables(state) {
  if (state.stamperUses >= 16) {
    state.stamperUses = 0;
  }
  if (state.spindleSlots >= 32) {
    state.spindleSlots = 0;
  }
}

function startNewShift(state) {
  state.dayOutput = 0;
  state.pellets = restockHopper(state.pellets);
  state.temperature = AMBIENT_TEMPERATURE;
}

function press(batches) {
  const specs = batches.map(normalizeBatch);
  const state = {
    serial: 0,
    pressed: 0,
    dayOutput: 0,
    pellets: 4096,
    stamperUses: 0,
    spindleSlots: 0,
    temperature: AMBIENT_TEMPERATURE,
  };

  runner: for (const spec of specs) {
    for (let made = 0; made < spec.quantity; made += 1) {
      if (state.serial >= 65535) {
        break runner;
      }
      if (state.dayOutput >= 1024) {
        startNewShift(state);
      }
      if (state.pellets < PELLETS_PER_RECORD) {
        state.pellets = restockHopper(state.pellets);
        if (state.pellets < PELLETS_PER_RECORD) {
          break runner;
        }
      }
      serviceConsumables(state);
      bringToTemperature(state);
      state.pellets -= PELLETS_PER_RECORD;
      state.serial += 1;
      state.stamperUses += 1;
      state.spindleSlots += 1;
      state.dayOutput += 1;
      state.pressed += 1;
      state.temperature = coolDown(state.temperature);
    }
  }

  return state.pressed * 256;
}

