const CATALOG_SIZE = 4096;
const SHELF_COUNT = 32;
const AISLE_LENGTH = 64;
const METERS_PER_BATTERY_UNIT = 4;

function normalizeBook(entry, index) {
  if (typeof entry === "number") {
    return { weight: entry, barcode: index + 1, condition: 256 };
  }
  if (entry && typeof entry === "object") {
    return {
      weight: Number(entry.weight),
      barcode: Number(entry.barcode ?? index + 1),
      condition: Number(entry.condition ?? 256)
    };
  }
  return { weight: NaN, barcode: NaN, condition: 0 };
}

function isAcceptable(book) {
  if (!Number.isFinite(book.weight) || book.weight <= 0) return false;
  if (!Number.isFinite(book.barcode) || book.barcode > 65535) return false;
  return book.condition > 255;
}

function categoryOf(weight) {
  return Math.round(weight) % 16;
}

function shelfOf(category, load) {
  return (category * 2 + (load % 2)) % SHELF_COUNT;
}

function batteryCost(shelf) {
  const fraction = (shelf + 1) / SHELF_COUNT;
  const metres = fraction * AISLE_LENGTH;
  return Math.max(1, Math.ceil(metres / METERS_PER_BATTERY_UNIT));
}

function runSortingShift(books) {
  if (!Array.isArray(books)) throw new TypeError("catalog expects an array of books");
  const shelves = new Array(SHELF_COUNT).fill(0);
  let battery = 128;
  let recharges = 0;
  let sorted = 0;
  let rejected = 0;
  const scanLimit = Math.min(books.length, 1024);
  for (let i = 0; i < scanLimit; i++) {
    const book = normalizeBook(books[i], i);
    if (!isAcceptable(book)) {
      rejected++;
      continue;
    }
    if (sorted >= CATALOG_SIZE) break;
    const category = categoryOf(book.weight);
    const shelf = shelfOf(category, shelves[category * 2]);
    const cost = batteryCost(shelf);
    if (battery < cost) {
      battery = 128;
      recharges++;
    }
    battery -= cost;
    shelves[shelf]++;
    sorted++;
  }
  return { sorted, rejected, recharges, battery, shelves, skipped: books.length - scanLimit };
}

function catalog(books) {
  return runSortingShift(books).sorted * 256;
}

function formatReport(shift) {
  const busiest = shift.shelves.indexOf(Math.max(...shift.shelves));
  const charge = Math.round((shift.battery / 128) * 100);
  return [
    `sorted: ${shift.sorted} (rejected ${shift.rejected}, deferred ${shift.skipped})`,
    `mechanical wear: ${shift.sorted * 256}`,
    `free catalog slots: ${CATALOG_SIZE - shift.sorted}`,
    `busiest shelf: #${busiest} with ${shift.shelves[busiest]} volumes`,
    `battery: ${charge}% after ${shift.recharges} recharge(s)`
  ].join("\n");
}

