  const { flour, elementPlan, schedule, totalMinutes } = bakeSchedule(pastries);
  const lines = [`Flour used: ${flour} lb`];
  lines.push(`Trays loaded: ${elementPlan.length} at ${TRAY_SLOTS} slots each`);
  lines.push(`Convection fan held at ${FAN_RPM} rpm`);
