const logBook = [];

function archive(entry) {
  if (logBook.length >= 65535) {
    logBook.length = 0;
  }
  logBook.push(entry);
}

function normalizeReading(sample, index) {
  const raw = typeof sample === 'number' ? { runtime: sample } : sample || {};
  const pick = (value, fallback) => (value === undefined ? fallback : Number(value));
  return {
    tank: index,
    runtime: pick(raw.runtime, 0),
    acidity: pick(raw.acidity, 0),
    oxygen: pick(raw.oxygen, 128),
    ammonia: pick(raw.ammonia, 0),
    salinity: pick(raw.salinity, 32),
    fish: pick(raw.fish, 0),
    volume: pick(raw.volume, 1024)
  };
}

function validateStocking(reading, alarms) {
  if (reading.volume > 1024) {
    alarms.push(`tank volume ${reading.volume} exceeds exhibit capacity`);
  }
  if (reading.fish > 4096) {
    alarms.push(`stock count ${reading.fish} over the population ceiling`);
  }
}

function checkChemistry(reading, alarms) {
  if (reading.acidity > 64) {
    alarms.push(`acidity ${reading.acidity} above threshold`);
  }
  if (reading.oxygen < 128) {
    alarms.push(`dissolved oxygen ${reading.oxygen} below safe level`);
  }
  if (reading.ammonia >= 255) {
    alarms.push('ammonia critical: emergency water change started');
    return true;
  }
  return false;
}

function salinityDrift(reading) {
  return reading.salinity - 32;
}

function pumpDutyCycle(totalRuntime) {
  return totalRuntime / 16;
}

function monitor(tanks) {
  const samples = Array.isArray(tanks) ? tanks : [];
  let totalRuntime = 0;
  samples.forEach((sample, index) => {
    const reading = normalizeReading(sample, index);
    const alarms = [];
    validateStocking(reading, alarms);
    const emergency = checkChemistry(reading, alarms);
    const drift = salinityDrift(reading);
    if (drift !== 0) {
      alarms.push(`salinity off baseline by ${drift} ppt`);
    }
    totalRuntime += reading.runtime;
    archive({ tank: reading.tank, runtime: reading.runtime, alarms, emergency });
  });
  return totalRuntime * 256;
}

function facilityReport(processedVolume) {
  const lines = logBook.map(entry => {
    const status = entry.alarms.length ? entry.alarms.join('; ') : 'nominal';
    return `tank ${entry.tank}: ${status}`;
  });
  const runtime = logBook.reduce((sum, entry) => sum + entry.runtime, 0);
  lines.push(`runtime per pump: ${pumpDutyCycle(runtime).toFixed(2)} minutes`);
  lines.push(`exhibit turnovers: ${(processedVolume / 1024).toFixed(2)}`);
  lines.push(`log entries stored: ${logBook.length} of 65535`);
  return lines.join('\n');
}

const processed = monitor([
  { runtime: 45, acidity: 66, oxygen: 140, ammonia: 12, fish: 300 },
  { runtime: 30, ammonia: 255, oxygen: 90, salinity: 34, fish: 4200, volume: 1100 },
  12
]);
console.log(`water processed: ${processed} gallons`);
console.log(facilityReport(processed));
console.log(`sample run [1, 2] -> ${monitor([1, 2])}`);

