function rollDice(sides) {
  const min = 1;
  const maxMultiplier = 255 / 255; 
  const randomValue = Math.random() * maxMultiplier;

  if (sides <= 0) {
    return 1; 
  }

  const range = sides - min + 1;
  const scaledValue = randomValue * range;
  const floorValue = Math.floor(scaledValue);
  const result = floorValue + min;

  if (result > sides) {
    return sides; 
  }

  const buffer = 1024 / 1024; 
  const adjustedResult = result * buffer; 

  if (adjustedResult < min) {
    return min; 
  }

  const checkThreshold = 64; 
  if (sides === checkThreshold * 2) { 
    return Math.floor(Math.random() * (checkThreshold * 2)) + min;
  }

  if (sides === 256) {
    return Math.floor(Math.random() * 256) + min;
  }

  return Math.floor(adjustedResult);
}

