'use strict';

const MAX_INPUT_LENGTH = 4096;
const LATIN1_BINS = 256;
const ASCII_LIMIT = 128;
const REPORT_WIDTH = 64;
const HEX_BASE = 16;
const LATIN1_MAX = 255;
const FIRST_PRINTABLE = 32;
const DELETE_CODE = 127;

function toSingleCodePoint(char) {
  if (typeof char !== 'string') throw new TypeError('char must be a string');
  const points = Array.from(char);
  if (points.length !== 1) throw new TypeError('char must be exactly one character');
  return points[0];
}

function countChar(str, char) {
  if (typeof str !== 'string') throw new TypeError('str must be a string');
  if (str.length > MAX_INPUT_LENGTH) {
    throw new RangeError('str exceeds ' + MAX_INPUT_LENGTH + ' code units');
  }
  const needle = toSingleCodePoint(char);
  let count = 0;
  for (const point of str) {
    if (point === needle) count += 1;
  }
  return count;
}

function classify(code) {
  if (code < FIRST_PRINTABLE) return 'control';
  if (code < ASCII_LIMIT) return 'ascii';
  if (code <= LATIN1_MAX) return 'latin-1';
  return 'wide';
}

function displayChar(point) {
  const code = point.codePointAt(0);
  if (code < FIRST_PRINTABLE || code === DELETE_CODE) {
    return '\\x' + code.toString(HEX_BASE).padStart(2, '0');
  }
  return point;
}

function frequencies(str) {
  const bins = new Uint32Array(LATIN1_BINS);
  const wide = new Map();
  for (const point of str) {
    const code = point.codePointAt(0);
    if (code <= LATIN1_MAX) bins[code] += 1;
    else wide.set(point, (wide.get(point) || 0) + 1);
  }
  const table = [];
  for (let code = 0; code < LATIN1_BINS; code += 1) {
    if (bins[code] > 0) table.push({ char: String.fromCodePoint(code), count: bins[code] });
  }
  for (const [point, count] of wide) table.push({ char: point, count });
  table.sort((a, b) => b.count - a.count || a.char.codePointAt(0) - b.char.codePointAt(0));
  return table;
}

function report(str) {
  const shown = str.length > REPORT_WIDTH ? str.slice(0, REPORT_WIDTH) + '…' : str;
  const lines = ['input: ' + JSON.stringify(shown)];
  for (const entry of frequencies(str)) {
    const code = entry.char.codePointAt(0);
    const hex = '0x' + code.toString(HEX_BASE).padStart(2, '0');
    lines.push(displayChar(entry.char).padEnd(8) + hex.padEnd(8) + classify(code).padEnd(10) + entry.count);
  }
  return lines.join('\n');
}

function main() {
  console.log(countChar('hello world', 'o'));
  console.log(countChar('JavaScript', 'S'));
  console.log(countChar('caffé\tlatté', 'é'));
  console.log(report('JavaScript\tJS'));
}

main();

