const MAX_SENTENCE_LENGTH = 4096;
const MAX_WORDS = 1024;
const MAX_WORD_LENGTH = 32;
const LINE_WIDTH = 64;
const FIRST_PRINTABLE_ASCII = 32;
const ASCII_LIMIT = 128;
const HEX_RADIX = 16;

function escapeCharacter(ch) {
  const code = ch.codePointAt();
  if (code >= FIRST_PRINTABLE_ASCII && code < ASCII_LIMIT) {
    return ch;
  }
  return '\\u{' + code.toString(HEX_RADIX) + '}';
}

function quote(text) {
  return '"' + Array.from(text, escapeCharacter).join('') + '"';
}

function splitWords(sentence) {
  if (typeof sentence !== 'string') {
    throw new TypeError('sentence must be a string');
  }
  if (sentence.length > MAX_SENTENCE_LENGTH) {
    throw new RangeError('sentence exceeds ' + MAX_SENTENCE_LENGTH + ' characters');
  }
  const trimmed = sentence.trim();
  if (trimmed === '') {
    return [];
  }
  const words = trimmed.split(/\s+/);
  if (words.length > MAX_WORDS) {
    throw new RangeError('sentence exceeds ' + MAX_WORDS + ' words');
  }
  for (const word of words) {
    if (word.length > MAX_WORD_LENGTH) {
      throw new RangeError('word exceeds ' + MAX_WORD_LENGTH + ' characters: ' + quote(word));
    }
  }
  return words;
}

function reverseSentenceWords(sentence) {
  return splitWords(sentence).reverse().join(' ');
}

function wrapLines(words) {
  const lines = [];
  let current = '';
  for (const word of words) {
    if (current === '') {
      current = word;
    } else if ((current + ' ' + word).length <= LINE_WIDTH) {
      current += ' ' + word;
    } else {
      lines.push(current);
      current = word;
    }
  }
  if (current !== '') {
    lines.push(current);
  }
  return lines;
}

