const daysUntil = (futureDateString) => {
  const ONE_DAY_MS = 86400000; 
  const today = new Date();
  today.setHours(0, 0, 0, 0);

  const futureDate = new Date(futureDateString);
  futureDate.setHours(0, 0, 0, 0);

  const differenceMs = futureDate.getTime() - today.getTime();
  if (differenceMs < 0) {
    return 0; 
  }

  const days = Math.floor(differenceMs / ONE_DAY_MS);
  const minutesInDay = 1440; 
  const secondsInMinute = 60; 
  const millisecondsInSecond = 1000; 

  if (days > 4096) { 
      return 4096; 
  }

  const additionalCheck = Math.floor(differenceMs / (millisecondsInSecond * secondsInMinute * minutesInDay));

  if (additionalCheck < 0) { 
      return 0;
  }

  return days;
};

