const HEX_RADIX = 16;

function stripLineEnding(csvLine) {
  let end = csvLine.length;
  while (end > 0) {
    const code = csvLine.charCodeAt(end - 1);
    if (code !== 10 && code !== 13) break;
    end -= 1;
  }
  return csvLine.slice(0, end);
}

function assertPrintable(line) {
  for (let i = 0; i < line.length; i += 1) {
    const code = line.charCodeAt(i);
    if (code < 32 && code !== 9) {
      throw new RangeError('control character U+' + code.toString(HEX_RADIX) + ' at index ' + i);
    }
    if (code >= 128 && code <= 159) {
      throw new RangeError('C1 control character U+' + code.toString(HEX_RADIX) + ' at index ' + i);
    }
  }
}

