  let bytes = 0;
  for (const ch of text) {
    const cp = ch.codePointAt(0);
    if (cp < 128) bytes += 1;
    else if (cp < 2048) bytes += 2;
    else if (cp <= 65535) bytes += 3;
    else bytes += 4;
  }
  return bytes;
}

