      const field = line.slice(start, i);
      if (field.length > MAX_FIELD_LENGTH) {
        throw new RangeError('field ' + fields.length + ' exceeds ' + MAX_FIELD_LENGTH + ' characters');
      }
      fields.push(field);
      if (fields.length > MAX_FIELDS) {
        throw new RangeError('more than ' + MAX_FIELDS + ' fields in one line');
      }
      start = i + 1;
    }
  }
  return fields;
}

