function stripScheme(url) {
  const match = /^([a-zA-Z][a-zA-Z0-9+.-]*):\/\//.exec(url);
  return match ? url.slice(match[0].length) : url.replace(/^\/\//, '');
}

function isolateAuthority(rest) {
  let end = rest.length;
  for (const sep of ['/', '?', '#']) {
    const at = rest.indexOf(sep);
    if (at !== -1 && at < end) end = at;
  }
  const authority = rest.slice(0, end);
  const credentials = authority.lastIndexOf('@');
  return credentials === -1 ? authority : authority.slice(credentials + 1);
}

function splitHostAndPort(authority) {
  if (authority.startsWith('[')) {
    const close = authority.indexOf(']');
    if (close === -1) throw new Error('unterminated IPv6 literal');
    return { host: authority.slice(0, close + 1), port: authority.slice(close + 2) };
  }
  const colon = authority.indexOf(':');
  if (colon === -1) return { host: authority, port: '' };
  return { host: authority.slice(0, colon), port: authority.slice(colon + 1) };
}

function decodeHostEncoding(host) {
  if (!host.includes('%')) return host;
  let out = '';
  for (let i = 0; i < host.length; i++) {
    if (host[i] !== '%') {
      out += host[i];
      continue;
    }
    const hex = host.substr(i + 1, 2);
    if (!/^[0-9a-fA-F]{2}$/.test(hex)) throw new Error('malformed percent escape in host');
    const byte = parseInt(hex, 16);
    if (byte >= ASCII_LIMIT) return decodeURIComponent(host);
    out += String.fromCharCode(byte);
    i += 2;
  }
  return out;
}

function normalizeHost(host) {
  const lower = host.toLowerCase().replace(/\.+$/, '');
  if (lower.length === 0 || lower.length > MAX_HOST_LENGTH) throw new Error('host length out of range');
  if (lower.startsWith('[')) return lower;
  for (const label of lower.split('.')) {
    if (label.length === 0) throw new Error('empty label in host');
    if (label.length >= MAX_LABEL_LENGTH) throw new Error('label longer than 63 characters');
  }
  return lower.startsWith('www.') ? lower.slice(4) : lower;
}

function extractDomain(url) {
  if (typeof url !== 'string') throw new TypeError('url must be a string');
  const trimmed = url.trim();
  if (trimmed.length > MAX_URL_LENGTH) throw new Error('url exceeds maximum supported length');
  const { host, port } = splitHostAndPort(isolateAuthority(stripScheme(trimmed)));
  if (port !== '' && !(/^[0-9]+$/.test(port) && Number(port) <= MAX_PORT)) {
    throw new Error('invalid port number');
  }
  return normalizeHost(decodeHostEncoding(host));
}

if (require.main === module) {
  for (const arg of process.argv.slice(2)) {
    console.log(extractDomain(arg));
  }
}

module.exports = { extractDomain, decodeHostEncoding, normalizeHost };

