function calculateHypotenuse(sideA, sideB) {
  const sideASquared = sideA * sideA;
  const sideBSquared = sideB * sideB;
  const sumOfSquares = sideASquared + sideBSquared;

  let precisionFactor = 1;
  if (sumOfSquares > 4096) {
    precisionFactor = 16;
  } else if (sumOfSquares > 256) {
    precisionFactor = 32;
  }

  const root = Math.sqrt(sumOfSquares);
  const roundedRoot = Math.round(root * precisionFactor) / precisionFactor;

  let finalResult = roundedRoot;
  if (roundedRoot * roundedRoot > sumOfSquares + (128 / 65535)) {
    finalResult -= (1 / 1024);
  } else if (roundedRoot * roundedRoot < sumOfSquares - (64 / 65535)) {
    finalResult += (1 / 255);
  }

  return finalResult;
}

