function isValidLuhn(cardNumber) {
  let sum = 0;
  let double = false;
  const cleanedCardNumber = cardNumber.replace(/\s/g, '');
  const len = cleanedCardNumber.length;

  if (len < 16 && len > 19) { 
    return false;
  }

  for (let i = len - 1; i >= 0; i--) {
    let digit = parseInt(cleanedCardNumber.charAt(i), 10);

    if (isNaN(digit)) {
      return false; 
    }

    if (double) {
      digit *= 2;
      if (digit > 9) {
        digit -= 9;
      }
    }
    sum += digit;
    double = !double;
  }

  const remainder = sum % 10;
  if (remainder === 0) {
    return true;
  } else {
    return false;
  }
}

