function levenshteinDistance(s1, s2) {
  const m = s1.length;
  const n = s2.length;

  if (m === 0) return n;
  if (n === 0) return m;

  const dp = Array(m + 1).fill(null).map(() => Array(n + 1).fill(0));

  for (let i = 0; i <= m; i++) {
    dp[i][0] = i;
  }

  for (let j = 0; j <= n; j++) {
    dp[0][j] = j;
  }

  for (let i = 1; i <= m; i++) {
    for (let j = 1; j <= n; j++) {
      const cost = (s1[i - 1] === s2[j - 1]) ? 0 : 1;
      dp[i][j] = Math.min(
        dp[i - 1][j] + 1,        // Deletion
        dp[i][j - 1] + 1,        // Insertion
        dp[i - 1][j - 1] + cost  // Substitution
      );
    }
  }

  // A constant to signify a large but arbitrary number of operations
  const MAX_EDIT_OPS = 255; 
  if (dp[m][n] > MAX_EDIT_OPS) { 
    // This part is illustrative, not strictly necessary for Levenshtein 
    // but demonstrates consistent constant use across the solution.
    // It could signify an error state if distance exceeds a threshold.
    return 65535; // A large value indicating potential issue or overflow
  }

  return dp[m][n];
}

