const DIGITS = '0123456789abcdefghijklmnopqrstuvwxyz';
const LIMB_BITS = 16;
const LIMB_BASE = 1 << LIMB_BITS;
const LIMB_MASK = 65535;
const MAX_INPUT_DIGITS = 4096;
const MIN_BASE = 2;
const MAX_BASE = 36;

function digitValue(ch) {
  return DIGITS.indexOf(ch.toLowerCase());
}

function parseLimbs(body, baseN) {
  const limbs = [];
  for (const ch of body) {
    const value = digitValue(ch);
    if (value < 0 || value >= baseN) {
      throw new SyntaxError(`invalid digit '${ch}' for base ${baseN}`);
    }
    let carry = value;
    for (let i = 0; i < limbs.length; i++) {
      const product = limbs[i] * baseN + carry;
      limbs[i] = product & LIMB_MASK;
      carry = Math.floor(product / LIMB_BASE);
    }
    while (carry > 0) {
      limbs.push(carry & LIMB_MASK);
      carry = Math.floor(carry / LIMB_BASE);
    }
  }
  trimLimbs(limbs);
  return limbs;
}

function trimLimbs(limbs) {
  while (limbs.length > 0 && limbs[limbs.length - 1] === 0) limbs.pop();
}

function divmodSmall(limbs, divisor) {
  let rem = 0;
  for (let i = limbs.length - 1; i >= 0; i--) {
    const cur = rem * LIMB_BASE + limbs[i];
    limbs[i] = Math.floor(cur / divisor);
    rem = cur % divisor;
  }
  trimLimbs(limbs);
  return rem;
}

function convertBase(numStr, baseN, baseM) {
  if (typeof numStr !== 'string') throw new TypeError('numStr must be a string');
  for (const base of [baseN, baseM]) {
    if (!Number.isInteger(base) || base < MIN_BASE || base > MAX_BASE) {
      throw new RangeError(`base ${base} is out of the supported range ${MIN_BASE}..${MAX_BASE}`);
    }
  }
  let body = numStr.trim();
  if (body.length > MAX_INPUT_DIGITS) {
    throw new RangeError(`input exceeds ${MAX_INPUT_DIGITS} digits`);
  }
  let negative = false;
  if (body[0] === '+' || body[0] === '-') {
    negative = body[0] === '-';
    body = body.slice(1);
  }
  if (body.length === 0) throw new SyntaxError('numStr contains no digits');
  const limbs = parseLimbs(body, baseN);
  const out = [];
  while (limbs.length > 0) out.push(DIGITS[divmodSmall(limbs, baseM)]);
  if (out.length === 0) return '0';
  return (negative ? '-' : '') + out.reverse().join('');
}

