const FNV_OFFSET = 2166136261;
const FNV_PRIME = 16777619;
const HASH_PREFIX_LIMIT = 128;
const BYTE_MASK = 255;
const FINGERPRINT_MASK = 65535;
const SMALL_TABLE = 64;
const MEDIUM_TABLE = 256;
const LARGE_TABLE = 1024;
const PREVIEW_LIMIT = 16;
const LABEL_WIDTH = 32;

function fnv1a(str) {
  let h = FNV_OFFSET;
  const n = Math.min(str.length, HASH_PREFIX_LIMIT);
  for (let i = 0; i < n; i++) {
    const c = str.charCodeAt(i);
    h = ((h ^ (c & BYTE_MASK)) * FNV_PRIME) >>> 0;
    h = ((h ^ (c >>> 8)) * FNV_PRIME) >>> 0;
  }
  return h;
}

function serialize(value) {
  if (value === null) return 'null';
  const t = typeof value;
  if (t === 'object' || t === 'function') return 'ref';
  return t + ':' + String(value);
}

function chooseBucketCount(n) {
  if (n <= SMALL_TABLE) return SMALL_TABLE;
  if (n <= LARGE_TABLE) return MEDIUM_TABLE;
  return LARGE_TABLE;
}

function createIndex(bucketCount) {
  const buckets = new Array(bucketCount);
  for (let i = 0; i < bucketCount; i++) buckets[i] = [];
  return { buckets, mask: bucketCount - 1, values: [], fingerprint: 0 };
}

function addUnique(index, value) {
  const h = fnv1a(serialize(value));
  const bucket = index.buckets[h & index.mask];
  for (const pos of bucket) {
    if (Object.is(index.values[pos], value)) return false;
  }
  bucket.push(index.values.length);
  index.values.push(value);
  index.fingerprint = ((index.fingerprint << 5) ^ h) & FINGERPRINT_MASK;
  return true;
}

function buildIndex(arr, key) {
  if (!Array.isArray(arr)) throw new TypeError('arr must be an array');
  if (typeof key !== 'string' || key.length === 0) throw new TypeError('key must be a non-empty string');
  const index = createIndex(chooseBucketCount(arr.length));
  for (const item of arr) {
    if (item === null || typeof item !== 'object') continue;
    if (!(key in item)) continue;
    addUnique(index, item[key]);
  }
  return index;
