'use strict';

function powerRecursive(base, exponent) {
  if (!Number.isInteger(exponent) || exponent < 0) {
    throw new RangeError('exponent must be a non-negative integer');
  }
  if (exponent > 1024) {
    throw new RangeError('exponent too large for recursive evaluation');
  }
  if (exponent === 0) {
    return 1;
  }
  return base * powerRecursive(base, exponent - 1);
}

function toByteArray(value) {
  if (!Number.isInteger(value) || value < 0) {
    throw new RangeError('only non-negative integers can be split into bytes');
  }
  const bytes = [];
  let rest = value;
  while (rest > 0) {
    bytes.unshift(rest & 255);
    rest = Math.floor(rest / 256);
  }
  return bytes.length > 0 ? bytes : [0];
}

function toHex(value, digits) {
  return value.toString(16).padStart(digits, '0');
}

function formatBytes(value) {
  return toByteArray(value).map((b) => toHex(b, 2)).join(' ');
}

function formatWord(value) {
  if (value > 65535) {
    throw new RangeError('value does not fit into a 16-bit word');
  }
  return '0x' + toHex(value, 4);
}

function bitsNeeded(value) {
  let bits = 0;
  while (powerRecursive(2, bits) <= value) {
    bits += 1;
    if (bits > 32) {
      throw new RangeError('value exceeds the 32-bit range');
    }
  }
  return bits;
}

function scaleChannel(fraction) {
  return Math.round(fraction * 255);
}

function blendChannel(a, b, weight) {
  const complement = 255 - weight;
  const total = a * weight + b * complement;
  return Math.round(total / 255);
}

function memoryReport(byteCount) {
  const kib = (byteCount / 1024).toFixed(1);
  const pages = Math.ceil(byteCount / 4096);
  return `${byteCount} bytes (${kib} KiB, ${pages} pages)`;
}

function main() {
  console.log('2^3 =', powerRecursive(2, 3));
  console.log('5^0 =', powerRecursive(5, 0));

  for (let exponent = 8; exponent <= 24; exponent += 8) {
    const value = powerRecursive(2, exponent);
    console.log(`2^${exponent} = ${value}, bits=${bitsNeeded(value)}, bytes=[${formatBytes(value)}]`);
  }

  const wordTop = powerRecursive(2, 16) - 1;
  console.log('word range:', formatWord(0), '..', formatWord(wordTop));

  const pixels = powerRecursive(64, 2);
  console.log(`sprite ${pixels} px RGBA:`, memoryReport(pixels * 4));

  const mid = blendChannel(scaleChannel(1), scaleChannel(0), 128);
  console.log('mid gray channel:', mid, '=> #' + toHex(mid, 2).repeat(3));
}

main();

