const BYTE_MASK = 255;
const BYTE_MODULUS = 256;
const BYTE_SIGN_BIT = 128;
const WORD_MASK = 65535;
const WORD_BITS = 16;
const HEX_RADIX = 16;
const MAX_BITS = 32;
const REPORT_WIDTH = 64;

function cleanBits(binaryStr) {
  if (typeof binaryStr !== 'string') {
    throw new TypeError('binaryStr must be a string');
  }
  const bits = binaryStr.trim().replace(/[\s_]/g, '');
  if (!/^[01]+$/.test(bits)) {
    throw new SyntaxError(`not a binary string: "${binaryStr}"`);
  }
  if (bits.length > MAX_BITS) {
    throw new RangeError(`at most ${MAX_BITS} bits are supported`);
  }
  return bits;
}

function fitToWidth(bits, width) {
  if (bits.length > width) {
    throw new RangeError(`${bits.length} bits do not fit in ${width} bits`);
  }
  return bits.padStart(width, '0');
}

function toUnsigned(bits) {
  let value = 0;
  for (const ch of bits) {
    value = value * 2 + (ch === '1' ? 1 : 0);
  }
  return value;
}

function signedBinaryToDecimal(binaryStr) {
  const value = toUnsigned(fitToWidth(cleanBits(binaryStr), 8)) & BYTE_MASK;
  return (value & BYTE_SIGN_BIT) !== 0 ? value - BYTE_MODULUS : value;
}

function signedWordToDecimal(binaryStr) {
  const value = toUnsigned(fitToWidth(cleanBits(binaryStr), WORD_BITS)) & WORD_MASK;
  const modulus = WORD_MASK + 1;
