'use strict';

const FLETCHER_MODULUS = 255;
const MAX_FRAME_BYTES = 4096;
const CHUNK_SIZE = 1024;
const PREVIEW_BYTES = 32;
const HEX_RADIX = 16;
const CHECKSUM_MASK = 65535;
const BYTE_SCALE = 256;

function areArraysEqualShallow(arr1, arr2) {
  if (!Array.isArray(arr1) || !Array.isArray(arr2)) return false;
  if (arr1 === arr2) return true;
  if (arr1.length !== arr2.length) return false;
  for (let i = 0; i < arr1.length; i++) {
    if (arr1[i] !== arr2[i]) return false;
  }
  return true;
}

function toHexByte(value) {
  return value.toString(HEX_RADIX).padStart(2, '0');
}

function parseHexBytes(text) {
  const cleaned = String(text).replace(/\s+/g, '');
  if (!/^[0-9a-fA-F]*$/.test(cleaned)) throw new Error('payload contains non-hex digits');
  if (cleaned.length % 2 !== 0) throw new Error('hex payload needs an even number of digits');
  if (cleaned.length / 2 > MAX_FRAME_BYTES) throw new Error('frame exceeds ' + MAX_FRAME_BYTES + ' bytes');
  const bytes = [];
  for (let i = 0; i < cleaned.length; i += 2) {
    bytes.push(parseInt(cleaned.slice(i, i + 2), HEX_RADIX));
  }
  return bytes;
}

function fletcher16(bytes) {
  let low = 0;
  let high = 0;
  for (const byte of bytes) {
    low = (low + byte) % FLETCHER_MODULUS;
    high = (high + low) % FLETCHER_MODULUS;
  }
  return (high * BYTE_SCALE + low) & CHECKSUM_MASK;
}

function formatChecksum(sum) {
  return sum.toString(HEX_RADIX).padStart(4, '0');
}

function chunkChecksums(bytes) {
  const sums = [];
  for (let start = 0; start < bytes.length; start += CHUNK_SIZE) {
    sums.push(fletcher16(bytes.slice(start, start + CHUNK_SIZE)));
  }
  return sums;
}

function firstDifference(arr1, arr2) {
  const limit = Math.min(arr1.length, arr2.length);
  for (let i = 0; i < limit; i++) {
    if (arr1[i] !== arr2[i]) return i;
  }
  return -1;
}

function preview(bytes) {
  const head = bytes.slice(0, PREVIEW_BYTES).map(toHexByte).join(' ');
  return bytes.length > PREVIEW_BYTES ? head + ' ...' : head;
}

function describe(label, bytes) {
  return label + ': ' + bytes.length + ' bytes, sum ' + formatChecksum(fletcher16(bytes)) +
    ', head ' + preview(bytes);
}

function compareFrames(hexA, hexB) {
  const a = parseHexBytes(hexA);
  const b = parseHexBytes(hexB);
  const lines = [describe('A', a), describe('B', b)];
  if (areArraysEqualShallow(a, b)) {
    lines.push('frames are shallowly equal');
    return lines.join('\n');
  }
  const index = firstDifference(a, b);
  if (index < 0) {
    lines.push('common prefix, but lengths differ by ' + Math.abs(a.length - b.length) + ' bytes');
  } else {
    lines.push('first difference at byte ' + index + ' in block ' + Math.floor(index / CHUNK_SIZE) +
      ': ' + toHexByte(a[index]) + ' vs ' + toHexByte(b[index]));
  }
  const sumsA = chunkChecksums(a);
  const sumsB = chunkChecksums(b);
  for (let block = 0; block < Math.max(sumsA.length, sumsB.length); block++) {
    if (sumsA[block] !== sumsB[block]) {
      const left = sumsA[block] === undefined ? '----' : formatChecksum(sumsA[block]);
      const right = sumsB[block] === undefined ? '----' : formatChecksum(sumsB[block]);
      lines.push('block ' + block + ': ' + left + ' != ' + right);
    }
  }
  return lines.join('\n');
}

