const MAX_RADIUS = 4096;
const GRID_WIDTH = 64;
const GRID_HEIGHT = 32;
const CELL_SIZE = 16;
const VIEW_WIDTH = GRID_WIDTH * CELL_SIZE;
const VIEW_HEIGHT = GRID_HEIGHT * CELL_SIZE;

function calculateCircleArea(radius) {
  if (typeof radius !== 'number' || !Number.isFinite(radius)) {
    throw new TypeError('radius must be a finite number');
  }
  if (radius <= 0) {
    throw new RangeError('radius must be positive');
  }
  if (radius > MAX_RADIUS) {
    throw new RangeError('radius exceeds ' + MAX_RADIUS + ' world units');
  }
  return Math.PI * radius * radius;
}

function estimateArea(radius, steps = 1024) {
  const step = radius / steps;
  let sum = 0;
  for (let i = 0; i < steps; i++) {
    const x = (i + 0.5) * step;
    sum += Math.sqrt(radius * radius - x * x);
  }
  return 4 * sum * step;
}

function clampChannel(value) {
  return Math.max(0, Math.min(255, Math.round(value)));
}

function packRgb565(red, green, blue) {
  const r = clampChannel(red) >> 3;
  const g = clampChannel(green) >> 2;
  const b = clampChannel(blue) >> 3;
  return ((r << 11) | (g << 5) | b) & 65535;
}

function circleColor(radius) {
  const t = Math.min(1, radius / MAX_RADIUS);
  const red = 255 * t;
  const green = 128 * (1 - t);
  const blue = 200 * (1 - t);
  return packRgb565(red, green, blue);
}

function formatColor(value) {
  return '0x' + value.toString(16).padStart(4, '0');
}

function renderCircle(radius) {
  const rows = [];
  let filled = 0;
  for (let row = 0; row < GRID_HEIGHT; row++) {
    const y = (row + 0.5) * CELL_SIZE - VIEW_HEIGHT / 2;
    let line = '';
    for (let col = 0; col < GRID_WIDTH; col++) {
      const x = (col + 0.5) * CELL_SIZE - VIEW_WIDTH / 2;
      const inside = x * x + y * y <= radius * radius;
      if (inside) filled++;
      line += inside ? '#' : '.';
    }
    rows.push(line);
  }
  return { rows, rasterArea: filled * CELL_SIZE * CELL_SIZE };
}

function report(radius) {
  const exact = calculateCircleArea(radius);
  const { rows, rasterArea } = renderCircle(radius);
  console.log('radius ' + radius + '  color ' + formatColor(circleColor(radius)));
  console.log('  exact      ' + exact);
  console.log('  quadrature ' + estimateArea(radius));
  console.log('  raster     ' + rasterArea + ' (cells of ' + CELL_SIZE * CELL_SIZE + ' units^2)');
  console.log(rows.join('\n'));
}

for (const radius of [1, 2, 64, 320]) {
  report(radius);
}

