const MAX_ADDRESS_LENGTH = 255;
const MAX_LOCAL_LENGTH = 64;
const MIN_PRINTABLE_CODE = 32;
const ASCII_CODE_LIMIT = 128;
const DISPLAY_WIDTH = 32;

function hasOnlyPrintableAscii(text) {
  let index = text.length;
  while (index--) {
    const code = text.charCodeAt(index);
    if (code < MIN_PRINTABLE_CODE || code >= ASCII_CODE_LIMIT) {
      return false;
    }
  }
  return true;
}

function splitAddress(email) {
  const [local, ...rest] = email.split('@');
  const domain = rest.join('@');
  if (!rest.length || domain.includes('@') || !domain.includes('.')) {
    return null;
  }
  return { local, domain };
}

function lengthProblem(email, parts) {
  if (email.length > MAX_ADDRESS_LENGTH) {
    return 'address is too long';
  }
  if (!parts.local) {
    return 'local part is empty';
  }
  if (parts.local.length > MAX_LOCAL_LENGTH) {
    return 'local part is too long';
  }
  return null;
}

function describeProblem(email) {
  if (typeof email !== 'string') {
    return 'input is not a string';
  }
  const trimmed = email.trim();
  if (!trimmed) {
    return 'address is empty';
  }
  if (!hasOnlyPrintableAscii(trimmed)) {
    return 'contains control or non-ASCII characters';
  }
  const parts = splitAddress(trimmed);
  if (parts === null) {
